// Thai Baht Text Converter
function thaiBahtText(num) {
    if (num === null || num === undefined || isNaN(num)) return 'ศูนย์บาทถ้วน';
    const n = parseFloat(num);
    if (n === 0) return 'ศูนย์บาทถ้วน';
    
    const formatted = Math.abs(n).toFixed(2);
    const [intPart, decPart] = formatted.split('.');
    
    const digits = ['ศูนย์', 'หนึ่ง', 'สอง', 'สาม', 'สี่', 'ห้า', 'หก', 'เจ็ด', 'แปด', 'เก้า'];
    const units = ['', 'สิบ', 'ร้อย', 'พัน', 'หมื่น', 'แสน'];
    
    function convertGroup(str) {
        let res = '';
        const len = str.length;
        for (let i = 0; i < len; i++) {
            const d = parseInt(str[i]);
            const pos = len - i - 1;
            if (d !== 0) {
                if (pos === 1 && d === 1) {
                    res += 'สิบ';
                } else if (pos === 1 && d === 2) {
                    res += 'ยี่สิบ';
                } else if (pos === 0 && d === 1 && len > 1 && str[len - 2] !== '0') {
                    res += 'เอ็ด';
                } else {
                    res += digits[d] + units[pos];
                }
            }
        }
        return res;
    }

    let bahtText = '';
    let remaining = intPart;
    let millionGroups = [];
    while (remaining.length > 6) {
        millionGroups.unshift(remaining.slice(-6));
        remaining = remaining.slice(0, -6);
    }
    millionGroups.unshift(remaining);

    for (let g = 0; g < millionGroups.length; g++) {
        const groupText = convertGroup(millionGroups[g]);
        if (groupText) {
            bahtText += groupText + (g < millionGroups.length - 1 ? 'ล้าน' : '');
        }
    }

    let result = (n < 0 ? 'ลบ' : '') + bahtText + 'บาท';
    const decNum = parseInt(decPart);
    if (decNum === 0) {
        result += 'ถ้วน';
    } else {
        result += convertGroup(decPart) + 'สตางค์';
    }
    return result;
}

// Thai Date Helpers
const THAI_MONTHS_FULL = ['มกราคม', 'กุมภาพันธ์', 'มีนาคม', 'เมษายน', 'พฤษภาคม', 'มิถุนายน', 'กรกฎาคม', 'สิงหาคม', 'กันยายน', 'ตุลาคม', 'พฤศจิกายน', 'ธันวาคม'];
const THAI_MONTHS_SHORT = ['ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.', 'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'];

function formatThaiDateFull(dateObjOrStr) {
    if (!dateObjOrStr) return '';
    const d = new Date(dateObjOrStr);
    if (isNaN(d.getTime())) return dateObjOrStr;
    const day = d.getDate();
    const month = THAI_MONTHS_FULL[d.getMonth()];
    const year = d.getFullYear() + 543;
    return `${day} เดือน ${month} พ.ศ. ${year}`;
}

function formatThaiDateShort(dateObjOrStr) {
    if (!dateObjOrStr) return '';
    const d = new Date(dateObjOrStr);
    if (isNaN(d.getTime())) return dateObjOrStr;
    const day = d.getDate();
    const month = THAI_MONTHS_SHORT[d.getMonth()];
    const year = (d.getFullYear() + 543).toString().slice(-2);
    return `${day} ${month} ${year}`;
}

// Convert ISO (YYYY-MM-DD) or Date to Thai BE string "DD/MM/YYYY" (เช่น 29/05/2569)
function formatThaiBEDate(dateObjOrStr) {
    if (!dateObjOrStr) return '';
    const d = new Date(dateObjOrStr);
    if (isNaN(d.getTime())) return '';
    const dd = String(d.getDate()).padStart(2, '0');
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const yyyy = d.getFullYear() + 543;
    return `${dd}/${mm}/${yyyy}`;
}

// Convert Thai BE string "DD/MM/YYYY" (เช่น 29/05/2569) to ISO "YYYY-MM-DD"
function parseThaiBEToISO(thaiStr) {
    if (!thaiStr) return null;
    const clean = thaiStr.trim().replace(/-/g, '/');
    const parts = clean.split('/');
    if (parts.length !== 3) return null;
    const d = parseInt(parts[0]);
    const m = parseInt(parts[1]);
    let y = parseInt(parts[2]);
    if (isNaN(d) || isNaN(m) || isNaN(y)) return null;
    if (d < 1 || d > 31 || m < 1 || m > 12) return null;
    
    // If year is BE (e.g. 2568, 2569) convert to CE
    if (y > 2400) {
        y = y - 543;
    }
    const iso = `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
    const testDate = new Date(iso);
    if (isNaN(testDate.getTime())) return null;
    return iso;
}

// Parse various Thai Date strings ("3 พ.ย. 68", "03/11/2568", "2025-11-03") to JS Date
function parseThaiDateShort(thaiStr) {
    if (!thaiStr || typeof thaiStr !== 'string') return null;
    const clean = thaiStr.trim();
    if (!clean) return null;

    // Check ISO (YYYY-MM-DD)
    if (/^\d{4}-\d{2}-\d{2}$/.test(clean)) {
        const parts = clean.split('-');
        return new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2]), 12, 0, 0);
    }

    // Check DD/MM/YYYY or DD-MM-YYYY
    const slashParts = clean.replace(/-/g, '/').split('/');
    if (slashParts.length === 3) {
        const d = parseInt(slashParts[0]);
        const m = parseInt(slashParts[1]);
        let y = parseInt(slashParts[2]);
        if (!isNaN(d) && !isNaN(m) && !isNaN(y)) {
            if (y > 2400) y -= 543;
            else if (y < 100) y += 2000;
            return new Date(y, m - 1, d, 12, 0, 0);
        }
    }

    // Check "3 พ.ย. 68" or "03 พ.ย. 2568" or "3 พฤศจิกายน 2568"
    const spaceParts = clean.split(/\s+/);
    if (spaceParts.length >= 3) {
        const d = parseInt(spaceParts[0]);
        const mStr = spaceParts[1];
        let y = parseInt(spaceParts[2]);
        if (!isNaN(d) && !isNaN(y)) {
            let mIdx = THAI_MONTHS_SHORT.indexOf(mStr);
            if (mIdx === -1) mIdx = THAI_MONTHS_FULL.indexOf(mStr);
            if (mIdx !== -1) {
                if (y < 100) y += 2500;
                const ceYear = y > 2400 ? y - 543 : y;
                return new Date(ceYear, mIdx, d, 12, 0, 0);
            }
        }
    }

    const testD = new Date(clean);
    if (!isNaN(testD.getTime())) {
        testD.setHours(12, 0, 0, 0);
        return testD;
    }
    return null;
}

// Check if a holiday reason string matches official public holidays
function isKnownThaiHolidayReason(reason) {
    if (!reason || typeof reason !== 'string') return false;
    const r = reason.trim();
    if (!r) return false;
    for (const k in FIXED_THAI_HOLIDAYS) {
        if (FIXED_THAI_HOLIDAYS[k] && (r.includes(FIXED_THAI_HOLIDAYS[k]) || FIXED_THAI_HOLIDAYS[k].includes(r))) return true;
    }
    for (const k in LUNAR_THAI_HOLIDAYS) {
        if (LUNAR_THAI_HOLIDAYS[k] && (r.includes(LUNAR_THAI_HOLIDAYS[k]) || LUNAR_THAI_HOLIDAYS[k].includes(r))) return true;
    }
    const keywords = ['วันพ่อ', 'วันแม่', 'วันขึ้นปีใหม่', 'วันสิ้นปี', 'วันรัฐธรรมนูญ', 'วันสงกรานต์', 'วันจักรี', 'วันมาฆบูชา', 'วันวิสาขบูชา', 'วันอาสาฬหบูชา', 'วันเข้าพรรษา', 'วันปิยมหาราช', 'วันนวมินทร', 'ชดเชย', 'วันหยุด'];
    return keywords.some(kw => r.includes(kw));
}

