function getThaiHoliday(dateObjOrStr) {
    if (!dateObjOrStr) return null;
    const d = new Date(dateObjOrStr);
    if (isNaN(d.getTime())) return null;

    const yyyy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const dd = String(d.getDate()).padStart(2, '0');
    const fullIso = `${yyyy}-${mm}-${dd}`;
    const md = `${mm}-${dd}`;

    if (LUNAR_THAI_HOLIDAYS[fullIso]) {
        return { name: LUNAR_THAI_HOLIDAYS[fullIso] };
    }
    if (FIXED_THAI_HOLIDAYS[md]) {
        return { name: FIXED_THAI_HOLIDAYS[md] };
    }

    // Check Monday substitutions if holiday fell on Sat/Sun
    if (d.getDay() === 1) {
        const sun = new Date(d);
        sun.setDate(d.getDate() - 1);
        const sunMD = `${String(sun.getMonth() + 1).padStart(2, '0')}-${String(sun.getDate()).padStart(2, '0')}`;
        if (FIXED_THAI_HOLIDAYS[sunMD]) {
            return { name: `ชดเชย${FIXED_THAI_HOLIDAYS[sunMD]}` };
        }
        const sat = new Date(d);
        sat.setDate(d.getDate() - 2);
        const satMD = `${String(sat.getMonth() + 1).padStart(2, '0')}-${String(sat.getDate()).padStart(2, '0')}`;
        if (FIXED_THAI_HOLIDAYS[satMD]) {
            return { name: `ชดเชย${FIXED_THAI_HOLIDAYS[satMD]}` };
        }
    }

    return null;
}

// ย่อชื่อวันหยุดให้สั้นลงไม่เกิน 2 บรรทัด
function shortenHolidayName(name) {
    if (!name) return "";
    let str = name.trim();

    const dict = [
        { pattern: /วันคล้ายวันพระบรมราชสมภพ.*วันพ่อแห่งชาติ/i, rep: "วันพ่อแห่งชาติ (วันชาติ)" },
        { pattern: /วันคล้ายวันสวรรคต.*มหาภูมิพลอดุลยเดชมหาราช/i, rep: "วันนวมินทรมหาราช (ร.9)" },
        { pattern: /วันเฉลิมพระชนมพรรษา.*พระวชิรเกล้าเจ้าอยู่หัว/i, rep: "วันเฉลิมฯ ร.10" },
        { pattern: /วันเฉลิมพระชนมพรรษา.*พระเจ้าอยู่หัว/i, rep: "วันเฉลิมฯ ร.10" },
        { pattern: /วันเฉลิมพระชนมพรรษา.*พันปีหลวง.*วันแม่/i, rep: "วันแม่แห่งชาติ" },
        { pattern: /วันเฉลิมพระชนมพรรษา.*พระบรมราชินีนาถ/i, rep: "วันแม่แห่งชาติ" },
        { pattern: /วันเฉลิมพระชนมพรรษา.*พระบรมราชินี/i, rep: "วันเฉลิมฯ พระราชินี" },
        { pattern: /วันพระบาทสมเด็จพระพุทธยอดฟ้าจุฬาโลกมหาราช.*มหาจักรีบรมราชวงศ์/i, rep: "วันจักรี" },
        { pattern: /พระราชพิธีพืชมงคลจรดพระนังคัลแรกนาขวัญ/i, rep: "วันพืชมงคล" }
    ];

    for (const item of dict) {
        if (item.pattern.test(str)) {
            str = item.rep;
            break;
        }
    }

    if (str.length > 30) {
        str = str.slice(0, 28) + '...';
    }
    return str;
}

