// Global Active Claim Data
let activeClaim = null;
let activeSubjectRef = null;

// -------------------------------------------------------------------------
// SIGNATURES 2-9 DEFAULT INHERITANCE SYSTEM
// -------------------------------------------------------------------------
function getFormattedDeptRole(deptName, roleType = 'deptHead') {
    let d = (deptName || '').trim();
    if (!d) d = 'เทคโนโลยีโยธา';
    if (d.startsWith('สาขาวิชา')) {
        d = d.replace(/^สาขาวิชา/, '').trim();
    } else if (d.startsWith('สาขา')) {
        d = d.replace(/^สาขา/, '').trim();
    }
    if (!d.startsWith('เทคโนโลยี')) {
        d = 'เทคโนโลยี' + d;
    }
    if (roleType === 'programChair') {
        return `ประธานหลักสูตรสาขาวิชา${d}`;
    }
    return `หัวหน้าสาขาวิชา${d}`;
}

function extractSignatures2To9(sig, deptName = '') {
    if (!sig) return {};
    return {
        programChair: sig.programChair || '',
        programChairRole: sig.programChairRole || getFormattedDeptRole(deptName, 'programChair'),
        curriculumHead: sig.curriculumHead || '',
        curriculumHeadRole: sig.curriculumHeadRole || 'หัวหน้างานพัฒนาหลักสูตรสายเทคโนโลยีฯ',
        deptHead: sig.deptHead || '',
        deptHeadRole: sig.deptHeadRole || getFormattedDeptRole(deptName, 'deptHead'),
        techHead: sig.techHead || '',
        techHeadRole: sig.techHeadRole || 'หัวหน้างานภาควิชาเทคโนโลยีบัณฑิต',
        academicDeputy: sig.academicDeputy || '',
        academicDeputyRole: sig.academicDeputyRole || 'รองผู้อำนวยการฝ่ายวิชาการ',
        financeHead: sig.financeHead || '',
        financeHeadRole: sig.financeHeadRole || 'หัวหน้าการเงิน',
        resourceDeputy: sig.resourceDeputy || '',
        resourceDeputyRole: sig.resourceDeputyRole || 'รองผู้อำนวยการฝ่ายบริหารทรัพยากร',
        director: sig.director || '',
        directorRole: sig.directorRole || 'ผู้อำนวยการวิทยาลัยเทคนิคอุบลราชธานี'
    };
}

function getDefaultSignatures2To9() {
    // 1. Check if already saved in appData
    if (typeof appData !== 'undefined' && appData && appData.defaultSignatures2To9) {
        const d = appData.defaultSignatures2To9;
        if (d.director || d.academicDeputy || d.deptHead || d.programChair || d.curriculumHead) {
            return JSON.parse(JSON.stringify(d));
        }
    }

    // 2. Pull from the first created term (appData.terms[0])
    if (typeof appData !== 'undefined' && appData && appData.terms && appData.terms.length > 0) {
        const firstTerm = appData.terms[0];
        if (firstTerm && firstTerm.subjects) {
            for (const sub of firstTerm.subjects) {
                if (sub.claimData && sub.claimData.signatures) {
                    const s = sub.claimData.signatures;
                    if (s.director || s.academicDeputy || s.deptHead || s.programChair || s.curriculumHead) {
                        const extracted = extractSignatures2To9(s);
                        appData.defaultSignatures2To9 = extracted;
                        if (typeof saveData === 'function') saveData();
                        return JSON.parse(JSON.stringify(extracted));
                    }
                }
            }
        }

        // Fallback: check any term
        for (const t of appData.terms) {
            if (t.subjects) {
                for (const sub of t.subjects) {
                    if (sub.claimData && sub.claimData.signatures) {
                        const s = sub.claimData.signatures;
                        if (s.director || s.academicDeputy || s.deptHead || s.programChair || s.curriculumHead) {
                            const extracted = extractSignatures2To9(s);
                            appData.defaultSignatures2To9 = extracted;
                            if (typeof saveData === 'function') saveData();
                            return JSON.parse(JSON.stringify(extracted));
                        }
                    }
                }
            }
        }
    }

    // 3. Fallback to DEFAULT_RC_CLAIM
    const fallback = extractSignatures2To9(typeof DEFAULT_RC_CLAIM !== 'undefined' ? DEFAULT_RC_CLAIM.signatures : null);
    if (typeof appData !== 'undefined' && appData) {
        appData.defaultSignatures2To9 = fallback;
        if (typeof saveData === 'function') saveData();
    }
    return JSON.parse(JSON.stringify(fallback));
}

function updateDefaultSignatures2To9(sig) {
    if (typeof appData === 'undefined' || !appData) return;
    if (!appData.defaultSignatures2To9) {
        appData.defaultSignatures2To9 = getDefaultSignatures2To9();
    }
    const keys = [
        'programChair', 'programChairRole',
        'curriculumHead', 'curriculumHeadRole',
        'deptHead', 'deptHeadRole',
        'techHead', 'techHeadRole',
        'academicDeputy', 'academicDeputyRole',
        'financeHead', 'financeHeadRole',
        'resourceDeputy', 'resourceDeputyRole',
        'director', 'directorRole'
    ];
    keys.forEach(k => {
        if (sig && sig[k] !== undefined) {
            appData.defaultSignatures2To9[k] = sig[k];
        }
    });
    if (typeof saveData === 'function') saveData();
}

function saveActiveClaim() {
    if (typeof activeSubjectRef !== 'undefined' && activeSubjectRef && typeof activeClaim !== 'undefined' && activeClaim) {
        activeSubjectRef.claimData = JSON.parse(JSON.stringify(activeClaim));
    }
    if (typeof saveData === 'function') saveData();
}


// Ensure teachingDays array is structured properly for any daysPerWeek (1..7)
function ensureTeachingDays(claim = activeClaim) {
    if (!claim) return;
    const n = Math.max(1, Math.min(7, parseInt(claim.teachingDaysPerWeek) || 1));
    claim.teachingDaysPerWeek = n;
    claim.totalWeeks = Math.ceil(18 / n);

    if (!Array.isArray(claim.teachingDays)) {
        claim.teachingDays = [];
    }

    const defaultDows = ["1", "2", "3", "4", "5", "6", "0"]; // Mon to Sun
    const defaultTime = claim.timeStr || "17.00-20.00";
    const defaultHrs = claim.weeklyHours || 3;

    while (claim.teachingDays.length < n) {
        const i = claim.teachingDays.length;
        let dow = defaultDows[i % 7];
        let time = defaultTime;
        let hrs = defaultHrs;
        if (i === 0 && claim.day1DOW !== undefined) {
            dow = claim.day1DOW;
            time = claim.day1Time || defaultTime;
            hrs = claim.day1Hours || defaultHrs;
        } else if (i === 1 && claim.day2DOW !== undefined) {
            dow = claim.day2DOW;
            time = claim.day2Time || defaultTime;
            hrs = claim.day2Hours || defaultHrs;
        }
        claim.teachingDays.push({
            dow: String(dow),
            time: time,
            hours: parseInt(hrs) || 3
        });
    }

    if (claim.teachingDays.length > n) {
        claim.teachingDays = claim.teachingDays.slice(0, n);
    }
}

// Calculate schedule (18 sessions across totalWeeks) based on start date, days per week, and day configs
function generateScheduleForClaim(claim = activeClaim, preserveExistingHolidays = false, masterSub = null, term = null) {
    if (!claim) return;
    ensureTeachingDays(claim);
    const n = claim.teachingDaysPerWeek || 1;
    const totalWeeks = Math.ceil(18 / n);
    claim.totalWeeks = totalWeeks;

    // Parse start date safely at noon to avoid any timezone/DST drift
    let start = null;
    if (claim.startDate) {
        const parts = claim.startDate.split('-');
        if (parts.length === 3) {
            start = new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2]), 12, 0, 0);
        } else {
            start = new Date(claim.startDate);
            start.setHours(12, 0, 0, 0);
        }
    }
    if (!start || isNaN(start.getTime())) {
        start = new Date(2025, 10, 3, 12, 0, 0); // Default 2025-11-03
    }

    // Map existing manual custom holidays BY DATE (NOT by array index s!)
    // so if slots shift, custom holidays attach to their real date, not fixed in wrong box!
    const customHolidaysByDate = {};
    if (preserveExistingHolidays && claim.weeks && Array.isArray(claim.weeks)) {
        claim.weeks.forEach(w => {
            if (w.isHoliday && w.dateStr && w.holidayReason) {
                customHolidaysByDate[w.dateStr] = w.holidayReason;
                if (w.isoDate) customHolidaysByDate[w.isoDate] = w.holidayReason;
            }
        });
    }

    const newWeeks = [];
    let lastDate = null;

    // Align Day 1 DOW
    const d1Dow = parseInt(claim.teachingDays[0].dow);

    // If start date's day of week does not match Day 1 DOW, shift start date forward to match Day 1 DOW
    if (start.getDay() !== d1Dow) {
        const diff = (d1Dow - start.getDay() + 7) % 7;
        start.setDate(start.getDate() + diff);
        const yyyy = start.getFullYear();
        const mm = String(start.getMonth() + 1).padStart(2, '0');
        const dd = String(start.getDate()).padStart(2, '0');
        claim.startDate = `${yyyy}-${mm}-${dd}`;
        const elStart = document.getElementById('claim-input-start-date');
        if (elStart) elStart.value = claim.startDate;
        const elStartTh = document.getElementById('claim-input-start-date-th');
        if (elStartTh) elStartTh.value = formatThaiBEDate(claim.startDate);
    }

    const mSub = masterSub || (appData.subjects_master || []).find(s => s.code === claim.subjectCode || s.name === claim.subjectName);
    const thHours = (claim.theoryHours !== undefined) ? claim.theoryHours : (mSub && mSub.theoryHours !== undefined ? mSub.theoryHours : 3);
    const prHours = (claim.practiceHours !== undefined) ? claim.practiceHours : (mSub && mSub.practiceHours !== undefined ? mSub.practiceHours : 0);
    claim.theoryHours = thHours;
    claim.practiceHours = prHours;

    // Generate 18 sessions
    for (let s = 0; s < 18; s++) {
        const weekIdx = Math.floor(s / n); // 0-indexed week (0 to totalWeeks - 1)
        const dayIdx = s % n; // 0-indexed day within the week (0 to n - 1)
        const dayConf = claim.teachingDays[dayIdx] || claim.teachingDays[0];
        const targetDow = parseInt(dayConf.dow);

        // Calculate day offset from Day 1 within the same week
        // Order: Mon=1, Tue=2, Wed=3, Thu=4, Fri=5, Sat=6, Sun=7
        const d1Order = d1Dow === 0 ? 7 : d1Dow;
        const targetOrder = targetDow === 0 ? 7 : targetDow;
        let dayOffsetInWeek = targetOrder >= d1Order ? (targetOrder - d1Order) : (targetOrder - d1Order + 7);

        const sessionDate = new Date(start);
        sessionDate.setDate(start.getDate() + (weekIdx * 7) + dayOffsetInWeek);

        const dateStr = formatThaiDateShort(sessionDate);
        const yyyy = sessionDate.getFullYear();
        const mm = String(sessionDate.getMonth() + 1).padStart(2, '0');
        const dd = String(sessionDate.getDate()).padStart(2, '0');
        const isoDate = `${yyyy}-${mm}-${dd}`;

        const hrs = parseInt(dayConf.hours) || parseInt(claim.weeklyHours) || 3;
        const timeStr = dayConf.time || claim.timeStr || "17.00-20.00";

        // Check official Thai public holidays on this session's actual date
        const thaiHoliday = getThaiHoliday(sessionDate);
        let isHoli = false;
        let reason = "";

        if (thaiHoliday) {
            // Official public holiday on this specific date
            isHoli = true;
            reason = shortenHolidayName(thaiHoliday.name);
        } else if (preserveExistingHolidays && (customHolidaysByDate[dateStr] || customHolidaysByDate[isoDate])) {
            // User had manually set a custom holiday on this specific date
            isHoli = true;
            reason = customHolidaysByDate[dateStr] || customHolidaysByDate[isoDate];
        }

        // Check teacher leave / official travel for this teacher and date
        const teacherLeave = getTeacherLeaveForSession(claim, isoDate, term);
        if (teacherLeave) {
            isHoli = true;
            reason = teacherLeave.type || "ไปราชการ";
        }

        let sessionTh = thHours;
        let sessionPr = prHours;
        let sessionTotal = thHours + prHours;

        if (n === 1) {
            sessionTh = thHours;
            sessionPr = prHours;
            sessionTotal = thHours + prHours;
        } else {
            const dayHrs = parseInt(dayConf.hours) || parseInt(claim.weeklyHours) || 3;
            sessionTotal = dayHrs;
            if (thHours + prHours === dayHrs) {
                sessionTh = thHours;
                sessionPr = prHours;
            } else {
                if (dayIdx === 0) {
                    sessionTh = Math.min(dayHrs, thHours);
                    sessionPr = dayHrs - sessionTh;
                } else {
                    sessionPr = Math.min(dayHrs, prHours);
                    sessionTh = dayHrs - sessionPr;
                }
            }
        }

        newWeeks.push({
            weekNo: weekIdx + 1,
            dayNo: dayIdx + 1,
            sessionNo: s + 1,
            dateStr: dateStr,
            isoDate: isoDate,
            timeStr: timeStr,
            theoryHrs: isHoli ? 0 : sessionTh,
            practiceHrs: isHoli ? 0 : sessionPr,
            totalHrs: isHoli ? 0 : sessionTotal,
            isHoliday: isHoli,
            holidayReason: reason
        });

        if (!lastDate || sessionDate > lastDate) {
            lastDate = sessionDate;
        }
    }

    if (lastDate) {
        claim.endDateThai = formatThaiDateFull(lastDate);
    }

    claim.weeks = newWeeks;
}

function recalculateClaimSchedule(preserveExistingHolidays = true) {
    if (!activeClaim) return;
    ensureTeachingDays(activeClaim);
    generateScheduleForClaim(activeClaim, preserveExistingHolidays);
    const elEndDate = document.getElementById('claim-input-end-date');
    if (elEndDate) elEndDate.value = activeClaim.endDateThai;
}

function createInitialSubjectClaimData(term, masterSub, teacher = null) {
    const termYearFull = term ? `${term.no}/${term.year || '2568'}` : '1/2568';
    const c = JSON.parse(JSON.stringify(DEFAULT_RC_CLAIM));
    
    // ข้อ 2-9 ดึงมาจากเทอมแรกที่สร้าง (หรือค่าเริ่มต้นที่จดจำไว้) เสมอ
    const defSig2To9 = getDefaultSignatures2To9();
    if (!c.signatures) c.signatures = {};
    Object.assign(c.signatures, defSig2To9);

    // Check if sibling subject in the same term has settings we should inherit
    const siblingWithClaim = (term && term.subjects) ? term.subjects.find(s => s.claimData && s.claimData.weeks && s.claimData.weeks.length > 0) : null;
    
    if (siblingWithClaim && siblingWithClaim.claimData) {
        const sc = siblingWithClaim.claimData;
        if (sc.startDate) c.startDate = sc.startDate;
        if (sc.endDateThai) c.endDateThai = sc.endDateThai;
        if (sc.curriculum) c.curriculum = sc.curriculum;
        if (sc.department) c.department = sc.department;
        if (sc.level) c.level = sc.level;
        if (sc.teachingDaysPerWeek) c.teachingDaysPerWeek = sc.teachingDaysPerWeek;
        if (sc.totalWeeks) c.totalWeeks = sc.totalWeeks;
        if (sc.teachingDays && Array.isArray(sc.teachingDays)) {
            c.teachingDays = JSON.parse(JSON.stringify(sc.teachingDays));
        }
        if (sc.day1DOW !== undefined) c.day1DOW = sc.day1DOW;
        if (sc.day1Time !== undefined) c.day1Time = sc.day1Time;
        if (sc.day1Hours !== undefined) c.day1Hours = sc.day1Hours;
        if (sc.day2DOW !== undefined) c.day2DOW = sc.day2DOW;
        if (sc.day2Time !== undefined) c.day2Time = sc.day2Time;
        if (sc.day2Hours !== undefined) c.day2Hours = sc.day2Hours;
        if (sc.summerTableLayout) c.summerTableLayout = sc.summerTableLayout;
        if (sc.signatures) {
            const sib2To9 = extractSignatures2To9(sc.signatures, c.department);
            Object.assign(c.signatures, sib2To9);
        }
        if (sc.students && sc.students.length > 0) {
            c.students = JSON.parse(JSON.stringify(sc.students));
        }
    }

    const curDept = c.department || 'เทคโนโลยีโยธา';
    if (!c.signatures.deptHeadRole || (c.signatures.deptHeadRole.includes('โยธา') && !curDept.includes('โยธา'))) {
        c.signatures.deptHeadRole = getFormattedDeptRole(curDept, 'deptHead');
    }
    if (!c.signatures.programChairRole || (c.signatures.programChairRole.includes('โยธา') && !curDept.includes('โยธา'))) {
        c.signatures.programChairRole = getFormattedDeptRole(curDept, 'programChair');
    }

    c.academicYear = termYearFull;
    c.subjectCode = masterSub.code || c.subjectCode;
    c.subjectName = masterSub.name || c.subjectName;
    c.credits = masterSub.credits || 3;
    
    const th = masterSub.theoryHours !== undefined ? masterSub.theoryHours : 3;
    const pr = masterSub.practiceHours !== undefined ? masterSub.practiceHours : 0;
    const weeklyHours = masterSub.hours || (th + pr) || 3;
    c.theoryHours = th;
    c.practiceHours = pr;
    c.weeklyHours = weeklyHours;
    if (c.teachingDays && c.teachingDays[0]) {
        c.teachingDays[0].hours = weeklyHours;
    }
    c.day1Hours = weeklyHours;
    if (weeklyHours === 4 && (c.timeStr === '17.00-20.00' || !c.timeStr || c.day1Time === '17.00-20.00')) {
        c.timeStr = '17.00-21.00';
        c.day1Time = '17.00-21.00';
        if (c.teachingDays && c.teachingDays[0]) c.teachingDays[0].time = '17.00-21.00';
    }
    c.rate = (term && term.hourlyRate) ? term.hourlyRate : 42;

    if (teacher && teacher.name) {
        c.teacherName = teacher.name;
        if (!c.signatures) c.signatures = {};
        c.signatures.teacher = teacher.name;
    } else {
        c.teacherName = '';
        if (c.signatures) delete c.signatures.teacher;
    }

    if ((!c.students || c.students.length === 0) && appData.students && appData.students.length > 0) {
        c.students = appData.students.map(st => {
            const parts = st.name.trim().split(' ');
            return {
                studentId: st.studentId || '',
                name: parts[0] || '',
                surname: parts.slice(1).join(' ') || ''
            };
        });
    }

    generateScheduleForClaim(c, false, masterSub, term);

    return c;
}

// Fallback helper for backward compatibility
function generate18WeeksFromDate(startDateStr, weeklyHours = 3, timeStr = "17.00-20.00") {
    if (activeClaim) {
        activeClaim.startDate = startDateStr;
        activeClaim.timeStr = timeStr;
        activeClaim.weeklyHours = weeklyHours;
        recalculateClaimSchedule(false);
        return activeClaim.weeks;
    }
    return [];
}

// Load and Render Claim Form
function loadAndRenderClaimForm(termId, subjectId) {
    const term = appData.terms.find(t => t.id === termId);
    if (!term) return switchView('semesters');
    
    const sub = term.subjects.find(s => s.id === subjectId);
    if (!sub) return switchView('subjects', termId);
    
    activeSubjectRef = sub;

    const termYearFull = term ? `${term.no}/${term.year || '2568'}` : '1/2568';

    // Load or initialize claimData
    if (sub.claimData) {
        activeClaim = JSON.parse(JSON.stringify(sub.claimData));
        // ซิงค์ปีการศึกษาและระดับชั้น
        if (!activeClaim.academicYear || activeClaim.academicYear === '1/68') {
            activeClaim.academicYear = termYearFull;
            sub.claimData.academicYear = termYearFull;
        }
        if (sub.level && !activeClaim.level) {
            activeClaim.level = sub.level;
            sub.claimData.level = sub.level;
        }
        // ตรวจสอบและดึงลายเซ็นต์ ข้อ 2-9 จากเทอมแรก/ค่าเริ่มต้นหากยังว่างอยู่
        const defSig2To9 = getDefaultSignatures2To9();
        if (!activeClaim.signatures) activeClaim.signatures = {};
        const sigKeys2To9 = ['programChair', 'curriculumHead', 'deptHead', 'techHead', 'academicDeputy', 'financeHead', 'resourceDeputy', 'director'];
        let updatedSigFields = false;
        sigKeys2To9.forEach(k => {
            if (!activeClaim.signatures[k] && defSig2To9[k]) {
                activeClaim.signatures[k] = defSig2To9[k];
                updatedSigFields = true;
            }
            const rk = k + 'Role';
            if (!activeClaim.signatures[rk] && defSig2To9[rk]) {
                activeClaim.signatures[rk] = defSig2To9[rk];
                updatedSigFields = true;
            }
        });

        // อัปเดตชื่อตำแหน่งหัวหน้าสาขา/ประธานหลักสูตร ให้ตรงกับสาขาวิชาของรายวิชานี้โดยอัตโนมัติ
        const curSubjectDept = activeClaim.department || sub.department || 'เทคโนโลยีโยธา';
        const expectedDHRole = getFormattedDeptRole(curSubjectDept, 'deptHead');
        const expectedPCRole = getFormattedDeptRole(curSubjectDept, 'programChair');
        if (!activeClaim.signatures.deptHeadRole || (activeClaim.signatures.deptHeadRole.includes('โยธา') && !curSubjectDept.includes('โยธา'))) {
            activeClaim.signatures.deptHeadRole = expectedDHRole;
            updatedSigFields = true;
        }
        if (!activeClaim.signatures.programChairRole || (activeClaim.signatures.programChairRole.includes('โยธา') && !curSubjectDept.includes('โยธา'))) {
            activeClaim.signatures.programChairRole = expectedPCRole;
            updatedSigFields = true;
        }

        if (updatedSigFields && sub.claimData) {
            sub.claimData.signatures = JSON.parse(JSON.stringify(activeClaim.signatures));
            saveData();
        }

        // ซิงค์ชั่วโมง ท และ ป จากคลังรายวิชา Master
        const masterSub = (appData.subjects_master || []).find(s => s.id === sub.subjectId || s.code === activeClaim.subjectCode || s.name === activeClaim.subjectName);
        if (masterSub) {
            if (activeClaim.theoryHours === undefined) {
                activeClaim.theoryHours = masterSub.theoryHours !== undefined ? masterSub.theoryHours : 3;
            }
            if (activeClaim.practiceHours === undefined) {
                activeClaim.practiceHours = masterSub.practiceHours !== undefined ? masterSub.practiceHours : 0;
            }
            const expectedWeekly = masterSub.hours || (activeClaim.theoryHours + activeClaim.practiceHours);
            if (!activeClaim.weeklyHours || (activeClaim.teachingDaysPerWeek === 1 && activeClaim.weeklyHours !== expectedWeekly && !activeClaim.weeklyHoursCustomized)) {
                activeClaim.weeklyHours = expectedWeekly;
                if (activeClaim.teachingDays && activeClaim.teachingDays[0]) {
                    activeClaim.teachingDays[0].hours = expectedWeekly;
                }
                activeClaim.day1Hours = expectedWeekly;
            }
            if (activeClaim.teachingDaysPerWeek === 1 && activeClaim.weeks && activeClaim.theoryHours !== undefined && activeClaim.practiceHours !== undefined) {
                activeClaim.weeks.forEach(w => {
                    if (!w.isHoliday) {
                        w.theoryHrs = activeClaim.theoryHours;
                        w.practiceHrs = activeClaim.practiceHours;
                        w.totalHrs = activeClaim.theoryHours + activeClaim.practiceHours;
                    }
                });
            }
            sub.claimData = JSON.parse(JSON.stringify(activeClaim));
        }

        // ถ้าผู้ใช้ยังไม่ได้กำหนดอัตราเองเฉพาะวิชานี้ และเทอมมีอัตราคำนวณไว้ ให้นำอัตราเทอมมาใช้
        if (!activeClaim.rateCustomized && term && term.hourlyRate) {
            activeClaim.rate = term.hourlyRate;
            sub.rate = term.hourlyRate;
            sub.claimData.rate = term.hourlyRate;
        }
    } else {
        // Build initial claim data from master catalogue
        const masterSub = (appData.subjects_master || []).find(s => s.id === sub.subjectId) || {};
        const teacher = (appData.teachers || []).find(t => t.id === sub.teacherId) || {};
        activeClaim = createInitialSubjectClaimData(term, masterSub, teacher);
        sub.claimData = JSON.parse(JSON.stringify(activeClaim));
        saveData();
    }

    // Ensure fallback defaults
    ensureTeachingDays();

    // Update Header Badge
    const headerName = document.getElementById('claim-header-subject-name');
    if (headerName) {
        headerName.textContent = `${activeClaim.subjectName} (${activeClaim.subjectCode})`;
    }

    // Populate Subject Preset dropdown in Sidebar Tab 1
    initClaimSubjectPresetDropdown();

    // Fill Sidebar Form Controls
    populateSidebarFromClaimData();

    // Render 18 Weeks in Tab 2
    renderWeeksEditor();

    // Render Students in Tab 4
    renderStudentsEditor();

    // Live Render A4 Pages
    renderA4Page1();
    renderA4Page2();

    // Setup Claim Form Listeners (once)
    setupClaimEventListeners();
}

// Populate Preset Dropdown
function initClaimSubjectPresetDropdown() {
    const sel = document.getElementById('claim-subject-preset');
    if (!sel) return;
    sel.innerHTML = '<option value="">-- เลือกดึงข้อมูลอัตโนมัติจากหลักสูตร ป.ตรี --</option>';
    appData.subjects_master.forEach(s => {
        const opt = document.createElement('option');
        opt.value = s.id;
        const th = s.theoryHours !== undefined ? s.theoryHours : 3;
        const pr = s.practiceHours !== undefined ? s.practiceHours : 0;
        const tot = s.hours || (th + pr);
        opt.textContent = `[${s.code}] ${s.name} (${s.credits || 3} นก. / ท${th}-ป${pr}-รวม${tot} ชม.)`;
        sel.appendChild(opt);
    });

    sel.onchange = () => {
        const val = sel.value;
        if (!val) return;
        const found = appData.subjects_master.find(s => s.id === val);
        if (found) {
            const th = found.theoryHours !== undefined ? found.theoryHours : 3;
            const pr = found.practiceHours !== undefined ? found.practiceHours : 0;
            const tot = found.hours || (th + pr);

            document.getElementById('claim-input-code').value = found.code;
            document.getElementById('claim-input-name').value = found.name;
            document.getElementById('claim-input-credits').value = found.credits || 3;
            
            const elTh = document.getElementById('claim-input-theory-hours');
            if (elTh) elTh.value = th;
            const elPr = document.getElementById('claim-input-practice-hours');
            if (elPr) elPr.value = pr;
            const elWk = document.getElementById('claim-input-weekly-hours');
            if (elWk) elWk.value = tot;

            activeClaim.subjectCode = found.code;
            activeClaim.subjectName = found.name;
            activeClaim.credits = found.credits || 3;
            activeClaim.theoryHours = th;
            activeClaim.practiceHours = pr;
            activeClaim.weeklyHours = tot;

            if (activeClaim.teachingDaysPerWeek === 1 && activeClaim.teachingDays && activeClaim.teachingDays[0]) {
                activeClaim.teachingDays[0].hours = tot;
                activeClaim.day1Hours = tot;
                const day1HoursInp = document.querySelector('.input-day-hours');
                if (day1HoursInp) day1HoursInp.value = tot;
            }
            
            // Recalculate weeks hours
            activeClaim.weeks.forEach(w => {
                if (!w.isHoliday) {
                    w.theoryHrs = th;
                    w.practiceHrs = pr;
                    w.totalHrs = tot;
                }
            });

            updateCalculationsAndPreview();
            renderWeeksEditor();
        }
    };
}

// Calculate hours duration from time range string e.g. "17.00-20.00" -> 3, "08.30-12.30" -> 4
function calculateHoursFromTimeString(timeStr) {
    if (!timeStr) return null;
    const clean = timeStr.trim();
    const m = clean.match(/(\d{1,2})[.:](\d{2})\s*[-–—toถึง]\s*(\d{1,2})[.:](\d{2})/i) ||
              clean.match(/(\d{1,2})\s*[-–—toถึง]\s*(\d{1,2})/i);
    if (!m) return null;
    let sH = parseInt(m[1]), sM = m.length === 5 ? parseInt(m[2]) : 0;
    let eH = m.length === 5 ? parseInt(m[3]) : parseInt(m[2]), eM = m.length === 5 ? parseInt(m[4]) : 0;
    const diffMin = (eH * 60 + eM) - (sH * 60 + sM);
    if (diffMin > 0) {
        const hrs = diffMin / 60;
        return hrs % 1 === 0 ? hrs : Math.round(hrs * 10) / 10;
    }
    return null;
}

// Render dynamic day config cards in Sidebar Tab 1
function renderDailyConfigs() {
    const container = document.getElementById('container-daily-configs');
    if (!container || !activeClaim) return;
    ensureTeachingDays();
    container.innerHTML = '';

    const dowOptions = [
        { val: "1", label: "วันจันทร์" },
        { val: "2", label: "วันอังคาร" },
        { val: "3", label: "วันพุธ" },
        { val: "4", label: "วันพฤหัสบดี" },
        { val: "5", label: "วันศุกร์" },
        { val: "6", label: "วันเสาร์" },
        { val: "0", label: "วันอาทิตย์" }
    ];

    activeClaim.teachingDays.forEach((dayConf, idx) => {
        const dayCard = document.createElement('div');
        dayCard.className = 'p-2.5 rounded-lg bg-[#0f121d] border border-[#2d3748] space-y-1.5 day-config-card';
        dayCard.dataset.dayIdx = idx;

        const dowSelectHtml = dowOptions.map(opt => 
            `<option value="${opt.val}" ${String(dayConf.dow) === opt.val ? 'selected' : ''}>${opt.label}</option>`
        ).join('');

        dayCard.innerHTML = `
            <div class="flex items-center justify-between">
                <span class="text-xs font-semibold ${idx === 0 ? 'text-blue-400' : (idx === 1 ? 'text-orange-400' : (idx === 2 ? 'text-emerald-400' : 'text-purple-400'))} flex items-center gap-1">
                    <i class="fa-regular fa-calendar-days"></i> วันสอนที่ ${idx + 1}
                </span>
                <span class="text-[10px] text-gray-400">ครั้งที่ ${idx + 1} ของสัปดาห์</span>
            </div>
            <div class="grid grid-cols-1 sm:grid-cols-3 gap-2">
                <div>
                    <label class="block text-[10px] text-gray-400 mb-0.5">วันในสัปดาห์</label>
                    <select class="input-day-dow w-full p-1 rounded bg-[#1c2134] border border-[#2d3748] text-xs text-white">
                        ${dowSelectHtml}
                    </select>
                </div>
                <div>
                    <label class="block text-[10px] text-gray-400 mb-0.5">ช่วงเวลาสอน</label>
                    <input type="text" class="input-day-time w-full p-1 rounded bg-[#1c2134] border border-[#2d3748] text-xs text-center text-white" value="${dayConf.time || '17.00-20.00'}" placeholder="17.00-20.00">
                </div>
                <div>
                    <label class="block text-[10px] text-gray-400 mb-0.5">จำนวน ชม./วัน</label>
                    <div class="flex items-center gap-1">
                        <input type="number" class="input-day-hours w-full p-1 rounded bg-[#1c2134] border border-[#2d3748] text-xs text-center text-white" value="${dayConf.hours || 3}" min="1" max="12">
                        <span class="text-[11px] text-gray-400">ชม.</span>
                    </div>
                </div>
            </div>
        `;

        // Bind day card events
        const selDow = dayCard.querySelector('.input-day-dow');
        const inpTime = dayCard.querySelector('.input-day-time');
        const inpHours = dayCard.querySelector('.input-day-hours');

        selDow.addEventListener('change', () => {
            dayConf.dow = selDow.value;
            if (idx === 0) {
                activeClaim.day1DOW = selDow.value;
                // If user manually changes Day 1 DOW, shift startDate so Day 1 aligns to this new DOW
                const parsedStart = parseThaiDateShort(activeClaim.startDate);
                if (parsedStart && !isNaN(parsedStart.getTime())) {
                    const targetDow = parseInt(selDow.value);
                    const curDow = parsedStart.getDay();
                    if (curDow !== targetDow) {
                        const shift = (targetDow - curDow + 7) % 7;
                        parsedStart.setDate(parsedStart.getDate() + shift);
                        const yyyy = parsedStart.getFullYear();
                        const mm = String(parsedStart.getMonth() + 1).padStart(2, '0');
                        const dd = String(parsedStart.getDate()).padStart(2, '0');
                        activeClaim.startDate = `${yyyy}-${mm}-${dd}`;
                        const elStart = document.getElementById('claim-input-start-date');
                        if (elStart) elStart.value = activeClaim.startDate;
                        const elStartTh = document.getElementById('claim-input-start-date-th');
                        if (elStartTh) elStartTh.value = formatThaiBEDate(activeClaim.startDate);
                    }
                }
            }
            if (idx === 1) activeClaim.day2DOW = selDow.value;
            recalculateClaimSchedule(true);
            renderWeeksEditor();
            updateCalculationsAndPreview();
        });

        const syncHoursFromTime = () => {
            const calculatedHrs = calculateHoursFromTimeString(inpTime.value);
            if (calculatedHrs && calculatedHrs > 0) {
                inpHours.value = calculatedHrs;
                dayConf.hours = calculatedHrs;
                if (idx === 0) {
                    activeClaim.day1Hours = calculatedHrs;
                    if (activeClaim.teachingDaysPerWeek === 1) {
                        activeClaim.weeklyHours = calculatedHrs;
                        const wkInp = document.getElementById('claim-input-weekly-hours');
                        if (wkInp) wkInp.value = calculatedHrs;
                    }
                }
                if (idx === 1) activeClaim.day2Hours = calculatedHrs;
                (activeClaim.weeks || []).forEach(w => {
                    if (w.dayNo === idx + 1 && !w.isHoliday) {
                        w.theoryHrs = calculatedHrs;
                        w.totalHrs = calculatedHrs + (parseInt(w.practiceHrs) || 0);
                    }
                });
                renderWeeksEditor();
                updateCalculationsAndPreview();
            }
        };

        inpTime.addEventListener('input', () => {
            dayConf.time = inpTime.value;
            if (idx === 0) {
                activeClaim.day1Time = inpTime.value;
                activeClaim.timeStr = inpTime.value;
            }
            if (idx === 1) activeClaim.day2Time = inpTime.value;
            (activeClaim.weeks || []).forEach(w => {
                if (w.dayNo === idx + 1) w.timeStr = inpTime.value;
            });
            syncHoursFromTime();
            renderWeeksEditor();
            renderA4Page1();
        });

        inpTime.addEventListener('change', () => {
            syncHoursFromTime();
        });

        inpHours.addEventListener('input', () => {
            const hrs = parseInt(inpHours.value) || 0;
            dayConf.hours = hrs;
            if (idx === 0) {
                activeClaim.day1Hours = hrs;
                if (activeClaim.teachingDaysPerWeek === 1) activeClaim.weeklyHours = hrs;
            }
            if (idx === 1) activeClaim.day2Hours = hrs;
            (activeClaim.weeks || []).forEach(w => {
                if (w.dayNo === idx + 1 && !w.isHoliday) {
                    w.theoryHrs = hrs;
                    w.totalHrs = hrs + (parseInt(w.practiceHrs) || 0);
                }
            });
            renderWeeksEditor();
            updateCalculationsAndPreview();
        });

        container.appendChild(dayCard);
    });
}

// Populate Sidebar Tab 1 & Tab 3 from activeClaim
function populateSidebarFromClaimData() {
    if (activeClaim && activeClaim.startDate) {
        const d = parseThaiDateShort(activeClaim.startDate);
        if (d && !isNaN(d.getTime())) {
            const startDow = String(d.getDay());
            ensureTeachingDays(activeClaim);
            if (activeClaim.teachingDays && activeClaim.teachingDays[0]) {
                activeClaim.teachingDays[0].dow = startDow;
                activeClaim.day1DOW = startDow;
            }
        }
    }
    ensureTeachingDays();
    const n = activeClaim.teachingDaysPerWeek || 1;
    const totWeeks = activeClaim.totalWeeks || Math.ceil(18 / n);
    const isMulti = n > 1;

    // Tab 1
    const inputTeacher = document.getElementById('claim-input-teacher');
    if (inputTeacher) inputTeacher.value = activeClaim.teacherName || '';
    const btnClearClaimTeacher = document.getElementById('btn-clear-claim-teacher');
    if (btnClearClaimTeacher) {
        if (activeClaim.teacherName) btnClearClaimTeacher.classList.remove('hidden');
        else btnClearClaimTeacher.classList.add('hidden');
    }
    const inputLevel = document.getElementById('claim-input-level');
    if (inputLevel) inputLevel.value = activeClaim.level || 'ชั้นปี 1';

    const inputAcademicYear = document.getElementById('claim-input-academic-year');
    const curTerm = appData.terms.find(t => t.id === currentTermId);
    const defaultYear = curTerm ? `${curTerm.no}/${curTerm.year}` : '1/2568';
    if (inputAcademicYear) inputAcademicYear.value = activeClaim.academicYear || defaultYear;

    // Days per week input
    const inputDaysPerWeek = document.getElementById('claim-input-days-per-week');
    if (inputDaysPerWeek) inputDaysPerWeek.value = n;

    // Render dynamic day config cards
    renderDailyConfigs();

    const badgeMode = document.getElementById('badge-teaching-mode');
    if (badgeMode) {
        badgeMode.textContent = isMulti ? `${n} วัน/สัปดาห์ (${totWeeks} สัปดาห์)` : '1 วัน/สัปดาห์ (18 สัปดาห์)';
    }

    const tabTitle = document.getElementById('tab-calendar-title');
    if (tabTitle) {
        tabTitle.textContent = isMulti ? `2. ตาราง ${totWeeks} สัปดาห์` : '2. ตาราง 18 สัปดาห์';
    }

    const labelCalc = document.getElementById('label-calc-weeks');
    if (labelCalc) {
        labelCalc.textContent = isMulti ? `คำนวณปฏิทิน ${totWeeks} สัปดาห์อัตโนมัติ` : 'คำนวณปฏิทิน 18 สัปดาห์อัตโนมัติ';
    }

    const labelEndDate = document.getElementById('label-end-date');
    if (labelEndDate) {
        labelEndDate.textContent = isMulti ? `วันสิ้นสุด (คำนวณ ${totWeeks} สัปดาห์)` : 'วันสิ้นสุด (คำนวณ 18 สัปดาห์)';
    }

    const btnPage2Label = document.getElementById('label-btn-page-2');
    if (btnPage2Label) {
        btnPage2Label.textContent = isMulti ? `หน้า 2: ใบตรวจสอบการเข้าเรียน (${totWeeks} สัปดาห์)` : 'หน้า 2: ใบตรวจสอบการเข้าเรียน (18 สัปดาห์)';
    }

    const selLayout = document.getElementById('claim-summer-layout');
    if (selLayout) selLayout.value = activeClaim.summerTableLayout || (n === 2 ? "side_by_side" : "sequential");

    const inpDept = document.getElementById('claim-input-dept');
    if (inpDept) inpDept.value = activeClaim.department || 'เทคโนโลยีโยธา';

    document.getElementById('claim-input-code').value = activeClaim.subjectCode || '';
    document.getElementById('claim-input-name').value = activeClaim.subjectName || '';
    document.getElementById('claim-input-credits').value = activeClaim.credits || 3;
    
    const masterSub = (appData.subjects_master || []).find(s => s.id === activeSubjectRef?.subjectId || s.code === activeClaim.subjectCode || s.name === activeClaim.subjectName);
    let defaultTh = 3, defaultPr = 0;
    if (masterSub) {
        defaultTh = masterSub.theoryHours !== undefined ? masterSub.theoryHours : 3;
        defaultPr = masterSub.practiceHours !== undefined ? masterSub.practiceHours : 0;
    }
    if (activeClaim.theoryHours === undefined) activeClaim.theoryHours = defaultTh;
    if (activeClaim.practiceHours === undefined) activeClaim.practiceHours = defaultPr;
    if (!activeClaim.weeklyHours || (activeClaim.teachingDaysPerWeek === 1 && activeClaim.weeklyHours !== activeClaim.theoryHours + activeClaim.practiceHours && !activeClaim.weeklyHoursCustomized)) {
        activeClaim.weeklyHours = activeClaim.theoryHours + activeClaim.practiceHours;
    }

    const elTh = document.getElementById('claim-input-theory-hours');
    if (elTh) elTh.value = activeClaim.theoryHours;
    const elPr = document.getElementById('claim-input-practice-hours');
    if (elPr) elPr.value = activeClaim.practiceHours;
    const inpWeeklyHrs = document.getElementById('claim-input-weekly-hours');
    if (inpWeeklyHrs) inpWeeklyHrs.value = activeClaim.weeklyHours;
    document.getElementById('claim-input-start-date').value = activeClaim.startDate || '2025-06-02';
    const inpStartTh = document.getElementById('claim-input-start-date-th');
    if (inpStartTh) inpStartTh.value = formatThaiBEDate(activeClaim.startDate || '2025-06-02');
    document.getElementById('claim-input-end-date').value = activeClaim.endDateThai || '29 เดือน กันยายน พ.ศ. 2568';
    const currentTerm = appData.terms.find(t => t.id === currentTermId);
    const termRate = currentTerm ? currentTerm.hourlyRate : null;
    if (activeClaim.rate === undefined || activeClaim.rate === null) {
        activeClaim.rate = termRate || 42;
    }
    document.getElementById('claim-input-rate').value = activeClaim.rate;

    const curStudentsCount = (activeClaim.students && activeClaim.students.length > 0)
        ? activeClaim.students.length
        : (activeClaim.studentCount !== undefined ? activeClaim.studentCount : 6);
    document.getElementById('claim-input-students').value = curStudentsCount;
    document.getElementById('claim-input-percent').value = activeClaim.percent || 60;

    const totals = calculateClaimTotals(activeClaim);
    const inputTotalHours = document.getElementById('claim-input-total-hours');
    if (inputTotalHours) {
        inputTotalHours.value = (activeClaim.customTotalHours !== undefined && activeClaim.customTotalHours !== null && activeClaim.customTotalHours !== '')
            ? activeClaim.customTotalHours
            : totals.tableHours;
    }
    const hintHours = document.getElementById('claim-table-hours-hint');
    if (hintHours) {
        hintHours.textContent = `จากตารางสอน: ${totals.tableHours} ชม.`;
    }

    // Tab 3: Signatures (ข้อ 2-9 ดึงค่าเริ่มต้นจากเทอมแรกเสมอ)
    const defSig = getDefaultSignatures2To9();
    if (!activeClaim.signatures) activeClaim.signatures = {};
    const sig = activeClaim.signatures;
    const deptName = activeClaim.department || 'เทคโนโลยีโยธา';

    // เติมเต็มค่าเริ่มต้นข้อ 2-9 หากยังว่างอยู่
    if (!sig.programChair && defSig.programChair) sig.programChair = defSig.programChair;
    if (!sig.curriculumHead && defSig.curriculumHead) sig.curriculumHead = defSig.curriculumHead;
    if (!sig.deptHead && defSig.deptHead) sig.deptHead = defSig.deptHead;
    if (!sig.techHead && defSig.techHead) sig.techHead = defSig.techHead;
    if (!sig.academicDeputy && defSig.academicDeputy) sig.academicDeputy = defSig.academicDeputy;
    if (!sig.financeHead && defSig.financeHead) sig.financeHead = defSig.financeHead;
    if (!sig.resourceDeputy && defSig.resourceDeputy) sig.resourceDeputy = defSig.resourceDeputy;
    if (!sig.director && defSig.director) sig.director = defSig.director;

    // ซิงค์ชื่อตำแหน่งหัวหน้าสาขาวิชา และ ประธานหลักสูตร ให้สอดคล้องกับสาขาวิชา
    const expectedDHRole = getFormattedDeptRole(deptName, 'deptHead');
    const expectedPCRole = getFormattedDeptRole(deptName, 'programChair');
    if (!sig.deptHeadRole || (sig.deptHeadRole.includes('โยธา') && !deptName.includes('โยธา'))) {
        sig.deptHeadRole = expectedDHRole;
        if (activeSubjectRef && activeSubjectRef.signatures) activeSubjectRef.signatures.deptHeadRole = expectedDHRole;
    }
    if (!sig.programChairRole || (sig.programChairRole.includes('โยธา') && !deptName.includes('โยธา'))) {
        sig.programChairRole = expectedPCRole;
        if (activeSubjectRef && activeSubjectRef.signatures) activeSubjectRef.signatures.programChairRole = expectedPCRole;
    }

    document.getElementById('sig-teacher-name').value = sig.teacher || activeClaim.teacherName || '';
    const inpProgChair = document.getElementById('sig-program-chair');
    if (inpProgChair) inpProgChair.value = sig.programChair || defSig.programChair || 'นายปริวัฒน์ ยืนยิ่ง';
    const lblProgChair = document.getElementById('label-sig-program-chair');
    if (lblProgChair) lblProgChair.textContent = `2. ประธานหลักสูตรสาขาวิชา${deptName}`;

    const inpProgChairRole = document.getElementById('sig-program-chair-role');
    if (inpProgChairRole) {
        inpProgChairRole.value = sig.programChairRole || expectedPCRole;
        inpProgChairRole.oninput = () => {
            sig.programChairRole = inpProgChairRole.value;
            if (activeSubjectRef) {
                if (!activeSubjectRef.signatures) activeSubjectRef.signatures = {};
                activeSubjectRef.signatures.programChairRole = inpProgChairRole.value;
            }
            renderA4Page1();
            renderA4Page2();
        };
    }

    document.getElementById('sig-curriculum-head').value = sig.curriculumHead || defSig.curriculumHead || '';
    document.getElementById('sig-dept-head').value = sig.deptHead || defSig.deptHead || '';
    const lblDeptHead = document.getElementById('label-sig-dept-head');
    if (lblDeptHead) lblDeptHead.textContent = `4. หัวหน้าสาขาวิชา${deptName}`;

    const inpDeptHeadRole = document.getElementById('sig-dept-head-role');
    if (inpDeptHeadRole) {
        inpDeptHeadRole.value = sig.deptHeadRole || expectedDHRole;
        inpDeptHeadRole.oninput = () => {
            sig.deptHeadRole = inpDeptHeadRole.value;
            if (activeSubjectRef) {
                if (!activeSubjectRef.signatures) activeSubjectRef.signatures = {};
                activeSubjectRef.signatures.deptHeadRole = inpDeptHeadRole.value;
            }
            renderA4Page1();
        };
    }

    document.getElementById('sig-tech-head').value = sig.techHead || defSig.techHead || '';
    document.getElementById('sig-academic-deputy').value = sig.academicDeputy || defSig.academicDeputy || '';
    document.getElementById('sig-finance-head').value = sig.financeHead || defSig.financeHead || '';
    document.getElementById('sig-resource-deputy').value = sig.resourceDeputy || defSig.resourceDeputy || '';
    document.getElementById('sig-director').value = sig.director || defSig.director || '';

    updateCalculationsAndPreview();
}

// Calculations for Hours, Money, and Thai Baht Text
function calculateClaimTotals(claim = activeClaim) {
    let totalTheory = 0;
    let totalPractice = 0;
    let tableHours = 0;
    if (!claim) return { totalTheory: 0, totalPractice: 0, grandTotalHrs: 0, tableHours: 0, totalMoney: 0, bahtString: '' };

    (claim.weeks || []).forEach(w => {
        if (!w.isHoliday) {
            totalTheory += (parseInt(w.theoryHrs) || 0);
            totalPractice += (parseInt(w.practiceHrs) || 0);
            tableHours += (parseInt(w.totalHrs) || 0);
        }
    });

    let grandTotalHrs = tableHours;
    if (claim.customTotalHours !== undefined && claim.customTotalHours !== null && claim.customTotalHours !== '') {
        const parsed = parseFloat(claim.customTotalHours);
        if (!isNaN(parsed)) {
            grandTotalHrs = parsed;
        }
    }

    const rate = parseFloat(claim.rate) || 0;
    const totalMoney = grandTotalHrs * rate;
    const bahtString = thaiBahtText(totalMoney);

    return { totalTheory, totalPractice, grandTotalHrs, tableHours, totalMoney, bahtString };
}

function updateCalculationsAndPreview() {
    const totals = calculateClaimTotals();

    const elTotalHours = document.getElementById('claim-display-total-hours');
    const elInputTotalHours = document.getElementById('claim-input-total-hours');
    const elTotalMoney = document.getElementById('claim-display-total-money');
    const elBahtText = document.getElementById('claim-input-baht-text');
    const hintHours = document.getElementById('claim-table-hours-hint');

    if (elTotalHours) elTotalHours.textContent = `${totals.grandTotalHrs} ชั่วโมง`;
    if (elInputTotalHours && document.activeElement !== elInputTotalHours) {
        elInputTotalHours.value = (activeClaim.customTotalHours !== undefined && activeClaim.customTotalHours !== null && activeClaim.customTotalHours !== '')
            ? activeClaim.customTotalHours
            : totals.tableHours;
    }
    if (hintHours) hintHours.textContent = `จากตารางสอน: ${totals.tableHours} ชม.`;
    if (elTotalMoney) elTotalMoney.textContent = formatMoney(totals.totalMoney);
    if (elBahtText) elBahtText.value = totals.bahtString;

    // Synchronize subject data and term hours in real-time
    if (activeSubjectRef) {
        activeSubjectRef.claimData = JSON.parse(JSON.stringify(activeClaim));
        activeSubjectRef.hours = totals.grandTotalHrs;
        activeSubjectRef.rate = activeClaim.rate;
        activeSubjectRef.level = activeClaim.level || activeSubjectRef.level || 'ชั้นปี 1';
        activeSubjectRef.time = activeClaim.timeStr || activeSubjectRef.time || '17.00-20.00';
        activeSubjectRef.studentCount = activeClaim.students ? activeClaim.students.length : 0;
        const matchedTeacher = (appData.teachers || []).find(t => t.name === activeClaim.teacherName);
        if (matchedTeacher) {
            activeSubjectRef.teacherId = matchedTeacher.id;
        }

        const currentTerm = appData.terms.find(t => t.id === currentTermId);
        if (currentTerm) {
            const autoHrs = calculateTermTotalHours(currentTerm);
            currentTerm.totalTeachingHours = autoHrs;
            if (currentTerm.budget > 0 && autoHrs > 0 && !activeClaim.rateCustomized) {
                currentTerm.hourlyRate = Math.floor(currentTerm.budget / autoHrs);
            }
        }
        saveData();
    }

    // Refresh Live A4 Documents
    renderA4Page1();
    renderA4Page2();
}

// Render Tab 2: Weeks Editor (18 Weeks or 9 Weeks)
// Render Tab 2: Weeks Editor (Dynamic totalWeeks or 18 Weeks)
// Helper to handle manual date input changes and check Thai holidays in real-time
function handleDateInputChange(sessionData, newDateStr, boxOrItem, isMulti) {
    sessionData.dateStr = newDateStr;
    const parsedDate = parseThaiDateShort(newDateStr);
    if (parsedDate) {
        const yyyy = parsedDate.getFullYear();
        const mm = String(parsedDate.getMonth() + 1).padStart(2, '0');
        const dd = String(parsedDate.getDate()).padStart(2, '0');
        sessionData.isoDate = `${yyyy}-${mm}-${dd}`;

        const thaiHoliday = getThaiHoliday(parsedDate);
        const chk = boxOrItem.querySelector('.chk-holiday');
        const reasonInp = boxOrItem.querySelector('.input-holiday-reason');
        const reasonDiv = boxOrItem.querySelector('.div-holiday-reason');
        const hrsDiv = boxOrItem.querySelector('.div-teaching-hours');
        const sessTotalSpan = boxOrItem.querySelector('.session-total-text');

        if (thaiHoliday) {
            sessionData.isHoliday = true;
            sessionData.holidayReason = shortenHolidayName(thaiHoliday.name);
            sessionData.theoryHrs = 0;
            sessionData.practiceHrs = 0;
            sessionData.totalHrs = 0;

            if (chk) chk.checked = true;
            if (reasonInp) reasonInp.value = sessionData.holidayReason;
            if (reasonDiv) reasonDiv.classList.remove('hidden');
            if (hrsDiv) hrsDiv.classList.add('hidden');
            if (sessTotalSpan) sessTotalSpan.textContent = '0';
            if (isMulti) {
                boxOrItem.className = 'session-box p-2 rounded-lg border text-xs transition bg-red-950/20 border-red-500/40';
            } else {
                boxOrItem.className = 'p-2.5 rounded-lg border text-xs transition bg-red-950/20 border-red-500/40';
            }
        } else {
            if (sessionData.isHoliday && isKnownThaiHolidayReason(sessionData.holidayReason)) {
                sessionData.isHoliday = false;
                sessionData.holidayReason = "";
                const defaultHrs = parseInt(sessionData.timeStr ? calculateHoursFromTimeString(sessionData.timeStr) : 3) || 3;
                sessionData.theoryHrs = defaultHrs;
                sessionData.practiceHrs = 0;
                sessionData.totalHrs = defaultHrs;

                if (chk) chk.checked = false;
                if (reasonInp) reasonInp.value = "";
                if (reasonDiv) reasonDiv.classList.add('hidden');
                if (hrsDiv) hrsDiv.classList.remove('hidden');
                if (sessTotalSpan) sessTotalSpan.textContent = defaultHrs;
                if (isMulti) {
                    boxOrItem.className = 'session-box p-2 rounded-lg border text-xs transition bg-[#0f121d] border-[#2d3748]';
                } else {
                    boxOrItem.className = 'p-2.5 rounded-lg border text-xs transition bg-[#141725] border-[#2d3748]';
                }
            }
        }
    }
    renderA4Page1();
    renderA4Page2();
    updateCalculationsAndPreview();
}

// Helper to handle manual time input changes
function handleTimeInputChange(sessionData, newTimeStr, boxOrItem) {
    sessionData.timeStr = newTimeStr;
    const calcHrs = calculateHoursFromTimeString(newTimeStr);
    if (calcHrs && calcHrs > 0 && !sessionData.isHoliday) {
        sessionData.theoryHrs = calcHrs;
        sessionData.practiceHrs = 0;
        sessionData.totalHrs = calcHrs;
        const thInp = boxOrItem.querySelector('.input-theory');
        const prInp = boxOrItem.querySelector('.input-practice');
        const totalSpan = boxOrItem.querySelector('.session-total-text');
        if (thInp) thInp.value = calcHrs;
        if (prInp) prInp.value = 0;
        if (totalSpan) totalSpan.textContent = calcHrs;
    }
    renderA4Page1();
    renderA4Page2();
    updateCalculationsAndPreview();
}

// Helper to handle Start Date changes and automatically sync Day 1 DOW with real calendar
function handleStartDateChange(newIsoDate) {
    if (!activeClaim || !newIsoDate) return;
    activeClaim.startDate = newIsoDate;

    // Parse date and determine real calendar day of week (0=Sun, 1=Mon, 2=Tue, 3=Wed, 4=Thu, 5=Fri, 6=Sat)
    const parsedDate = parseThaiDateShort(newIsoDate);
    if (parsedDate && !isNaN(parsedDate.getTime())) {
        const startDow = String(parsedDate.getDay());
        ensureTeachingDays(activeClaim);
        if (activeClaim.teachingDays && activeClaim.teachingDays[0]) {
            // Automatically set Day 1 DOW to match real calendar day of start date!
            activeClaim.teachingDays[0].dow = startDow;
            activeClaim.day1DOW = startDow;
        }
    }

    // Keep inputs in sync
    const elStart = document.getElementById('claim-input-start-date');
    if (elStart && elStart.value !== newIsoDate) elStart.value = newIsoDate;
    const elStartTh = document.getElementById('claim-input-start-date-th');
    if (elStartTh) elStartTh.value = formatThaiBEDate(newIsoDate);

    recalculateClaimSchedule(true);
    renderDailyConfigs(); // Day 1 dropdown automatically updates to show the real calendar day!
    renderWeeksEditor();
    updateCalculationsAndPreview();
}

function renderWeeksEditor() {
    const container = document.getElementById('claim-weeks-editor-list');
    const labelCount = document.getElementById('claim-weeks-count-label');
    const tabTitle = document.getElementById('tab-calendar-title');
    if (!container || !activeClaim) return;
    ensureTeachingDays();
    container.innerHTML = '';

    const n = activeClaim.teachingDaysPerWeek || 1;
    const totalWeeks = activeClaim.totalWeeks || Math.ceil(18 / n);
    const isMulti = n > 1;

    if (tabTitle) tabTitle.textContent = isMulti ? `2. ตาราง ${totalWeeks} สัปดาห์` : '2. ตาราง 18 สัปดาห์';
    if (labelCount) labelCount.textContent = isMulti 
        ? `รายการสอน ${totalWeeks} สัปดาห์ (สัปดาห์ละ ${n} วัน รวม 18 ครั้ง)` 
        : 'รายการสอน 18 สัปดาห์ (ติ๊กเพื่อตั้งเป็นวันหยุด)';

    if (isMulti) {
        // Group sessions into totalWeeks cards
        for (let w = 1; w <= totalWeeks; w++) {
            const startSessionIdx = (w - 1) * n;
            const endSessionIdx = Math.min(w * n, 18);

            const weekCard = document.createElement('div');
            weekCard.className = 'p-3 bg-[#141725] rounded-xl border border-[#2d3748] space-y-2.5';

            let sessionsHtml = '';
            for (let s = startSessionIdx; s < endSessionIdx; s++) {
                const dayInWeek = (s % n) + 1;
                const dConf = activeClaim.teachingDays[dayInWeek - 1] || {};
                const sessionData = activeClaim.weeks[s] || { 
                    weekNo: w, 
                    dayNo: dayInWeek, 
                    sessionNo: s + 1, 
                    dateStr: '', 
                    timeStr: dConf.time || '17.00-20.00', 
                    theoryHrs: dConf.hours || 3, 
                    practiceHrs: 0, 
                    totalHrs: dConf.hours || 3, 
                    isHoliday: false, 
                    holidayReason: '' 
                };

                const dayColors = ['text-blue-300', 'text-orange-300', 'text-emerald-300', 'text-purple-300', 'text-yellow-300', 'text-cyan-300', 'text-rose-300'];
                const dayColor = dayColors[(dayInWeek - 1) % dayColors.length];

                sessionsHtml += `
                    <div class="session-box p-2 rounded-lg border text-xs transition ${sessionData.isHoliday ? 'bg-red-950/20 border-red-500/40' : 'bg-[#0f121d] border-[#2d3748]'}" data-session-idx="${s}">
                        <div class="flex items-center justify-between gap-1.5 mb-1.5">
                            <div class="flex items-center gap-1.5 flex-1">
                                <span class="font-semibold ${dayColor} text-[11px] w-14">ครั้งที่ ${dayInWeek}</span>
                                <input type="text" class="input-week-date bg-[#1c2134] border border-[#2d3748] rounded px-2 py-0.5 text-xs ${dayColor} w-24 text-center" value="${sessionData.dateStr}" placeholder="ว/ด/ป">
                                <input type="text" class="input-week-time bg-[#1c2134] border border-[#2d3748] rounded px-2 py-0.5 text-xs text-gray-300 flex-1 text-center" value="${sessionData.timeStr || dConf.time || '17.00-20.00'}" placeholder="ช่วงเวลา">
                            </div>
                            <label class="flex items-center gap-1 cursor-pointer text-xs ${sessionData.isHoliday ? 'text-red-400 font-bold' : 'text-gray-400'}">
                                <input type="checkbox" class="chk-holiday accent-red-500 rounded" ${sessionData.isHoliday ? 'checked' : ''}>
                                <span>วันหยุด</span>
                            </label>
                        </div>
                        <div class="flex items-center gap-1.5 ${sessionData.isHoliday ? '' : 'hidden'} div-holiday-reason mb-1">
                            <span class="text-red-400 text-[11px]">เหตุผล:</span>
                            <input type="text" class="input-holiday-reason flex-1 bg-[#1c2134] border border-red-500/30 rounded px-2 py-0.5 text-xs text-red-300" value="${sessionData.holidayReason || ''}" placeholder="ระบุเหตุผลวันหยุด">
                        </div>
                        <div class="flex items-center gap-2 ${sessionData.isHoliday ? 'hidden' : ''} div-teaching-hours text-[11px] text-gray-400">
                            <span>ทฤษฎี: <input type="number" class="input-theory bg-[#1c2134] border border-[#2d3748] rounded w-10 text-center text-xs text-white" value="${sessionData.theoryHrs}"> ชม.</span>
                            <span>ปฏิบัติ: <input type="number" class="input-practice bg-[#1c2134] border border-[#2d3748] rounded w-10 text-center text-xs text-white" value="${sessionData.practiceHrs}"> ชม.</span>
                            <span class="font-bold text-white ml-auto">รวม: <span class="session-total-text">${sessionData.totalHrs}</span> ชม.</span>
                        </div>
                    </div>
                `;
            }

            let weekTotalHrs = 0;
            for (let s = startSessionIdx; s < endSessionIdx; s++) {
                const ws = activeClaim.weeks[s];
                if (ws && !ws.isHoliday) {
                    weekTotalHrs += (parseInt(ws.totalHrs) || 0);
                }
            }

            weekCard.innerHTML = `
                <div class="flex items-center justify-between border-b border-[#2d3748] pb-1.5">
                    <span class="font-bold text-blue-400 text-xs flex items-center gap-1.5">
                        <i class="fa-solid fa-calendar-week"></i> สัปดาห์ที่ ${w}
                    </span>
                    <span class="text-[11px] text-gray-400">
                        รวมสัปดาห์นี้: <span class="font-bold text-white week-total-display">${weekTotalHrs} ชม.</span>
                    </span>
                </div>
                ${sessionsHtml}
            `;

            // Bind session inputs within weekCard
            const sessionBoxes = weekCard.querySelectorAll('.session-box');
            sessionBoxes.forEach((box) => {
                const sIdx = parseInt(box.dataset.sessionIdx);
                const sessionData = activeClaim.weeks[sIdx];
                if (!sessionData) return;
                const dIdx = sIdx % n;
                const defaultHrs = parseInt((activeClaim.teachingDays[dIdx] || {}).hours) || 3;

                const chk = box.querySelector('.chk-holiday');
                const reasonInp = box.querySelector('.input-holiday-reason');
                const reasonDiv = box.querySelector('.div-holiday-reason');
                const hrsDiv = box.querySelector('.div-teaching-hours');
                const dateInp = box.querySelector('.input-week-date');
                const timeInp = box.querySelector('.input-week-time');
                const theoryInp = box.querySelector('.input-theory');
                const practiceInp = box.querySelector('.input-practice');
                const sessTotalSpan = box.querySelector('.session-total-text');

                const updateCardTotal = () => {
                    let sum = 0;
                    for (let s = startSessionIdx; s < endSessionIdx; s++) {
                        const ws = activeClaim.weeks[s];
                        if (ws && !ws.isHoliday) sum += (parseInt(ws.totalHrs) || 0);
                    }
                    weekCard.querySelector('.week-total-display').textContent = `${sum} ชม.`;
                };

                chk.addEventListener('change', () => {
                    sessionData.isHoliday = chk.checked;
                    if (sessionData.isHoliday) {
                        if (!sessionData.holidayReason) sessionData.holidayReason = "วันหยุด";
                        sessionData.theoryHrs = 0;
                        sessionData.practiceHrs = 0;
                        sessionData.totalHrs = 0;
                        reasonDiv.classList.remove('hidden');
                        hrsDiv.classList.add('hidden');
                        box.className = 'session-box p-2 rounded-lg border text-xs transition bg-red-950/20 border-red-500/40';
                    } else {
                        sessionData.holidayReason = "";
                        sessionData.theoryHrs = defaultHrs;
                        sessionData.practiceHrs = 0;
                        sessionData.totalHrs = defaultHrs;
                        reasonDiv.classList.add('hidden');
                        hrsDiv.classList.remove('hidden');
                        box.className = 'session-box p-2 rounded-lg border text-xs transition bg-[#0f121d] border-[#2d3748]';
                    }
                    if (sessTotalSpan) sessTotalSpan.textContent = sessionData.totalHrs;
                    updateCardTotal();
                    updateCalculationsAndPreview();
                });

                reasonInp.addEventListener('input', () => {
                    sessionData.holidayReason = reasonInp.value;
                    renderA4Page1();
                });

                dateInp.addEventListener('input', () => {
                    handleDateInputChange(sessionData, dateInp.value, box, true);
                    updateCardTotal();
                });
                dateInp.addEventListener('change', () => {
                    handleDateInputChange(sessionData, dateInp.value, box, true);
                    updateCardTotal();
                });

                timeInp.addEventListener('input', () => {
                    handleTimeInputChange(sessionData, timeInp.value, box);
                    updateCardTotal();
                });
                timeInp.addEventListener('change', () => {
                    handleTimeInputChange(sessionData, timeInp.value, box);
                    updateCardTotal();
                });

                theoryInp.addEventListener('input', () => {
                    sessionData.theoryHrs = parseInt(theoryInp.value) || 0;
                    sessionData.totalHrs = sessionData.theoryHrs + (parseInt(sessionData.practiceHrs) || 0);
                    if (sessTotalSpan) sessTotalSpan.textContent = sessionData.totalHrs;
                    updateCardTotal();
                    updateCalculationsAndPreview();
                });

                practiceInp.addEventListener('input', () => {
                    sessionData.practiceHrs = parseInt(practiceInp.value) || 0;
                    sessionData.totalHrs = (parseInt(sessionData.theoryHrs) || 0) + sessionData.practiceHrs;
                    if (sessTotalSpan) sessTotalSpan.textContent = sessionData.totalHrs;
                    updateCardTotal();
                    updateCalculationsAndPreview();
                });
            });

            container.appendChild(weekCard);
        }
    } else {
        // 1 Day / Week (18 weeks)
        (activeClaim.weeks || []).forEach((w, idx) => {
            const item = document.createElement('div');
            item.className = `p-2.5 rounded-lg border text-xs transition ${
                w.isHoliday ? 'bg-red-950/20 border-red-500/40' : 'bg-[#141725] border-[#2d3748]'
            }`;
            
            item.innerHTML = `
                <div class="flex items-center justify-between gap-2 mb-1.5">
                    <div class="flex items-center gap-1.5 flex-1">
                        <span class="font-bold text-gray-300 w-16">สัปดาห์ ${w.weekNo}</span>
                        <input type="text" class="input-week-date bg-[#0f121d] border border-[#2d3748] rounded px-2 py-0.5 text-xs text-blue-300 w-24 text-center" value="${w.dateStr}" placeholder="ว/ด/ป">
                        <input type="text" class="input-week-time bg-[#0f121d] border border-[#2d3748] rounded px-2 py-0.5 text-xs text-gray-300 flex-1 text-center" value="${w.timeStr || activeClaim.day1Time || '17.00-20.00'}" placeholder="ช่วงเวลา">
                    </div>
                    <label class="flex items-center gap-1.5 cursor-pointer text-xs ${w.isHoliday ? 'text-red-400 font-bold' : 'text-gray-400'}">
                        <input type="checkbox" class="chk-holiday accent-red-500 rounded" ${w.isHoliday ? 'checked' : ''}>
                        <span>วันหยุด</span>
                    </label>
                </div>
                <div class="flex items-center gap-2 ${w.isHoliday ? '' : 'hidden'} div-holiday-reason mb-1">
                    <span class="text-red-400">เหตุผล:</span>
                    <input type="text" class="input-holiday-reason flex-1 bg-[#0f121d] border border-red-500/30 rounded px-2 py-0.5 text-xs text-red-300" value="${w.holidayReason || ''}" placeholder="เช่น หยุดตามมติ ครม.">
                </div>
                <div class="flex items-center gap-3 ${w.isHoliday ? 'hidden' : ''} div-teaching-hours text-gray-400 mt-1">
                    <span>ทฤษฎี: <input type="number" class="input-theory bg-[#0f121d] border border-[#2d3748] rounded w-12 text-center text-xs text-white" value="${w.theoryHrs}"> ชม.</span>
                    <span>ปฏิบัติ: <input type="number" class="input-practice bg-[#0f121d] border border-[#2d3748] rounded w-12 text-center text-xs text-white" value="${w.practiceHrs}"> ชม.</span>
                    <span class="font-bold text-white ml-auto">รวม: ${w.totalHrs} ชม.</span>
                </div>
            `;

            // Bind week item inputs
            const chkHoli = item.querySelector('.chk-holiday');
            const inputReason = item.querySelector('.input-holiday-reason');
            const divReason = item.querySelector('.div-holiday-reason');
            const divHrs = item.querySelector('.div-teaching-hours');
            const inputDate = item.querySelector('.input-week-date');
            const inputTime = item.querySelector('.input-week-time');
            const inputTheory = item.querySelector('.input-theory');
            const inputPractice = item.querySelector('.input-practice');

            chkHoli.addEventListener('change', () => {
                w.isHoliday = chkHoli.checked;
                if (w.isHoliday) {
                    if (!w.holidayReason) w.holidayReason = "หยุดตามมติ ครม.";
                    w.theoryHrs = 0;
                    w.practiceHrs = 0;
                    w.totalHrs = 0;
                    divReason.classList.remove('hidden');
                    divHrs.classList.add('hidden');
                    item.className = 'p-2.5 rounded-lg border text-xs transition bg-red-950/20 border-red-500/40';
                } else {
                    w.holidayReason = "";
                    const defTh = activeClaim.theoryHours !== undefined ? activeClaim.theoryHours : 3;
                    const defPr = activeClaim.practiceHours !== undefined ? activeClaim.practiceHours : 0;
                    w.theoryHrs = defTh;
                    w.practiceHrs = defPr;
                    w.totalHrs = defTh + defPr;
                    divReason.classList.add('hidden');
                    divHrs.classList.remove('hidden');
                    item.className = 'p-2.5 rounded-lg border text-xs transition bg-[#141725] border-[#2d3748]';
                }
                updateCalculationsAndPreview();
            });

            inputReason.addEventListener('input', () => {
                w.holidayReason = inputReason.value;
                renderA4Page1();
            });

            inputDate.addEventListener('input', () => {
                handleDateInputChange(w, inputDate.value, item, false);
            });
            inputDate.addEventListener('change', () => {
                handleDateInputChange(w, inputDate.value, item, false);
            });

            inputTime.addEventListener('input', () => {
                handleTimeInputChange(w, inputTime.value, item);
            });
            inputTime.addEventListener('change', () => {
                handleTimeInputChange(w, inputTime.value, item);
            });

            inputTheory.addEventListener('input', () => {
                w.theoryHrs = parseInt(inputTheory.value) || 0;
                w.totalHrs = w.theoryHrs + (parseInt(w.practiceHrs) || 0);
                updateCalculationsAndPreview();
            });

            inputPractice.addEventListener('input', () => {
                w.practiceHrs = parseInt(inputPractice.value) || 0;
                w.totalHrs = (parseInt(w.theoryHrs) || 0) + w.practiceHrs;
                updateCalculationsAndPreview();
            });

            container.appendChild(item);
        });
    }
}

// Helper to split Thai Full Name into { name, surname }
function splitThaiFullName(fullName = '') {
    const trimmed = (fullName || '').trim();
    if (!trimmed) return { name: '', surname: '' };

    const prefixes = ['นางสาว', 'นาย', 'นาง', 'น.ส.', 'ด.ช.', 'ด.ญ.'];
    const parts = trimmed.split(/\s+/);
    
    if (parts.length <= 1) {
        return { name: parts[0] || '', surname: '' };
    }

    // Check if first token is a standalone prefix (e.g. ["นาย", "วัชรายุทธ", "นิพระขัน"])
    if (parts.length >= 3 && prefixes.includes(parts[0])) {
        return {
            name: `${parts[0]} ${parts[1]}`,
            surname: parts.slice(2).join(' ')
        };
    }

    return {
        name: parts[0],
        surname: parts.slice(1).join(' ')
    };
}

// Render Tab 4: Students Editor (รวมเป็นช่องกรอกเดียว: ชื่อ-สกุล)
function renderStudentsEditor() {
    const container = document.getElementById('claim-students-editor-list');
    const badgeCount = document.getElementById('claim-student-count-badge');
    if (!container) return;

    const count = activeClaim.students ? activeClaim.students.length : 0;
    if (badgeCount) badgeCount.textContent = count;
    container.innerHTML = '';

    (activeClaim.students || []).forEach((st, idx) => {
        const row = document.createElement('div');
        row.className = 'p-2 bg-[#141725] border border-[#2d3748] rounded-lg text-xs flex items-center gap-2';
        
        // ประกอบชื่อ-สกุลเต็มสำหรับแสดงในช่องกรอกเดียว
        const currentFullName = [st.name || '', st.surname || ''].filter(Boolean).join(' ');

        row.innerHTML = `
            <span class="text-gray-500 font-mono w-5 text-right">${idx + 1}.</span>
            <div class="relative w-28">
                <input type="text" class="input-st-id bg-[#0f121d] border border-[#2d3748] rounded px-2 py-1.5 text-xs text-blue-300 w-full font-mono" value="${st.studentId || ''}" placeholder="รหัสนักศึกษา" autocomplete="off">
            </div>
            <div class="relative flex-1">
                <input type="text" class="input-st-fullname w-full bg-[#0f121d] border border-[#2d3748] rounded px-2 py-1.5 text-xs text-white" value="${currentFullName}" placeholder="ชื่อ - สกุล (เช่น นายวัชรายุทธ นิพระขัน)" autocomplete="off">
            </div>
            <button class="btn-del-st text-gray-500 hover:text-red-400 p-1" title="ลบนักศึกษา"><i class="fa-solid fa-trash-can"></i></button>
        `;

        const idInput = row.querySelector('.input-st-id');
        const fullnameInput = row.querySelector('.input-st-fullname');

        idInput.addEventListener('input', (e) => {
            st.studentId = e.target.value;
            renderA4Page2();
        });

        fullnameInput.addEventListener('input', (e) => {
            const splitted = splitThaiFullName(e.target.value);
            st.name = splitted.name;
            st.surname = splitted.surname;
            renderA4Page2();
        });

        // Autocomplete for Student Full Name
        createAutocompleteDropdown(fullnameInput, {
            getItems: (query) => {
                const sorted = filterAndSortSuggestions(appData.students || [], query, stItem => ({
                    primary: stItem.name,
                    secondary: stItem.studentId || ''
                }));
                return sorted.map(stItem => ({
                    title: stItem.name,
                    subtitle: stItem.studentId ? `รหัสนักศึกษา: ${stItem.studentId}` : '',
                    value: stItem.name,
                    raw: stItem
                }));
            },
            onSelect: (item) => {
                const s = item.raw;
                const full = (s.name || '').trim();
                const splitted = splitThaiFullName(full);
                fullnameInput.value = full;
                if (s.studentId) idInput.value = s.studentId;
                st.name = splitted.name;
                st.surname = splitted.surname;
                st.studentId = s.studentId || st.studentId || '';
                renderA4Page2();
            }
        });

        // Autocomplete for Student ID
        createAutocompleteDropdown(idInput, {
            getItems: (query) => {
                const sorted = filterAndSortSuggestions(appData.students || [], query, stItem => ({
                    primary: stItem.studentId || '',
                    secondary: stItem.name || ''
                }));
                return sorted.map(stItem => ({
                    title: stItem.studentId || '',
                    subtitle: stItem.name || '',
                    value: stItem.studentId || '',
                    raw: stItem
                }));
            },
            onSelect: (item) => {
                const s = item.raw;
                const full = (s.name || '').trim();
                const splitted = splitThaiFullName(full);
                idInput.value = s.studentId || '';
                fullnameInput.value = full;
                st.name = splitted.name;
                st.surname = splitted.surname;
                st.studentId = s.studentId || '';
                renderA4Page2();
            }
        });

        row.querySelector('.btn-del-st').addEventListener('click', () => {
            activeClaim.students.splice(idx, 1);
            activeClaim.studentCount = activeClaim.students.length;
            if (activeSubjectRef) activeSubjectRef.studentCount = activeClaim.students.length;
            document.getElementById('claim-input-students').value = activeClaim.students.length;
            renderStudentsEditor();
            renderA4Page2();
            renderA4Page1();
        });

        container.appendChild(row);
    });
}

// -------------------------------------------------------------------------
// SELECT STUDENTS MODAL FOR CLAIM SUBJECT
// -------------------------------------------------------------------------
let selectedStudentClaimKeys = new Set();
let selectStudentsClaimEventsInitialized = false;

function openSelectStudentsClaimModal() {
    selectedStudentClaimKeys.clear();
    const searchInput = document.getElementById('input-search-claim-students');
    if (searchInput) searchInput.value = '';
    const btnClear = document.getElementById('btn-clear-search-claim-students');
    if (btnClear) btnClear.classList.add('hidden');

    const quickBox = document.getElementById('box-quick-add-student');
    if (quickBox) quickBox.classList.add('hidden');
    const qId = document.getElementById('quick-add-student-id');
    if (qId) qId.value = '';
    const qName = document.getElementById('quick-add-student-name');
    if (qName) qName.value = '';

    renderSelectStudentsClaimModalList('');
    initSelectStudentsClaimModalEvents();
    openModal('modal-select-students-claim');

    setTimeout(() => {
        if (searchInput) searchInput.focus();
    }, 100);
}

function renderSelectStudentsClaimModalList(query = '') {
    const container = document.getElementById('claim-modal-students-list');
    const selectedCounter = document.getElementById('claim-modal-selected-counter');
    const totalCounter = document.getElementById('claim-modal-total-counter');
    const btnConfirmCount = document.getElementById('btn-confirm-add-count');
    const btnConfirm = document.getElementById('btn-confirm-add-selected-students');
    if (!container) return;

    const allStudents = (appData && appData.students) ? appData.students : [];
    if (totalCounter) totalCounter.textContent = allStudents.length;

    // Track existing students in activeClaim
    const existingIds = new Set(
        (activeClaim.students || []).map(s => (s.studentId || '').trim()).filter(Boolean)
    );
    const existingNames = new Set(
        (activeClaim.students || []).map(s => {
            return [s.name || '', s.surname || ''].filter(Boolean).join(' ').trim();
        }).filter(Boolean)
    );

    const q = (query || '').trim().toLowerCase();
    const filtered = allStudents.filter(st => {
        if (!q) return true;
        const nameMatch = (st.name || '').toLowerCase().includes(q);
        const idMatch = (st.studentId || '').toLowerCase().includes(q);
        return nameMatch || idMatch;
    });

    container.innerHTML = '';

    if (allStudents.length === 0) {
        container.innerHTML = `
            <div class="py-8 text-center text-gray-400 space-y-2">
                <i class="fa-solid fa-user-graduate text-3xl text-gray-500"></i>
                <div class="text-xs">ยังไม่มีข้อมูลนักศึกษาในระบบ</div>
                <div class="text-[11px] text-gray-500">คลิกปุ่ม <b>+ เพิ่ม นศ. ใหม่เข้าระบบ</b> ด้านบน เพื่อเพิ่มรายชื่อนักศึกษา</div>
            </div>
        `;
    } else if (filtered.length === 0) {
        container.innerHTML = `
            <div class="py-8 text-center text-gray-400 space-y-2">
                <i class="fa-solid fa-magnifying-glass text-2xl text-gray-500"></i>
                <div class="text-xs">ไม่พบนักศึกษาที่ตรงกับคำค้นหา "${query}"</div>
                <div class="text-[11px] text-gray-500">ลองตรวจสอบตัวสะกด หรือคลิกปุ่มเพิ่มนักศึกษาใหม่เข้าระบบ</div>
            </div>
        `;
    } else {
        filtered.forEach((st, idx) => {
            const stName = (st.name || '').trim();
            const stId = (st.studentId || '').trim();
            const key = stId || st.id || `st_key_${idx}`;

            const isInClaim = (stId && existingIds.has(stId)) || (stName && existingNames.has(stName));
            const isSelected = selectedStudentClaimKeys.has(key);

            const row = document.createElement('div');
            if (isInClaim) {
                row.className = 'flex items-center gap-3 p-2.5 rounded-xl border border-emerald-500/20 bg-emerald-950/10 opacity-75';
                row.innerHTML = `
                    <input type="checkbox" class="w-4 h-4 rounded text-emerald-500 bg-[#0f121d] border-emerald-500/50 cursor-not-allowed" checked disabled>
                    <div class="flex-1 min-w-0 flex items-center justify-between gap-2">
                        <div class="min-w-0">
                            <div class="text-xs font-medium text-gray-300 truncate">${stName || 'ไม่ระบุชื่อ'}</div>
                            <div class="text-[11px] font-mono text-gray-500">${stId || 'ไม่มีรหัส'}</div>
                        </div>
                        <span class="px-2 py-0.5 rounded text-[10px] bg-emerald-500/20 text-emerald-300 border border-emerald-500/30 flex items-center gap-1 shrink-0">
                            <i class="fa-solid fa-check text-[9px]"></i> มีในวิชานี้แล้ว
                        </span>
                    </div>
                `;
            } else {
                row.className = `flex items-center gap-3 p-2.5 rounded-xl border transition cursor-pointer select-none ${
                    isSelected ? 'bg-blue-950/30 border-blue-500/50 text-white' : 'border-transparent hover:border-[#2d3748] hover:bg-[#141829] text-gray-300'
                }`;
                row.innerHTML = `
                    <input type="checkbox" class="claim-st-checkbox w-4 h-4 rounded text-blue-600 bg-[#0f121d] border-gray-600 cursor-pointer pointer-events-none" ${isSelected ? 'checked' : ''}>
                    <div class="flex-1 min-w-0 flex items-center justify-between gap-2">
                        <div class="min-w-0">
                            <div class="text-xs font-medium text-white truncate">${stName || 'ไม่ระบุชื่อ'}</div>
                            <div class="text-[11px] font-mono text-blue-400">${stId || 'ไม่มีรหัส'}</div>
                        </div>
                        ${isSelected ? '<span class="px-2 py-0.5 rounded text-[10px] bg-blue-500/20 text-blue-300 border border-blue-500/30 shrink-0"><i class="fa-solid fa-check text-[9px]"></i> เลือกแล้ว</span>' : ''}
                    </div>
                `;

                row.addEventListener('click', (e) => {
                    if (selectedStudentClaimKeys.has(key)) {
                        selectedStudentClaimKeys.delete(key);
                    } else {
                        selectedStudentClaimKeys.add(key);
                    }
                    updateSelectStudentsClaimCounts();
                    renderSelectStudentsClaimModalList(document.getElementById('input-search-claim-students')?.value || '');
                });
            }
            container.appendChild(row);
        });
    }

    updateSelectStudentsClaimCounts();
}

function updateSelectStudentsClaimCounts() {
    const selectedCounter = document.getElementById('claim-modal-selected-counter');
    const btnConfirmCount = document.getElementById('btn-confirm-add-count');
    const btnConfirm = document.getElementById('btn-confirm-add-selected-students');
    const count = selectedStudentClaimKeys.size;

    if (selectedCounter) selectedCounter.textContent = count;
    if (btnConfirmCount) btnConfirmCount.textContent = count;
    if (btnConfirm) {
        if (count === 0) {
            btnConfirm.disabled = true;
            btnConfirm.classList.add('opacity-50', 'cursor-not-allowed');
        } else {
            btnConfirm.disabled = false;
            btnConfirm.classList.remove('opacity-50', 'cursor-not-allowed');
        }
    }
}

function initSelectStudentsClaimModalEvents() {
    if (selectStudentsClaimEventsInitialized) return;
    selectStudentsClaimEventsInitialized = true;

    // Search Input
    const searchInput = document.getElementById('input-search-claim-students');
    const btnClearSearch = document.getElementById('btn-clear-search-claim-students');

    if (searchInput) {
        searchInput.addEventListener('input', (e) => {
            const val = e.target.value;
            if (btnClearSearch) {
                if (val.trim()) btnClearSearch.classList.remove('hidden');
                else btnClearSearch.classList.add('hidden');
            }
            renderSelectStudentsClaimModalList(val);
        });
    }

    if (btnClearSearch) {
        btnClearSearch.addEventListener('click', () => {
            if (searchInput) {
                searchInput.value = '';
                searchInput.focus();
            }
            btnClearSearch.classList.add('hidden');
            renderSelectStudentsClaimModalList('');
        });
    }

    // Select All (from currently filtered, excluding already in claim)
    const btnSelectAll = document.getElementById('btn-claim-select-all-students');
    if (btnSelectAll) {
        btnSelectAll.addEventListener('click', () => {
            const allStudents = (appData && appData.students) ? appData.students : [];
            const existingIds = new Set(
                (activeClaim.students || []).map(s => (s.studentId || '').trim()).filter(Boolean)
            );
            const existingNames = new Set(
                (activeClaim.students || []).map(s => {
                    return [s.name || '', s.surname || ''].filter(Boolean).join(' ').trim();
                }).filter(Boolean)
            );
            const q = (searchInput?.value || '').trim().toLowerCase();

            allStudents.forEach((st, idx) => {
                const stName = (st.name || '').trim();
                const stId = (st.studentId || '').trim();
                if (q) {
                    const nameMatch = stName.toLowerCase().includes(q);
                    const idMatch = stId.toLowerCase().includes(q);
                    if (!nameMatch && !idMatch) return;
                }
                const isInClaim = (stId && existingIds.has(stId)) || (stName && existingNames.has(stName));
                if (!isInClaim) {
                    const key = stId || st.id || `st_key_${idx}`;
                    selectedStudentClaimKeys.add(key);
                }
            });
            renderSelectStudentsClaimModalList(searchInput?.value || '');
        });
    }

    // Deselect All
    const btnDeselectAll = document.getElementById('btn-claim-deselect-all-students');
    if (btnDeselectAll) {
        btnDeselectAll.addEventListener('click', () => {
            selectedStudentClaimKeys.clear();
            renderSelectStudentsClaimModalList(searchInput?.value || '');
        });
    }

    // Toggle Quick Add Form
    const btnToggleQuick = document.getElementById('btn-toggle-quick-add-student');
    const boxQuick = document.getElementById('box-quick-add-student');
    const btnCancelQuick = document.getElementById('btn-cancel-quick-add-student');
    const btnSaveQuick = document.getElementById('btn-save-quick-add-student');

    if (btnToggleQuick && boxQuick) {
        btnToggleQuick.addEventListener('click', () => {
            boxQuick.classList.toggle('hidden');
            if (!boxQuick.classList.contains('hidden')) {
                const qId = document.getElementById('quick-add-student-id');
                if (qId) qId.focus();
            }
        });
    }

    if (btnCancelQuick && boxQuick) {
        btnCancelQuick.addEventListener('click', () => {
            boxQuick.classList.add('hidden');
        });
    }

    if (btnSaveQuick) {
        btnSaveQuick.addEventListener('click', () => {
            const idInput = document.getElementById('quick-add-student-id');
            const nameInput = document.getElementById('quick-add-student-name');
            const sid = idInput ? idInput.value.trim() : '';
            const sname = nameInput ? nameInput.value.trim() : '';

            if (!sid && !sname) {
                alert('กรุณากรอกรหัสนักศึกษา หรือชื่อ-สกุล');
                return;
            }

            if (!appData.students) appData.students = [];

            // Check if student already exists in master students list
            let existing = appData.students.find(s => 
                (sid && s.studentId && s.studentId.trim() === sid) ||
                (sname && s.name && s.name.trim() === sname)
            );

            let key = '';
            if (existing) {
                key = existing.studentId || existing.id;
            } else {
                const newStudent = {
                    id: (typeof generateId === 'function') ? generateId() : 'st_' + Date.now(),
                    studentId: sid,
                    name: sname
                };
                appData.students.push(newStudent);
                key = sid || newStudent.id;
                saveData();
            }

            selectedStudentClaimKeys.add(key);

            if (idInput) idInput.value = '';
            if (nameInput) nameInput.value = '';
            if (boxQuick) boxQuick.classList.add('hidden');

            renderSelectStudentsClaimModalList(searchInput?.value || '');
        });
    }

    // Confirm Add Selected Students
    const btnConfirm = document.getElementById('btn-confirm-add-selected-students');
    if (btnConfirm) {
        btnConfirm.addEventListener('click', () => {
            if (selectedStudentClaimKeys.size === 0) {
                alert('กรุณาเลือกนักศึกษาอย่างน้อย 1 คน');
                return;
            }

            if (!activeClaim.students) activeClaim.students = [];

            const allStudents = (appData && appData.students) ? appData.students : [];
            let addedCount = 0;

            allStudents.forEach((st, idx) => {
                const stName = (st.name || '').trim();
                const stId = (st.studentId || '').trim();
                const key = stId || st.id || `st_key_${idx}`;

                if (selectedStudentClaimKeys.has(key)) {
                    const splitted = splitThaiFullName(stName);
                    const alreadyIn = activeClaim.students.some(s => {
                        return (stId && s.studentId && s.studentId.trim() === stId) ||
                               (s.name === splitted.name && s.surname === splitted.surname);
                    });

                    if (!alreadyIn) {
                        activeClaim.students.push({
                            studentId: stId,
                            name: splitted.name || '',
                            surname: splitted.surname || ''
                        });
                        addedCount++;
                    }
                }
            });

            activeClaim.studentCount = activeClaim.students.length;
            if (activeSubjectRef) {
                activeSubjectRef.studentCount = activeClaim.students.length;
                if (activeSubjectRef.claimData) {
                    activeSubjectRef.claimData.students = activeClaim.students;
                    activeSubjectRef.claimData.studentCount = activeClaim.students.length;
                }
            }

            const inpStudents = document.getElementById('claim-input-students');
            if (inpStudents) inpStudents.value = activeClaim.students.length;

            renderStudentsEditor();
            renderA4Page1();
            renderA4Page2();
            updateCalculationsAndPreview();
            saveData();
            if (typeof triggerAutoCloudSync === 'function') {
                triggerAutoCloudSync();
            }

            // Close modal
            const modal = document.getElementById('modal-select-students-claim');
            if (modal) {
                modal.classList.remove('active');
                modal.classList.add('hidden');
            }
        });
    }
}

window.openSelectStudentsClaimModal = openSelectStudentsClaimModal;

// -------------------------------------------------------------------------
// LIVE A4 RENDERING: PAGE 1 (ใบเบิกเงินค่าตอบแทนภาคสมทบ)
// -------------------------------------------------------------------------
function generateA4Page1HTML(claim = activeClaim) {
    if (!claim) return '';

    const totals = calculateClaimTotals(claim);
    const weeks = claim.weeks || [];
    const defSig = getDefaultSignatures2To9();
    const rawSig = claim.signatures || {};

    const curDept = claim.department || 'เทคโนโลยีโยธา';
    const defaultDHRole = getFormattedDeptRole(curDept, 'deptHead');
    const defaultPCRole = getFormattedDeptRole(curDept, 'programChair');

    let resolvedDHRole = rawSig.deptHeadRole;
    if (!resolvedDHRole || (resolvedDHRole.includes('โยธา') && !curDept.includes('โยธา'))) {
        resolvedDHRole = defaultDHRole;
    }

    let resolvedPCRole = rawSig.programChairRole;
    if (!resolvedPCRole || (resolvedPCRole.includes('โยธา') && !curDept.includes('โยธา'))) {
        resolvedPCRole = defaultPCRole;
    }

    const sig = {
        teacher: rawSig.teacher || claim.teacherName || '',
        teacherRole: rawSig.teacherRole || claim.teacherRole || 'อาจารย์ผู้สอน',
        programChair: rawSig.programChair || defSig.programChair || '',
        programChairRole: resolvedPCRole || defSig.programChairRole || defaultPCRole,
        curriculumHead: rawSig.curriculumHead || defSig.curriculumHead || 'นายชนะ สุทธิประภา',
        curriculumHeadRole: rawSig.curriculumHeadRole || defSig.curriculumHeadRole || 'หัวหน้างานพัฒนาหลักสูตรสายเทคโนโลยีฯ',
        deptHead: rawSig.deptHead || defSig.deptHead || 'นายปริวัฒน์ ยืนยิ่ง',
        deptHeadRole: resolvedDHRole || defSig.deptHeadRole || defaultDHRole,
        techHead: rawSig.techHead || defSig.techHead || 'นายสถิระ กาญจันดา',
        techHeadRole: rawSig.techHeadRole || defSig.techHeadRole || 'หัวหน้างานภาควิชาเทคโนโลยีบัณฑิต',
        academicDeputy: rawSig.academicDeputy || defSig.academicDeputy || 'นายสุวิชา มั่นยืน',
        academicDeputyRole: rawSig.academicDeputyRole || defSig.academicDeputyRole || 'รองผู้อำนวยการฝ่ายวิชาการ',
        financeHead: rawSig.financeHead || defSig.financeHead || 'นางมลีทอง จารุพงษ์',
        financeHeadRole: rawSig.financeHeadRole || defSig.financeHeadRole || 'หัวหน้าการเงิน',
        resourceDeputy: rawSig.resourceDeputy || defSig.resourceDeputy || 'นางสาวสายฝน สาระผล',
        resourceDeputyRole: rawSig.resourceDeputyRole || defSig.resourceDeputyRole || 'รองผู้อำนวยการฝ่ายบริหารทรัพยากร',
        director: rawSig.director || defSig.director || 'นายธาตรี พิบูลมณฑา',
        directorRole: rawSig.directorRole || defSig.directorRole || 'ผู้อำนวยการวิทยาลัยเทคนิคอุบลราชธานี'
    };

    // Format academic year as 1/2568
    let yearFormatted = (claim.academicYear || '1/2568').trim();
    if (yearFormatted.startsWith('ปีการศึกษา')) {
        yearFormatted = yearFormatted.replace('ปีการศึกษา', '').trim();
    } else if (yearFormatted.includes('/') && !yearFormatted.includes('25')) {
        const parts = yearFormatted.split('/');
        yearFormatted = `${parts[0]}/25${parts[1]}`;
    }

    let scheduleRowsHtml = '';
    const n = claim.teachingDaysPerWeek || 1;
    const is2Days = (n === 2);
    const mSub = (appData.subjects_master || []).find(s => s.code === claim.subjectCode || s.name === claim.subjectName);
    let weeklyHoursPlan = 3;
    if (claim.theoryHours !== undefined && claim.practiceHours !== undefined) {
        weeklyHoursPlan = claim.theoryHours + claim.practiceHours;
    } else if (mSub) {
        const th = mSub.theoryHours !== undefined ? mSub.theoryHours : 3;
        const pr = mSub.practiceHours !== undefined ? mSub.practiceHours : 0;
        weeklyHoursPlan = mSub.hours || (th + pr);
    } else if (claim.weeklyHours) {
        weeklyHoursPlan = claim.weeklyHours;
    } else {
        weeklyHoursPlan = (claim.teachingDays || []).reduce((sum, d) => sum + (parseInt(d.hours) || 0), 0) || 3;
    }

    for (let r = 0; r < 9; r++) {
        let wLeft, wRight;
        let leftWeekNum = '';
        let rightWeekNum = '';

        if (is2Days && claim.summerTableLayout === 'side_by_side') {
            // side_by_side: Left = Day 1 of week r+1, Right = Day 2 of week r+1
            wLeft = weeks[r * 2] || { weekNo: r + 1, dayNo: 1, dateStr: '', timeStr: '', theoryHrs: 0, practiceHrs: 0, totalHrs: 0, isHoliday: false, holidayReason: '' };
            wRight = weeks[r * 2 + 1] || { weekNo: r + 1, dayNo: 2, dateStr: '', timeStr: '', theoryHrs: 0, practiceHrs: 0, totalHrs: 0, isHoliday: false, holidayReason: '' };
            leftWeekNum = `${r + 1}`;
            rightWeekNum = `${r + 1}`;
        } else {
            // Sequential filling for N >= 3, or N=2 sequential, or N=1: Left = session r, Right = session r + 9
            wLeft = weeks[r] || { weekNo: Math.floor(r / n) + 1, dayNo: (r % n) + 1, dateStr: '', timeStr: '', theoryHrs: 0, practiceHrs: 0, totalHrs: 0, isHoliday: false, holidayReason: '' };
            wRight = weeks[r + 9] || { weekNo: Math.floor((r + 9) / n) + 1, dayNo: ((r + 9) % n) + 1, dateStr: '', timeStr: '', theoryHrs: 0, practiceHrs: 0, totalHrs: 0, isHoliday: false, holidayReason: '' };
            leftWeekNum = `${wLeft.weekNo}`;
            rightWeekNum = `${wRight.weekNo}`;
        }

        const leftDIdx = wLeft.dayNo ? wLeft.dayNo - 1 : (r % n);
        const rightDIdx = wRight.dayNo ? wRight.dayNo - 1 : ((r + 9) % n);
        const leftTime = wLeft.timeStr || (claim.teachingDays && claim.teachingDays[leftDIdx] ? claim.teachingDays[leftDIdx].time : '17.00-20.00');
        const rightTime = wRight.timeStr || (claim.teachingDays && claim.teachingDays[rightDIdx] ? claim.teachingDays[rightDIdx].time : '17.00-20.00');

        // Left Cell
        let leftContent = '';
        if (wLeft.isHoliday) {
            leftContent = `
                <td style="text-align: center; border: 1px solid #000; padding: 2.5px 1px;">${leftWeekNum}</td>
                <td style="text-align: center; border: 1px solid #000; padding: 2.5px 1px;">${wLeft.dateStr}</td>
                <td style="text-align: center; border: 1px solid #000; padding: 2.5px 1px;">${leftTime}</td>
                <td colspan="3" style="text-align: center; border: 1px solid #000; padding: 1.5px 2px; vertical-align: middle;">
                    <div class="clamp-2-lines" style="font-size: 13.5px; line-height: 1.25; max-height: 2.6em; overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; word-break: break-word; text-align: center; margin: 0 auto;" title="${wLeft.holidayReason || 'วันหยุด'}">
                        ${shortenHolidayName(wLeft.holidayReason || 'วันหยุด')}
                    </div>
                </td>
            `;
        } else {
            leftContent = `
                <td style="text-align: center; border: 1px solid #000; padding: 2.5px 1px;">${leftWeekNum}</td>
                <td style="text-align: center; border: 1px solid #000; padding: 2.5px 1px;">${wLeft.dateStr}</td>
                <td style="text-align: center; border: 1px solid #000; padding: 2.5px 1px;">${leftTime}</td>
                <td style="text-align: center; border: 1px solid #000; padding: 2.5px 1px;">${wLeft.theoryHrs}</td>
                <td style="text-align: center; border: 1px solid #000; padding: 2.5px 1px;">${wLeft.practiceHrs}</td>
                <td style="text-align: center; border: 1px solid #000; padding: 2.5px 1px;">${wLeft.totalHrs}</td>
            `;
        }

        // Right Cell
        let rightContent = '';
        if (wRight.isHoliday) {
            rightContent = `
                <td style="text-align: center; border: 1px solid #000; padding: 2.5px 1px;">${rightWeekNum}</td>
                <td style="text-align: center; border: 1px solid #000; padding: 2.5px 1px;">${wRight.dateStr}</td>
                <td style="text-align: center; border: 1px solid #000; padding: 2.5px 1px;">${rightTime}</td>
                <td colspan="3" style="text-align: center; border: 1px solid #000; padding: 1.5px 2px; vertical-align: middle;">
                    <div class="clamp-2-lines" style="font-size: 13.5px; line-height: 1.25; max-height: 2.6em; overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; word-break: break-word; text-align: center; margin: 0 auto;" title="${wRight.holidayReason || 'วันหยุด'}">
                        ${shortenHolidayName(wRight.holidayReason || 'วันหยุด')}
                    </div>
                </td>
            `;
        } else {
            rightContent = `
                <td style="text-align: center; border: 1px solid #000; padding: 2.5px 1px;">${rightWeekNum}</td>
                <td style="text-align: center; border: 1px solid #000; padding: 2.5px 1px;">${wRight.dateStr}</td>
                <td style="text-align: center; border: 1px solid #000; padding: 2.5px 1px;">${rightTime}</td>
                <td style="text-align: center; border: 1px solid #000; padding: 2.5px 1px;">${wRight.theoryHrs}</td>
                <td style="text-align: center; border: 1px solid #000; padding: 2.5px 1px;">${wRight.practiceHrs}</td>
                <td style="text-align: center; border: 1px solid #000; padding: 2.5px 1px;">${wRight.totalHrs}</td>
            `;
        }

        scheduleRowsHtml += `<tr>${leftContent}${rightContent}</tr>`;
    }

    return `
        <div style="font-family: 'TH Sarabun PSK', 'TH Sarabun New', 'Sarabun', Tahoma, sans-serif; color: #000; line-height: 1.35; padding: 0 4px; font-size: 14pt;">
            
            <!-- Page 1 Title -->
            <div style="text-align: center; font-size: 20pt; font-weight: bold; margin-bottom: 3px; letter-spacing: 0.2px;">
                ใบเบิกเงินค่าตอบแทนภาคสมทบ
            </div>
            <div style="text-align: center; font-size: 17pt; font-weight: bold; margin-bottom: 14px; letter-spacing: 0.2px;">
                วิทยาลัยเทคนิคอุบลราชธานี
            </div>

            <!-- Page 1 Subheader details -->
            <div style="font-size: 14pt; margin-bottom: 4px;">
                ${claim.level && claim.level.startsWith('ชั้นปี') ? claim.level : 'ชั้นปี ' + (claim.level || '1')}&nbsp;&nbsp;&nbsp;&nbsp;ปีการศึกษา ${yearFormatted}&nbsp;&nbsp;&nbsp;&nbsp;${claim.curriculum || 'หลักสูตร ปริญญาตรี สายเทคโนโลยีหรือสายปฏิบัติการ'}&nbsp;&nbsp;&nbsp;&nbsp;สาขาวิชา ${claim.department || 'เทคโนโลยีโยธา'}
            </div>
            <div style="font-size: 14pt; margin-bottom: 4px;">
                ชื่อผู้ขอเบิก ${claim.teacherName || ''}&nbsp;&nbsp;&nbsp;&nbsp;ตำแหน่ง ${claim.teacherRole || 'อาจารย์'}
            </div>
            <div style="font-size: 14pt; margin-bottom: 4px;">
                ระหว่างวันที่ ${formatThaiDateFull(claim.startDate)} ถึง วันที่ ${claim.endDateThai || ''}
            </div>
            <div style="font-size: 14pt; margin-bottom: 10px;">
                รหัสวิชา ${claim.subjectCode}&nbsp;&nbsp;&nbsp;&nbsp;ชื่อวิชา ${claim.subjectName}&nbsp;&nbsp;&nbsp;&nbsp;เวลาเรียน ${weeklyHoursPlan} ชม.&nbsp;&nbsp;&nbsp;&nbsp;จำนวน ${claim.credits || 3} หน่วยกิต
            </div>

            <!-- 18 Weeks Split Table -->
            <table class="doc-table" style="width: 100%; border-collapse: collapse; font-size: 14pt; margin-bottom: 10px;">
                <thead>
                    <tr style="font-weight: bold; text-align: center; background-color: #fafafa;">
                        <th style="width: 6%; border: 1px solid #000; padding: 2px 1px;">สัปดาห์</th>
                        <th style="width: 13.5%; border: 1px solid #000; padding: 2px 1px;">ว/ด/ป</th>
                        <th style="width: 15%; border: 1px solid #000; padding: 2px 1px;">ช่วงเวลา</th>
                        <th style="width: 5%; border: 1px solid #000; padding: 2px 1px;">ท</th>
                        <th style="width: 5%; border: 1px solid #000; padding: 2px 1px;">ป</th>
                        <th style="width: 5.5%; border: 1px solid #000; padding: 2px 1px;">รวม</th>
                        <th style="width: 6%; border: 1px solid #000; padding: 2px 1px;">สัปดาห์</th>
                        <th style="width: 13.5%; border: 1px solid #000; padding: 2px 1px;">ว/ด/ป</th>
                        <th style="width: 15%; border: 1px solid #000; padding: 2px 1px;">ช่วงเวลา</th>
                        <th style="width: 5%; border: 1px solid #000; padding: 2px 1px;">ท</th>
                        <th style="width: 5%; border: 1px solid #000; padding: 2px 1px;">ป</th>
                        <th style="width: 5.5%; border: 1px solid #000; padding: 2px 1px;">รวม</th>
                    </tr>
                </thead>
                <tbody>
                    ${scheduleRowsHtml}
                    <!-- Total Row -->
                    <tr style="font-weight: bold;">
                        <td colspan="9" style="text-align: center; border: 1px solid #000; padding: 2px 1px; font-size: 14pt;">รวมชั่วโมงสอน</td>
                        <td style="text-align: center; border: 1px solid #000; padding: 2px 1px; font-size: 14pt;">${totals.totalTheory}</td>
                        <td style="text-align: center; border: 1px solid #000; padding: 2px 1px; font-size: 14pt;">${totals.totalPractice}</td>
                        <td style="text-align: center; border: 1px solid #000; padding: 2px 1px; font-size: 14pt;">${totals.grandTotalHrs}</td>
                    </tr>
                </tbody>
            </table>

            <!-- Signatures & Calculation Section with Vertical Line Divider -->
            <div style="display: flex; font-size: 14pt; line-height: 1.35; margin-top: 10px;">
                
                <!-- Left 67%: Calculation & Staff Signatures -->
                <div style="width: 67%; padding-right: 14px; box-sizing: border-box;">
                    <!-- Calculation and text below table -->
                    <div style="font-size: 14pt; line-height: 1.45; margin-bottom: 12px;">
                        <div>
                            โดยขอเบิกในอัตราชั่วโมงละ &nbsp;${claim.rate}&nbsp; บาท &nbsp;&nbsp;จำนวน &nbsp;${totals.grandTotalHrs}&nbsp; ชม. &nbsp;&nbsp;${claim.credits}&nbsp; หน่วยกิต
                        </div>
                        <div style="margin-top: 2px;">
                            ตามจำนวนนักศึกษาลงทะเบียนเรียนวิชา ${claim.subjectName}
                        </div>
                        <div id="p1-calc-total-line" style="margin-top: 2px; white-space: nowrap; overflow: hidden;">
                            รวมจำนวน &nbsp;${claim.students ? claim.students.length : (claim.studentCount || 6)}&nbsp; คน &nbsp;&nbsp;ร้อยละ ${claim.percent || 60} เป็นเงิน &nbsp;${formatMoney(totals.totalMoney)}&nbsp; บาท (${totals.bahtString})
                        </div>
                    </div>

                    <!-- Row 1 Signatures -->
                    <div style="display: flex; justify-content: space-between; margin-bottom: 12px;">
                        <div style="width: 48%; text-align: center;">
                            ลงชื่อ..................................ผู้ขอเบิก<br>
                            ( ${sig.teacher || claim.teacherName || ''} )<br>
                            ตำแหน่ง ${sig.teacherRole || claim.teacherRole || 'อาจารย์ผู้สอน'}
                        </div>
                        <div style="width: 48%; text-align: center;">
                            ลงชื่อ.................................................<br>
                            ( ${sig.curriculumHead || 'นายชนะ สุทธิประภา'} )<br>
                            ${sig.curriculumHeadRole || 'หัวหน้างานพัฒนาหลักสูตรสายเทคโนโลยีฯ'}
                        </div>
                    </div>

                    <!-- Verification header -->
                    <div style="font-weight: bold; font-size: 14pt; margin: 8px 0 6px 0;">
                        ขอรับรองว่าได้ตรวจสอบถูกต้องแล้ว
                    </div>

                    <!-- Row 2 Signatures -->
                    <div style="display: flex; justify-content: space-between; margin-bottom: 12px;">
                        <div style="width: 48%; text-align: center;">
                            ลงชื่อ.................................................<br>
                            ( ${sig.deptHead || 'นายปริวัฒน์ ยืนยิ่ง'} )<br>
                            ${sig.deptHeadRole || defaultDHRole}
                        </div>
                        <div style="width: 48%; text-align: center;">
                            ลงชื่อ.................................................<br>
                            ( ${sig.academicDeputy || 'นายสุวิชา มั่นยืน'} )<br>
                            ${sig.academicDeputyRole || 'รองผู้อำนวยการฝ่ายวิชาการ'}
                        </div>
                    </div>

                    <!-- Row 3 Signature -->
                    <div style="display: flex; justify-content: flex-start;">
                        <div style="width: 48%; text-align: center;">
                            ลงชื่อ.................................................<br>
                            ( ${sig.techHead || 'นายสถิระ กาญจันดา'} )<br>
                            ${sig.techHeadRole || 'หัวหน้างานภาควิชาเทคโนโลยีบัณฑิต'}
                        </div>
                    </div>
                </div>

                <!-- Right 33%: Approval Box with clean vertical dividing line -->
                <div style="width: 33%; border-left: 1px solid #000; padding-left: 14px; box-sizing: border-box; display: flex; flex-direction: column; justify-content: space-between;">
                    <div style="font-weight: bold; font-size: 14pt; text-align: center; margin-bottom: 6px;">
                        เห็นควรอนุมัติให้เบิกได้
                    </div>
                    <div style="text-align: center; margin-bottom: 14px;">
                        ลงชื่อ.................................................<br>
                        ( ${sig.financeHead || 'นางมลีทอง จารุพงษ์'} )<br>
                        ${sig.financeHeadRole || 'หัวหน้าการเงิน'}
                    </div>
                    <div style="text-align: center; margin-bottom: 14px;">
                        ลงชื่อ.................................................<br>
                        ( ${sig.resourceDeputy || 'นางสาวสายฝน สาระผล'} )<br>
                        ${sig.resourceDeputyRole || 'รองผู้อำนวยการฝ่ายบริหารทรัพยากร'}
                    </div>
                    <div style="text-align: center;">
                        ลงชื่อ.................................................<br>
                        ( ${sig.director || 'นายธาตรี พิบูลมณฑา'} )<br>
                        ${sig.directorRole || 'ผู้อำนวยการวิทยาลัยเทคนิคอุบลราชธานี'}
                    </div>
                </div>

            </div>

        </div>
    `;
}

function renderA4Page1() {
    const page1 = document.getElementById('doc-page-1');
    if (!page1 || !activeClaim) return;
    page1.innerHTML = generateA4Page1HTML(activeClaim);

    // ปรับลดขนาดตัวอักษรยอดเงินรวมอัตโนมัติหากยาวเกิน 1 บรรทัด เพื่อให้อยู่ใน 1 บรรทัดเสมอ
    const totalLineEl = page1.querySelector('#p1-calc-total-line');
    if (totalLineEl) {
        let currentPt = 14;
        while (totalLineEl.scrollWidth > totalLineEl.clientWidth && currentPt > 8.5) {
            currentPt -= 0.5;
            totalLineEl.style.fontSize = currentPt + 'pt';
        }
    }
}

// -------------------------------------------------------------------------
// LIVE A4 RENDERING: PAGE 2 (ใบตรวจสอบการเข้าเรียนนักศึกษา 18 สัปดาห์)
// -------------------------------------------------------------------------
function generateA4Page2HTML(claim = activeClaim) {
    if (!claim) return '';

    const weeks = claim.weeks || [];
    const students = claim.students || [];
    const sig = claim.signatures || {};

    // Header 18 dates vertical cells
    let weekHeaderCols = '';
    weeks.forEach(w => {
        weekHeaderCols += `
            <th style="width: 17px; min-width: 17px; max-width: 17px; height: 62px; padding: 2px 0; text-align: center; vertical-align: bottom; border: 1px solid #000; box-sizing: border-box;">
                <div style="writing-mode: vertical-rl; transform: rotate(180deg); font-size: 13px; font-weight: 500; white-space: nowrap; margin: 0 auto; letter-spacing: -0.2px;">
                    ${w.dateStr}
                </div>
            </th>
        `;
    });

    // Student rows: ตัดตามจำนวนนักศึกษาจริง ไม่สร้างช่องเปล่าต่อท้าย
    let studentRowsHtml = '';
    const totalRenderRows = students.length;

    for (let i = 0; i < totalRenderRows; i++) {
        const st = students[i];
        const rowNo = i + 1;

        let weekCells = '';
        weeks.forEach(w => {
            if (w.isHoliday) {
                // Red shaded holiday cell as per RC reference PDF
                weekCells += `<td style="background-color: #ff0000; border: 1px solid #000; padding: 0; width: 17px; min-width: 17px; max-width: 17px; box-sizing: border-box;"></td>`;
            } else {
                // Blank check cell as per RC reference PDF
                weekCells += `<td style="border: 1px solid #000; padding: 0; width: 17px; min-width: 17px; max-width: 17px; box-sizing: border-box;"></td>`;
            }
        });

        let fName = (st.name || '').trim();
        let lName = (st.surname || '').trim();
        if (!lName && fName) {
            const splitted = splitThaiFullName(fName);
            fName = splitted.name;
            lName = splitted.surname;
        }

        studentRowsHtml += `
            <tr style="height: 22px;">
                <td style="text-align: center; font-size: 14pt; border: 1px solid #000;">${rowNo}</td>
                <td style="text-align: center; font-size: 14pt; white-space: nowrap; padding: 2px 3px; border: 1px solid #000;">${st.studentId || ''}</td>
                <td style="padding: 2px 4px; white-space: nowrap; font-size: 14pt; border: 1px solid #000;">${fName}</td>
                <td style="padding: 2px 4px; white-space: nowrap; font-size: 14pt; border: 1px solid #000;">${lName}</td>
                ${weekCells}
                <td style="border: 1px solid #000;"></td>
            </tr>
        `;
    }

    const p2TermFormatted = (claim.academicYear || '1/2568').trim().startsWith('ภาคเรียนที่')
        ? (claim.academicYear || '1/2568').trim()
        : `ภาคเรียนที่ ${claim.academicYear || '1/2568'}`;

    return `
        <div style="font-family: 'TH Sarabun New', 'TH Sarabun PSK', 'Sarabun', Tahoma, sans-serif; line-height: 1.25; color: #000; font-size: 14pt;">
            
            <!-- Page 2 Header -->
            <div style="text-align: center; font-size: 18pt; font-weight: bold; margin-bottom: 2px;">
                ใบตรวจสอบการเข้าเรียนนักศึกษา ระดับปริญญาตรี หลักสูตรเทคโนโลยีบัณฑิต (ทล.บ.)
            </div>
            <div style="text-align: center; font-size: 15pt; font-weight: bold; margin-bottom: 2px;">
                สาขาวิชา ${claim.department || 'เทคโนโลยีโยธา'} ${p2TermFormatted}
            </div>
            <div style="text-align: center; font-size: 14pt; margin-bottom: 2px;">
                วิชา ${claim.subjectName} รหัสวิชา ${claim.subjectCode} สัปดาห์ที่ ${claim.teachingDaysPerWeek > 1 ? `1-${claim.totalWeeks || Math.ceil(18 / claim.teachingDaysPerWeek)} (18 ครั้ง)` : '1-18'}
            </div>
            <div style="text-align: center; font-size: 14pt; margin-bottom: 2px;">
                ระหว่างวันที่ ${formatThaiDateFull(claim.startDate)} ถึง วันที่ ${claim.endDateThai || ''}
            </div>
            <div style="text-align: center; font-size: 14pt; margin-bottom: 8px;">
                อาจารย์ผู้สอน ${claim.teacherName || ''}
            </div>

            <!-- Attendance Table (18 Weeks) - จัดกลางหน้ากระดาษและระบุขนาดคอลัมน์ชัดเจน -->
            <table class="doc-table" style="width: 100%; border-collapse: collapse; font-family: 'TH Sarabun New', 'TH Sarabun PSK', 'Sarabun', Tahoma, sans-serif; font-size: 14pt; margin: 0 auto 10px auto; table-layout: fixed;">
                <thead>
                    <tr style="background-color: #f1f5f9;">
                        <th rowspan="2" style="width: 36px; text-align: center; font-size: 14pt; padding: 3px 2px; border: 1px solid #000; white-space: nowrap;">ลำดับ</th>
                        <th rowspan="2" style="width: 94px; text-align: center; font-size: 14pt; white-space: nowrap; padding: 3px 2px; border: 1px solid #000;">รหัสประจำตัว</th>
                        <th rowspan="2" style="width: 120px; text-align: center; font-size: 14pt; white-space: nowrap; padding: 3px 2px; border: 1px solid #000;">ชื่อ</th>
                        <th rowspan="2" style="width: 88px; text-align: center; font-size: 14pt; white-space: nowrap; padding: 3px 2px; border: 1px solid #000;">นามสกุล</th>
                        <th colspan="18" style="width: 306px; text-align: center; padding: 3px 0; font-size: 14pt; border: 1px solid #000;">สัปดาห์ที่ ${claim.teachingDaysPerWeek > 1 ? `1-${claim.totalWeeks || Math.ceil(18 / claim.teachingDaysPerWeek)} (18 ครั้ง)` : '1-18'}</th>
                        <th rowspan="2" style="width: 96px; text-align: center; font-size: 14pt; white-space: nowrap; padding: 3px 2px; border: 1px solid #000;">ลายเซ็นต์นักศึกษา</th>
                    </tr>
                    <tr style="background-color: #f8fafc;">
                        ${weekHeaderCols}
                    </tr>
                </thead>
                <tbody>
                    ${studentRowsHtml}
                </tbody>
            </table>

            <!-- Page 2 Footer: Legend & Signatures -->
            <div style="display: flex; justify-content: space-between; align-items: flex-start; font-size: 14pt; margin-top: 44px;">
                
                <!-- Legend -->
                <div style="line-height: 1.5; padding-left: 8px;">
                    <table style="border: none; border-collapse: collapse; font-size: 14pt;">
                        <tr><td style="font-weight: bold; padding-right: 14px; border:none; vertical-align: top;">หมายเหตุ</td><td style="width:22px; border:none; text-align:center; font-weight:bold;">/</td><td style="border:none;">มาเรียน</td></tr>
                        <tr><td style="border:none;"></td><td style="border:none; text-align:center; font-weight:bold;">0</td><td style="border:none;">ขาดเรียน</td></tr>
                        <tr><td style="border:none;"></td><td style="border:none; text-align:center; font-weight:bold;">L</td><td style="border:none;">มาสาย</td></tr>
                        <tr><td style="border:none;"></td><td style="border:none; text-align:center; font-weight:bold;">S</td><td style="border:none;">ลาป่วย</td></tr>
                    </table>
                </div>

                <!-- Signatures -->
                <div style="text-align: center; line-height: 1.6; font-size: 14pt; padding-right: 20px;">
                    <div style="margin-bottom: 26px;">
                        ลงชื่อ........................................................<br>
                        ( ${sig.teacher || claim.teacherName || '........................................................'} )<br>
                        อาจารย์ผู้สอน
                    </div>
                    <div>
                        ลงชื่อ........................................................<br>
                        ( ${sig.programChair || sig.deptHead || 'นายปริวัฒน์ ยืนยิ่ง'} )<br>
                        ${sig.programChairRole || getFormattedDeptRole(claim.department || '', 'programChair')}
                    </div>
                </div>

            </div>

        </div>
    `;
}

function renderA4Page2() {
    const page2 = document.getElementById('doc-page-2');
    if (!page2 || !activeClaim) return;
    page2.innerHTML = generateA4Page2HTML(activeClaim);
}

// -------------------------------------------------------------------------
// CLAIM EVENT LISTENERS & BINDINGS
// -------------------------------------------------------------------------
let claimListenersInitialized = false;

function setupClaimEventListeners() {
    if (claimListenersInitialized) return;
    claimListenersInitialized = true;

    // Top Bar Back Button
    const btnBack = document.getElementById('btn-back-to-term');
    if (btnBack) {
        btnBack.addEventListener('click', () => {
            if (activeSubjectRef) {
                activeSubjectRef.claimData = JSON.parse(JSON.stringify(activeClaim));
                const totals = calculateClaimTotals();
                activeSubjectRef.hours = totals.grandTotalHrs;
                activeSubjectRef.studentCount = activeClaim.students ? activeClaim.students.length : (activeClaim.studentCount || 0);
                const term = appData.terms.find(t => t.id === currentTermId);
                if (term) {
                    const autoHours = calculateTermTotalHours(term);
                    term.totalTeachingHours = autoHours;
                    if (term.budget > 0 && autoHours > 0 && !activeClaim.rateCustomized) {
                        term.hourlyRate = Math.floor(term.budget / autoHours);
                    }
                }
                saveData();
            }
            switchView('subjects', currentTermId);
        });
    }

    // Save Claim Button
    const btnSave = document.getElementById('btn-save-claim');
    if (btnSave) {
        btnSave.addEventListener('click', () => {
            if (activeSubjectRef) {
                activeSubjectRef.claimData = JSON.parse(JSON.stringify(activeClaim));
                // Sync subject hours and rate back to card
                const totals = calculateClaimTotals();
                activeSubjectRef.hours = totals.grandTotalHrs;
                activeSubjectRef.rate = activeClaim.rate;
                activeSubjectRef.level = activeClaim.level || activeSubjectRef.level || 'ชั้นปี 1';
                activeSubjectRef.time = activeClaim.timeStr || activeSubjectRef.time || '17.00-20.00';
                activeSubjectRef.studentCount = activeClaim.students ? activeClaim.students.length : 0;
                const matchedTeacher = (appData.teachers || []).find(t => t.name === activeClaim.teacherName);
                if (matchedTeacher) {
                    activeSubjectRef.teacherId = matchedTeacher.id;
                }
                const term = appData.terms.find(t => t.id === currentTermId);
                if (term) {
                    const autoHours = calculateTermTotalHours(term);
                    term.totalTeachingHours = autoHours;
                    if (term.budget > 0 && autoHours > 0 && !activeClaim.rateCustomized) {
                        term.hourlyRate = Math.floor(term.budget / autoHours);
                    }
                }
                saveData();
                alert('✓ บันทึกข้อมูลใบเบิกและตาราง 18 สัปดาห์เรียบร้อยแล้ว');
            }
        });
    }

    // Reset RC Button
    const btnResetRC = document.getElementById('btn-reset-rc');
    if (btnResetRC) {
        btnResetRC.addEventListener('click', () => {
            if (confirm('ต้องการรีเซ็ตข้อมูลใบเบิกเป็น "ค่าเริ่มต้นวิชา RC" ตามแบบฟอร์มต้นฉบับหรือไม่?')) {
                activeClaim = JSON.parse(JSON.stringify(DEFAULT_RC_CLAIM));
                populateSidebarFromClaimData();
                renderWeeksEditor();
                renderStudentsEditor();
                renderA4Page1();
                renderA4Page2();
                alert('รีเซ็ตข้อมูลตามต้นฉบับวิชา RC เรียบร้อยแล้ว');
            }
        });
    }

    // Export JSON Button
    const btnExport = document.getElementById('btn-export-json');
    if (btnExport) {
        btnExport.addEventListener('click', () => {
            const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(activeClaim, null, 2));
            const downloadAnchor = document.createElement('a');
            downloadAnchor.setAttribute("href", dataStr);
            downloadAnchor.setAttribute("download", `ใบเบิก_${activeClaim.subjectCode}_${activeClaim.subjectName}.json`);
            document.body.appendChild(downloadAnchor);
            downloadAnchor.click();
            downloadAnchor.remove();
        });
    }

    // Print Button
    const btnPrint = document.getElementById('btn-print-claim');
    if (btnPrint) {
        btnPrint.addEventListener('click', () => {
            // Show both pages for printing
            const p1 = document.getElementById('doc-page-1');
            const p2 = document.getElementById('doc-page-2');
            if (p1) p1.classList.remove('hidden');
            if (p2) p2.classList.remove('hidden');
            window.print();
        });
    }

    // Page Switchers
    const btnP1 = document.getElementById('btn-page-1');
    const btnP2 = document.getElementById('btn-page-2');
    const btnPAll = document.getElementById('btn-page-all');
    const p1 = document.getElementById('doc-page-1');
    const p2 = document.getElementById('doc-page-2');

    function setActivePageBtn(activeBtn) {
        [btnP1, btnP2, btnPAll].forEach(b => {
            if (b) {
                b.classList.remove('active', 'bg-blue-600', 'text-white', 'font-medium');
                b.classList.add('bg-[#141725]', 'text-gray-300');
            }
        });
        if (activeBtn) {
            activeBtn.classList.add('active', 'bg-blue-600', 'text-white', 'font-medium');
            activeBtn.classList.remove('bg-[#141725]', 'text-gray-300');
        }
    }

    if (btnP1) {
        btnP1.addEventListener('click', () => {
            if (p1) p1.classList.remove('hidden');
            if (p2) p2.classList.add('hidden');
            setActivePageBtn(btnP1);
        });
    }

    if (btnP2) {
        btnP2.addEventListener('click', () => {
            if (p1) p1.classList.add('hidden');
            if (p2) p2.classList.remove('hidden');
            setActivePageBtn(btnP2);
        });
    }

    if (btnPAll) {
        btnPAll.addEventListener('click', () => {
            if (p1) p1.classList.remove('hidden');
            if (p2) p2.classList.remove('hidden');
            setActivePageBtn(btnPAll);
        });
    }

    // Init Thai calendar
    initThaiCalendarPopup();

    // Claim Settings Button
    const btnClaimSettings = document.getElementById('btn-claim-settings');
    if (btnClaimSettings) {
        btnClaimSettings.addEventListener('click', () => {
            selectedTeacherSettingsIds.clear();
            selectedSubjectSettingsIds.clear();
            selectedStudentSettingsIds.clear();
            renderSettingsLists();
            openModal('modal-settings');
        });
    }

    // Sidebar Tab Switching
    document.querySelectorAll('.claim-tab-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            document.querySelectorAll('.claim-tab-btn').forEach(b => {
                b.classList.remove('active', 'text-blue-400', 'bg-blue-900/40', 'font-medium');
                b.classList.add('text-gray-400');
            });
            btn.classList.add('active', 'text-blue-400', 'bg-blue-900/40', 'font-medium');
            btn.classList.remove('text-gray-400');

            document.querySelectorAll('.claim-tab-content').forEach(c => c.classList.add('hidden'));
            const targetId = btn.getAttribute('data-target');
            const target = document.getElementById(targetId);
            if (target) target.classList.remove('hidden');
        });
    });

    // Reset Weeks Default button in Tab 2
    const btnResetWeeks = document.getElementById('btn-reset-weeks-default');
    if (btnResetWeeks) {
        btnResetWeeks.addEventListener('click', () => {
            recalculateClaimSchedule(false);
            renderWeeksEditor();
            updateCalculationsAndPreview();
        });
    }

    // Add Student Button in Tab 4 (Open multi-select modal)
    const btnAddStudent = document.getElementById('btn-add-student-to-subject');
    if (btnAddStudent) {
        btnAddStudent.addEventListener('click', () => {
            openSelectStudentsClaimModal();
        });
    }

    // Initialize Teacher Autocomplete in Tab 1
    initClaimTeacherAutocomplete();
    initUniversalClaimAutocompletes();

    // Live Sidebar Input Listeners (Tab 1: Subject info)
    const bindLiveInput = (id, property, updateCallback) => {
        const el = document.getElementById(id);
        if (el) {
            el.addEventListener('input', () => {
                activeClaim[property] = el.value;
                if (updateCallback) updateCallback();
                else updateCalculationsAndPreview();
            });
        }
    };

    bindLiveInput('claim-input-dept', 'department', () => {
        if (activeSubjectRef) activeSubjectRef.department = activeClaim.department;
        const deptName = activeClaim.department || 'เทคโนโลยีโยธา';
        const lblPC = document.getElementById('label-sig-program-chair');
        if (lblPC) lblPC.textContent = `2. ประธานหลักสูตรสาขาวิชา${deptName}`;
        const lblDH = document.getElementById('label-sig-dept-head');
        if (lblDH) lblDH.textContent = `4. หัวหน้าสาขาวิชา${deptName}`;

        const formattedRole = getFormattedDeptRole(deptName, 'deptHead');
        const formattedProgChairRole = getFormattedDeptRole(deptName, 'programChair');
        if (!activeClaim.signatures) activeClaim.signatures = {};
        activeClaim.signatures.deptHeadRole = formattedRole;
        activeClaim.signatures.programChairRole = formattedProgChairRole;
        if (activeSubjectRef) {
            if (!activeSubjectRef.signatures) activeSubjectRef.signatures = {};
            activeSubjectRef.signatures.deptHeadRole = formattedRole;
            activeSubjectRef.signatures.programChairRole = formattedProgChairRole;
        }
        const inpDHRole = document.getElementById('sig-dept-head-role');
        if (inpDHRole) inpDHRole.value = formattedRole;
        const inpPCRole = document.getElementById('sig-program-chair-role');
        if (inpPCRole) inpPCRole.value = formattedProgChairRole;

        renderA4Page1();
        renderA4Page2();
    });

    bindLiveInput('claim-input-level', 'level', () => {
        if (activeSubjectRef) activeSubjectRef.level = activeClaim.level;
        renderA4Page1();
        renderA4Page2();
    });

    bindLiveInput('claim-input-academic-year', 'academicYear', () => {
        renderA4Page1();
        renderA4Page2();
    });

    bindLiveInput('claim-input-code', 'subjectCode', () => {
        const hName = document.getElementById('claim-header-subject-name');
        if (hName) hName.textContent = `${activeClaim.subjectName} (${activeClaim.subjectCode})`;
        renderA4Page1();
        renderA4Page2();
    });

    bindLiveInput('claim-input-name', 'subjectName', () => {
        const hName = document.getElementById('claim-header-subject-name');
        if (hName) hName.textContent = `${activeClaim.subjectName} (${activeClaim.subjectCode})`;
        renderA4Page1();
        renderA4Page2();
    });

    bindLiveInput('claim-input-credits', 'credits', () => {
        const cr = parseInt(document.getElementById('claim-input-credits').value, 10) || 3;
        activeClaim.credits = cr;
        if (activeSubjectRef) {
            activeSubjectRef.credits = cr;
            if (activeSubjectRef.claimData) activeSubjectRef.claimData.credits = cr;
        }
        renderA4Page1();
        saveData();
    });

    const elThHrs = document.getElementById('claim-input-theory-hours');
    const elPrHrs = document.getElementById('claim-input-practice-hours');
    const elWkHrs = document.getElementById('claim-input-weekly-hours');

    function updateHoursFromInputs() {
        const th = parseInt(elThHrs ? elThHrs.value : 3) || 0;
        const pr = parseInt(elPrHrs ? elPrHrs.value : 0) || 0;
        const total = th + pr;
        activeClaim.theoryHours = th;
        activeClaim.practiceHours = pr;
        activeClaim.weeklyHours = total;
        if (elWkHrs) elWkHrs.value = total;
        if (activeClaim.teachingDaysPerWeek === 1 && activeClaim.teachingDays && activeClaim.teachingDays[0]) {
            activeClaim.teachingDays[0].hours = total;
            activeClaim.day1Hours = total;
            const day1HoursInp = document.querySelector('.input-day-hours');
            if (day1HoursInp) day1HoursInp.value = total;
            (activeClaim.weeks || []).forEach(w => {
                if (w.dayNo === 1 && !w.isHoliday) {
                    w.theoryHrs = th;
                    w.practiceHrs = pr;
                    w.totalHrs = total;
                }
            });
        }
        renderWeeksEditor();
        updateCalculationsAndPreview();
        renderA4Page1();
    }

    if (elThHrs) elThHrs.addEventListener('input', updateHoursFromInputs);
    if (elPrHrs) elPrHrs.addEventListener('input', updateHoursFromInputs);
    if (elWkHrs) {
        elWkHrs.addEventListener('input', () => {
            const val = parseInt(elWkHrs.value) || 0;
            activeClaim.weeklyHours = val;
            if (activeClaim.teachingDaysPerWeek === 1 && activeClaim.teachingDays && activeClaim.teachingDays[0]) {
                activeClaim.teachingDays[0].hours = val;
                activeClaim.day1Hours = val;
                const day1HoursInp = document.querySelector('.input-day-hours');
                if (day1HoursInp) day1HoursInp.value = val;
                (activeClaim.weeks || []).forEach(w => {
                    if (w.dayNo === 1 && !w.isHoliday) {
                        w.theoryHrs = val;
                        w.totalHrs = val;
                    }
                });
            }
            renderWeeksEditor();
            updateCalculationsAndPreview();
            renderA4Page1();
        });
    }

    // Flexible teaching days per week input
    const inputDaysMode = document.getElementById('claim-input-days-per-week');
    if (inputDaysMode) {
        inputDaysMode.addEventListener('input', () => {
            let val = parseInt(inputDaysMode.value);
            if (isNaN(val) || val < 1) val = 1;
            if (val > 7) val = 7;
            activeClaim.teachingDaysPerWeek = val;
            ensureTeachingDays();
            recalculateClaimSchedule(true);
            populateSidebarFromClaimData();
            renderWeeksEditor();
            updateCalculationsAndPreview();
        });
    }

    // Quick Day Preset buttons
    document.querySelectorAll('.btn-quick-day-preset').forEach(btn => {
        btn.addEventListener('click', () => {
            const days = parseInt(btn.getAttribute('data-days')) || 1;
            const inputDays = document.getElementById('claim-input-days-per-week');
            if (inputDays) inputDays.value = days;
            activeClaim.teachingDaysPerWeek = days;
            ensureTeachingDays();
            recalculateClaimSchedule(true);
            populateSidebarFromClaimData();
            renderWeeksEditor();
            updateCalculationsAndPreview();
        });
    });

    // Add / Remove teaching day buttons
    const btnAddDay = document.getElementById('btn-add-teaching-day');
    if (btnAddDay) {
        btnAddDay.addEventListener('click', () => {
            let cur = parseInt(activeClaim.teachingDaysPerWeek) || 1;
            if (cur < 7) {
                cur++;
                activeClaim.teachingDaysPerWeek = cur;
                const inputDays = document.getElementById('claim-input-days-per-week');
                if (inputDays) inputDays.value = cur;
                ensureTeachingDays();
                recalculateClaimSchedule(true);
                populateSidebarFromClaimData();
                renderWeeksEditor();
                updateCalculationsAndPreview();
            }
        });
    }

    const btnRemoveDay = document.getElementById('btn-remove-teaching-day');
    if (btnRemoveDay) {
        btnRemoveDay.addEventListener('click', () => {
            let cur = parseInt(activeClaim.teachingDaysPerWeek) || 1;
            if (cur > 1) {
                cur--;
                activeClaim.teachingDaysPerWeek = cur;
                const inputDays = document.getElementById('claim-input-days-per-week');
                if (inputDays) inputDays.value = cur;
                ensureTeachingDays();
                recalculateClaimSchedule(true);
                populateSidebarFromClaimData();
                renderWeeksEditor();
                updateCalculationsAndPreview();
            }
        });
    }

    // Summer table layout option for Page 1
    const selSummerLayout = document.getElementById('claim-summer-layout');
    if (selSummerLayout) {
        selSummerLayout.addEventListener('change', () => {
            activeClaim.summerTableLayout = selSummerLayout.value;
            renderA4Page1();
        });
    }

    const btnRecalc = document.getElementById('btn-recalculate-calendar');
    if (btnRecalc) {
        btnRecalc.addEventListener('click', () => {
            recalculateClaimSchedule(false);
            const inpStartTh = document.getElementById('claim-input-start-date-th');
            if (inpStartTh) inpStartTh.value = formatThaiBEDate(activeClaim.startDate);
            renderWeeksEditor();
            updateCalculationsAndPreview();
        });
    }

    const inputStartDate = document.getElementById('claim-input-start-date');
    if (inputStartDate) {
        inputStartDate.addEventListener('change', () => {
            handleStartDateChange(inputStartDate.value);
        });
    }

    bindLiveInput('claim-input-rate', 'rate', () => {
        const val = parseFloat(document.getElementById('claim-input-rate').value) || 0;
        activeClaim.rate = val;
        activeClaim.rateCustomized = true;
        if (activeSubjectRef) {
            activeSubjectRef.rate = val;
            if (activeSubjectRef.claimData) activeSubjectRef.claimData.rate = val;
            saveData();
        }
        updateCalculationsAndPreview();
    });

    bindLiveInput('claim-input-percent', 'percent', () => {
        activeClaim.percent = parseFloat(document.getElementById('claim-input-percent').value) || 0;
        renderA4Page1();
    });

    const inputStudents = document.getElementById('claim-input-students');
    if (inputStudents) {
        const handleStudentCountChange = () => {
            const rawVal = inputStudents.value.trim();
            if (rawVal === '') return;
            let count = parseInt(rawVal, 10);
            if (isNaN(count) || count < 0) count = 0;

            if (!activeClaim.students) activeClaim.students = [];

            while (activeClaim.students.length < count) {
                const idx = activeClaim.students.length + 1;
                activeClaim.students.push({
                    studentId: `6840121100${idx}`,
                    name: `นักศึกษาคนที่ ${idx}`,
                    surname: ''
                });
            }
            if (activeClaim.students.length > count) {
                activeClaim.students = activeClaim.students.slice(0, count);
            }

            activeClaim.studentCount = count;
            if (activeSubjectRef) {
                activeSubjectRef.studentCount = count;
                if (activeSubjectRef.claimData) {
                    activeSubjectRef.claimData.students = activeClaim.students;
                    activeSubjectRef.claimData.studentCount = count;
                }
            }

            const badge = document.getElementById('claim-student-count-badge');
            if (badge) badge.textContent = count;

            renderStudentsEditor();
            renderA4Page1();
            renderA4Page2();
            saveData();
        };

        inputStudents.addEventListener('input', handleStudentCountChange);
        inputStudents.addEventListener('change', () => {
            if (inputStudents.value.trim() === '') {
                inputStudents.value = activeClaim.students ? activeClaim.students.length : 0;
            } else {
                handleStudentCountChange();
            }
        });
    }

    const inputTotalHours = document.getElementById('claim-input-total-hours');
    if (inputTotalHours) {
        inputTotalHours.addEventListener('input', () => {
            const rawVal = inputTotalHours.value.trim();
            if (rawVal === '') {
                delete activeClaim.customTotalHours;
            } else {
                const parsed = parseFloat(rawVal);
                activeClaim.customTotalHours = isNaN(parsed) ? 0 : parsed;
            }
            if (activeSubjectRef) {
                if (activeSubjectRef.claimData) {
                    activeSubjectRef.claimData.customTotalHours = activeClaim.customTotalHours;
                }
            }
            updateCalculationsAndPreview();
        });
    }

    const btnSyncHours = document.getElementById('btn-sync-claim-hours');
    if (btnSyncHours) {
        btnSyncHours.addEventListener('click', () => {
            delete activeClaim.customTotalHours;
            if (activeSubjectRef && activeSubjectRef.claimData) {
                delete activeSubjectRef.claimData.customTotalHours;
            }
            const totals = calculateClaimTotals(activeClaim);
            if (inputTotalHours) inputTotalHours.value = totals.tableHours;
            updateCalculationsAndPreview();
        });
    }

    // Signatures Live Inputs (Tab 3)
    const bindSigInput = (id, propKey) => {
        const el = document.getElementById(id);
        if (el) {
            el.addEventListener('input', () => {
                if (!activeClaim.signatures) activeClaim.signatures = {};
                activeClaim.signatures[propKey] = el.value;
                if (propKey === 'teacher') {
                    activeClaim.teacherName = el.value;
                    const cTeacher = document.getElementById('claim-input-teacher');
                    if (cTeacher) cTeacher.value = el.value;
                } else {
                    updateDefaultSignatures2To9({ [propKey]: el.value });
                }
                saveActiveClaim();
                renderA4Page1();
                renderA4Page2();
            });
        }
    };

    bindSigInput('sig-teacher-name', 'teacher');
    bindSigInput('sig-program-chair', 'programChair');
    bindSigInput('sig-program-chair-role', 'programChairRole');
    bindSigInput('sig-curriculum-head', 'curriculumHead');
    bindSigInput('sig-dept-head', 'deptHead');
    bindSigInput('sig-dept-head-role', 'deptHeadRole');
    bindSigInput('sig-tech-head', 'techHead');
    bindSigInput('sig-academic-deputy', 'academicDeputy');
    bindSigInput('sig-finance-head', 'financeHead');
    bindSigInput('sig-resource-deputy', 'resourceDeputy');
    bindSigInput('sig-director', 'director');

    // Apply all signatures (except teacher) to all subjects in current term
    const btnApplyAllSigs = document.getElementById('btn-apply-all-signatures');
    if (btnApplyAllSigs) {
        btnApplyAllSigs.addEventListener('click', () => {
            const curTerm = appData.terms.find(t => t.id === currentTermId);
            if (!curTerm || !curTerm.subjects || curTerm.subjects.length === 0) {
                alert('ไม่พบรายวิชาในภาคเรียนนี้');
                return;
            }

            const sig = activeClaim.signatures || {};
            let count = 0;
            curTerm.subjects.forEach(sub => {
                if (!sub.claimData) {
                    sub.claimData = JSON.parse(JSON.stringify(DEFAULT_RC_CLAIM));
                }
                if (!sub.claimData.signatures) sub.claimData.signatures = {};

                // Copy positions 2 through 9 and their role titles
                sub.claimData.signatures.programChair = sig.programChair || '';
                sub.claimData.signatures.programChairRole = sig.programChairRole || '';
                sub.claimData.signatures.curriculumHead = sig.curriculumHead || '';
                sub.claimData.signatures.curriculumHeadRole = sig.curriculumHeadRole || '';
                sub.claimData.signatures.deptHead = sig.deptHead || '';
                sub.claimData.signatures.deptHeadRole = sig.deptHeadRole || '';
                sub.claimData.signatures.techHead = sig.techHead || '';
                sub.claimData.signatures.techHeadRole = sig.techHeadRole || '';
                sub.claimData.signatures.academicDeputy = sig.academicDeputy || '';
                sub.claimData.signatures.academicDeputyRole = sig.academicDeputyRole || '';
                sub.claimData.signatures.financeHead = sig.financeHead || '';
                sub.claimData.signatures.financeHeadRole = sig.financeHeadRole || '';
                sub.claimData.signatures.resourceDeputy = sig.resourceDeputy || '';
                sub.claimData.signatures.resourceDeputyRole = sig.resourceDeputyRole || '';
                sub.claimData.signatures.director = sig.director || '';
                sub.claimData.signatures.directorRole = sig.directorRole || '';

                // Ensure teacher name is preserved from each subject's own teacher
                const masterTeacher = appData.teachers.find(t => t.id === sub.teacherId)?.name;
                sub.claimData.signatures.teacher = sub.claimData.teacherName || masterTeacher || sub.claimData.signatures.teacher || '';
                count++;
            });

            updateDefaultSignatures2To9(sig);
            saveData();
            alert(`นำชุดรายชื่อผู้ลงนาม (ข้อ 2-9) ไปใช้กับทั้ง ${count} รายวิชาในภาคเรียนนี้เรียบร้อยแล้ว\n(ระบบบันทึกจดจำไว้เป็นค่าเริ่มต้นของเทอมต่อๆ ไปด้วยโดยอัตโนมัติ)`);
        });
    }

    // Apply single signature field to all subjects in current term
    document.querySelectorAll('.btn-apply-single-sig').forEach(btn => {
        btn.addEventListener('click', () => {
            const field = btn.getAttribute('data-field');
            const inputId = btn.getAttribute('data-input-id');
            if (!field) return;
            const curTerm = appData.terms.find(t => t.id === currentTermId);
            if (!curTerm || !curTerm.subjects || curTerm.subjects.length === 0) {
                alert('ไม่พบรายวิชาในภาคเรียนนี้');
                return;
            }

            const currentVal = (activeClaim.signatures && activeClaim.signatures[field]) ? activeClaim.signatures[field] : (document.getElementById(inputId)?.value || '');
            let count = 0;
            curTerm.subjects.forEach(sub => {
                if (!sub.claimData) {
                    sub.claimData = JSON.parse(JSON.stringify(DEFAULT_RC_CLAIM));
                }
                if (!sub.claimData.signatures) sub.claimData.signatures = {};
                sub.claimData.signatures[field] = currentVal;

                // Ensure teacher name is preserved from each subject's own teacher
                const masterTeacher = appData.teachers.find(t => t.id === sub.teacherId)?.name;
                sub.claimData.signatures.teacher = sub.claimData.teacherName || masterTeacher || sub.claimData.signatures.teacher || '';
                count++;
            });

            if (field === 'deptHead') {
                const roleVal = document.getElementById('sig-dept-head-role')?.value || activeClaim.signatures?.deptHeadRole;
                if (roleVal) {
                    curTerm.subjects.forEach(sub => {
                        if (sub.claimData && sub.claimData.signatures) {
                            sub.claimData.signatures.deptHeadRole = roleVal;
                        }
                    });
                    updateDefaultSignatures2To9({ deptHeadRole: roleVal });
                }
            }
            if (field === 'programChair') {
                const roleVal = document.getElementById('sig-program-chair-role')?.value || activeClaim.signatures?.programChairRole;
                if (roleVal) {
                    curTerm.subjects.forEach(sub => {
                        if (sub.claimData && sub.claimData.signatures) {
                            sub.claimData.signatures.programChairRole = roleVal;
                        }
                    });
                    updateDefaultSignatures2To9({ programChairRole: roleVal });
                }
            }

            updateDefaultSignatures2To9({ [field]: currentVal });
            saveData();
            alert(`นำชื่อนี้ไปใช้กับตำแหน่งเดียวกันในทั้ง ${count} รายวิชาของภาคเรียนนี้เรียบร้อยแล้ว\n(พร้อมบันทึกจดจำไว้เป็นค่าเริ่มต้นของเทอมต่อๆ ไปด้วย)`);
        });
    });
}

// -------------------------------------------------------------------------
// UNIVERSAL AUTOCOMPLETE ENGINE (ระบบค้นหาและแนะนำตัวเลือกอัตโนมัติป้องกันพิมพ์ผิด)
// -------------------------------------------------------------------------

function escapeHtml(str) {
    if (str === undefined || str === null) return '';
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}

function highlightMatch(text, query) {
    if (!query || !text) return escapeHtml(text || '');
    const cleanQ = query.trim();
    if (!cleanQ) return escapeHtml(text);
    const escaped = cleanQ.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    try {
        const regex = new RegExp(`(${escaped})`, 'gi');
        return escapeHtml(text).replace(regex, '<span class="text-blue-400 font-bold bg-blue-500/20 px-0.5 rounded">$1</span>');
    } catch (e) {
        return escapeHtml(text);
    }
}

function filterAndSortSuggestions(list, query, getFields) {
    const q = (query || '').toLowerCase().trim();
    if (!q) {
        return list.slice(0, 30);
    }
    const matched = [];
    for (const item of list) {
        const { primary, secondary } = getFields(item);
        const pLower = (primary || '').toLowerCase();
        const sLower = (secondary || '').toLowerCase();
        if (pLower.startsWith(q)) {
            matched.push({ item, score: 0 });
        } else if (sLower.startsWith(q)) {
            matched.push({ item, score: 1 });
        } else if (pLower.includes(q)) {
            matched.push({ item, score: 2 });
        } else if (sLower.includes(q)) {
            matched.push({ item, score: 3 });
        }
    }
    matched.sort((a, b) => a.score - b.score);
    return matched.map(m => m.item);
}

function createAutocompleteDropdown(inputEl, options) {
    if (!inputEl) return;
    
    // Prevent duplicate binding
    if (inputEl._acInitialized) return;
    inputEl._acInitialized = true;

    inputEl.setAttribute('autocomplete', 'off');

    // Ensure parent element has relative positioning
    const parent = inputEl.parentElement;
    if (parent && window.getComputedStyle(parent).position === 'static') {
        parent.style.position = 'relative';
    }

    // Create dropdown element
    const dropdown = document.createElement('div');
    dropdown.className = 'autocomplete-popup hidden absolute left-0 right-0 top-full mt-1 bg-[#141725] border border-blue-500/50 rounded-xl max-h-56 overflow-y-auto z-[9999] shadow-2xl p-1 text-xs space-y-0.5';
    parent.appendChild(dropdown);

    let activeIndex = -1;
    let currentItems = [];

    function positionDropdown() {
        const rect = inputEl.getBoundingClientRect();
        const spaceBelow = window.innerHeight - rect.bottom;
        const spaceAbove = rect.top;
        if (spaceBelow < 200 && spaceAbove > spaceBelow) {
            dropdown.style.top = 'auto';
            dropdown.style.bottom = '100%';
            dropdown.style.marginTop = '0px';
            dropdown.style.marginBottom = '4px';
        } else {
            dropdown.style.top = '100%';
            dropdown.style.bottom = 'auto';
            dropdown.style.marginTop = '4px';
            dropdown.style.marginBottom = '0px';
        }
    }

    function renderDropdown(query = '') {
        const items = options.getItems(query) || [];
        currentItems = items;
        activeIndex = -1;

        dropdown.innerHTML = '';
        if (items.length === 0) {
            if (query.trim()) {
                dropdown.innerHTML = `<div class="p-2.5 text-center text-[11px] text-gray-500">ไม่พบ "${escapeHtml(query)}" ในคลัง (พิมพ์ระบุเองได้)</div>`;
                positionDropdown();
                dropdown.classList.remove('hidden');
            } else {
                dropdown.classList.add('hidden');
            }
            return;
        }

        const maxDisplay = 30;
        const displayItems = items.slice(0, maxDisplay);

        displayItems.forEach((item, index) => {
            const itemDiv = document.createElement('div');
            itemDiv.className = 'ac-item p-2 hover:bg-blue-600/25 hover:text-white rounded-lg cursor-pointer transition text-xs flex justify-between items-center group text-left border-b border-[#2d3748]/40 last:border-0';
            itemDiv.setAttribute('data-index', index);

            itemDiv.innerHTML = `
                <div class="overflow-hidden pr-2 flex-1">
                    <div class="font-medium text-white group-hover:text-blue-200 truncate">${highlightMatch(item.title, query)}</div>
                    ${item.subtitle ? `<div class="text-[11px] text-gray-400 group-hover:text-gray-300 truncate mt-0.5">${highlightMatch(item.subtitle, query)}</div>` : ''}
                </div>
                <span class="text-[10px] bg-blue-500/20 text-blue-300 border border-blue-500/30 px-1.5 py-0.5 rounded whitespace-nowrap opacity-80 group-hover:opacity-100 flex-shrink-0">เลือก</span>
            `;

            itemDiv.addEventListener('mousedown', (e) => {
                e.preventDefault();
                selectItem(item);
            });

            dropdown.appendChild(itemDiv);
        });

        if (items.length > maxDisplay) {
            const moreHint = document.createElement('div');
            moreHint.className = 'p-1.5 text-center text-[10px] text-gray-500 border-t border-[#2d3748]/50 mt-1';
            moreHint.textContent = `พบทั้งหมด ${items.length} รายการ (พิมพ์ตัวอักษรเพื่อค้นหา)`;
            dropdown.appendChild(moreHint);
        }

        positionDropdown();
        dropdown.classList.remove('hidden');
    }

    function highlightActive() {
        const itemEls = dropdown.querySelectorAll('.ac-item');
        itemEls.forEach((el, i) => {
            if (i === activeIndex) {
                el.classList.add('bg-blue-600/35', 'text-white');
                el.scrollIntoView({ block: 'nearest' });
            } else {
                el.classList.remove('bg-blue-600/35', 'text-white');
            }
        });
    }

    function selectItem(item) {
        dropdown.classList.add('hidden');
        if (options.onSelect) {
            options.onSelect(item, inputEl);
        } else {
            inputEl.value = item.value || item.title;
            inputEl.dispatchEvent(new Event('input', { bubbles: true }));
        }
    }

    inputEl.addEventListener('input', () => {
        renderDropdown(inputEl.value);
    });

    inputEl.addEventListener('focus', () => {
        renderDropdown(inputEl.value);
    });

    inputEl.addEventListener('keydown', (e) => {
        if (dropdown.classList.contains('hidden')) {
            if (e.key === 'ArrowDown') {
                renderDropdown(inputEl.value);
                e.preventDefault();
            }
            return;
        }

        const count = Math.min(currentItems.length, 30);
        if (e.key === 'ArrowDown') {
            e.preventDefault();
            if (count > 0) {
                activeIndex = (activeIndex + 1) % count;
                highlightActive();
            }
        } else if (e.key === 'ArrowUp') {
            e.preventDefault();
            if (count > 0) {
                activeIndex = (activeIndex - 1 + count) % count;
                highlightActive();
            }
        } else if (e.key === 'Enter') {
            if (activeIndex >= 0 && activeIndex < currentItems.length) {
                e.preventDefault();
                selectItem(currentItems[activeIndex]);
            }
        } else if (e.key === 'Escape') {
            dropdown.classList.add('hidden');
        }
    });

    document.addEventListener('click', (e) => {
        if (!inputEl.contains(e.target) && !dropdown.contains(e.target)) {
            dropdown.classList.add('hidden');
        }
    });
}

function attachTeacherAutocomplete(inputEl, onSelectCallback) {
    if (!inputEl) return;
    createAutocompleteDropdown(inputEl, {
        getItems: (query) => {
            const sorted = filterAndSortSuggestions(appData.teachers || [], query, t => ({
                primary: t.name,
                secondary: ''
            }));
            return sorted.map(t => ({
                title: t.name,
                subtitle: 'บุคลากร วท.อุบลราชธานี',
                value: t.name,
                raw: t
            }));
        },
        onSelect: (item, el) => {
            el.value = item.value;
            el.dispatchEvent(new Event('input', { bubbles: true }));
            if (onSelectCallback) onSelectCallback(item.value, item.raw, el);
        }
    });
}

function initUniversalClaimAutocompletes() {
    // 1. Subject Name Autocomplete in Tab 1
    const nameInput = document.getElementById('claim-input-name');
    if (nameInput) {
        createAutocompleteDropdown(nameInput, {
            getItems: (query) => {
                const sorted = filterAndSortSuggestions(appData.subjects_master || [], query, s => ({
                    primary: s.name,
                    secondary: s.code
                }));
                return sorted.map(s => ({
                    title: s.name,
                    subtitle: `รหัส ${s.code} • ${s.credits || 3} นก. • ${s.hours || 3} ชม.`,
                    value: s.name,
                    raw: s
                }));
            },
            onSelect: (item, el) => {
                const s = item.raw;
                el.value = s.name;
                activeClaim.subjectName = s.name;
                const elCode = document.getElementById('claim-input-code');
                if (elCode && s.code) {
                    elCode.value = s.code;
                    activeClaim.subjectCode = s.code;
                }
                const elCredits = document.getElementById('claim-input-credits');
                if (elCredits && s.credits) {
                    elCredits.value = s.credits;
                    activeClaim.credits = s.credits;
                }
                const thHrs = s.theoryHours !== undefined ? s.theoryHours : 3;
                const prHrs = s.practiceHours !== undefined ? s.practiceHours : 0;
                const weeklyHrs = s.hours || (thHrs + prHrs);
                const elTh = document.getElementById('claim-input-theory-hours');
                if (elTh) elTh.value = thHrs;
                const elPr = document.getElementById('claim-input-practice-hours');
                if (elPr) elPr.value = prHrs;
                const inpHours = document.getElementById('claim-input-weekly-hours');
                if (inpHours) inpHours.value = weeklyHrs;
                activeClaim.theoryHours = thHrs;
                activeClaim.practiceHours = prHrs;
                activeClaim.weeklyHours = weeklyHrs;

                if (activeClaim.teachingDaysPerWeek === 1 && activeClaim.teachingDays && activeClaim.teachingDays[0]) {
                    activeClaim.teachingDays[0].hours = weeklyHrs;
                    activeClaim.day1Hours = weeklyHrs;
                    const day1HoursInp = document.querySelector('.input-day-hours');
                    if (day1HoursInp) day1HoursInp.value = weeklyHrs;
                    (activeClaim.weeks || []).forEach(w => {
                        if (w.dayNo === 1 && !w.isHoliday) {
                            w.theoryHrs = thHrs;
                            w.practiceHrs = prHrs;
                            w.totalHrs = weeklyHrs;
                        }
                    });
                }
                const headerName = document.getElementById('claim-header-subject-name');
                if (headerName) headerName.textContent = `${s.name} (${s.code || ''})`;
                if (activeSubjectRef) {
                    activeSubjectRef.name = s.name;
                    if (s.code) activeSubjectRef.code = s.code;
                    if (s.credits) activeSubjectRef.credits = s.credits;
                    saveData();
                }
                updateCalculationsAndPreview();
                renderWeeksEditor();
                renderA4Page1();
                renderA4Page2();
            }
        });
    }

    // 2. Subject Code Autocomplete in Tab 1
    const codeInput = document.getElementById('claim-input-code');
    if (codeInput) {
        createAutocompleteDropdown(codeInput, {
            getItems: (query) => {
                const sorted = filterAndSortSuggestions(appData.subjects_master || [], query, s => ({
                    primary: s.code,
                    secondary: s.name
                }));
                return sorted.map(s => ({
                    title: s.code,
                    subtitle: `${s.name} (${s.credits || 3} นก.)`,
                    value: s.code,
                    raw: s
                }));
            },
            onSelect: (item, el) => {
                const s = item.raw;
                el.value = s.code;
                activeClaim.subjectCode = s.code;
                const elName = document.getElementById('claim-input-name');
                if (elName && s.name) {
                    elName.value = s.name;
                    activeClaim.subjectName = s.name;
                }
                const elCredits = document.getElementById('claim-input-credits');
                if (elCredits && s.credits) {
                    elCredits.value = s.credits;
                    activeClaim.credits = s.credits;
                }
                const thHrs = s.theoryHours !== undefined ? s.theoryHours : 3;
                const prHrs = s.practiceHours !== undefined ? s.practiceHours : 0;
                const weeklyHrs = s.hours || (thHrs + prHrs);
                const elTh = document.getElementById('claim-input-theory-hours');
                if (elTh) elTh.value = thHrs;
                const elPr = document.getElementById('claim-input-practice-hours');
                if (elPr) elPr.value = prHrs;
                const inpHours = document.getElementById('claim-input-weekly-hours');
                if (inpHours) inpHours.value = weeklyHrs;
                activeClaim.theoryHours = thHrs;
                activeClaim.practiceHours = prHrs;
                activeClaim.weeklyHours = weeklyHrs;

                if (activeClaim.teachingDaysPerWeek === 1 && activeClaim.teachingDays && activeClaim.teachingDays[0]) {
                    activeClaim.teachingDays[0].hours = weeklyHrs;
                    activeClaim.day1Hours = weeklyHrs;
                    const day1HoursInp = document.querySelector('.input-day-hours');
                    if (day1HoursInp) day1HoursInp.value = weeklyHrs;
                    (activeClaim.weeks || []).forEach(w => {
                        if (w.dayNo === 1 && !w.isHoliday) {
                            w.theoryHrs = thHrs;
                            w.practiceHrs = prHrs;
                            w.totalHrs = weeklyHrs;
                        }
                    });
                }
                const headerName = document.getElementById('claim-header-subject-name');
                if (headerName) headerName.textContent = `${s.name || ''} (${s.code})`;
                if (activeSubjectRef) {
                    if (s.name) activeSubjectRef.name = s.name;
                    activeSubjectRef.code = s.code;
                    if (s.credits) activeSubjectRef.credits = s.credits;
                    saveData();
                }
                updateCalculationsAndPreview();
                renderWeeksEditor();
                renderA4Page1();
                renderA4Page2();
            }
        });
    }

    // 3. Tab 3 Signatures Autocomplete (9 Positions)
    const sigMap = [
        { id: 'sig-teacher-name', prop: 'teacher' },
        { id: 'sig-program-chair', prop: 'programChair' },
        { id: 'sig-curriculum-head', prop: 'curriculumHead' },
        { id: 'sig-dept-head', prop: 'deptHead' },
        { id: 'sig-tech-head', prop: 'techHead' },
        { id: 'sig-academic-deputy', prop: 'academicDeputy' },
        { id: 'sig-finance-head', prop: 'financeHead' },
        { id: 'sig-resource-deputy', prop: 'resourceDeputy' },
        { id: 'sig-director', prop: 'director' }
    ];

    sigMap.forEach(({ id, prop }) => {
        const el = document.getElementById(id);
        if (el) {
            attachTeacherAutocomplete(el, (name) => {
                if (!activeClaim.signatures) activeClaim.signatures = {};
                activeClaim.signatures[prop] = name;
                if (prop === 'teacher') {
                    activeClaim.teacherName = name;
                    const cTeacher = document.getElementById('claim-input-teacher');
                    if (cTeacher) cTeacher.value = name;
                } else {
                    updateDefaultSignatures2To9({ [prop]: name });
                }
                saveActiveClaim();
                renderA4Page1();
                renderA4Page2();
            });
        }
    });
}

// Autocomplete for Teacher input in Tab 1 (Claim form)
function initClaimTeacherAutocomplete() {
    const inputTeacher = document.getElementById('claim-input-teacher');
    const dropTeacher = document.getElementById('dropdown-claim-teacher-list');
    const btnClearTeacher = document.getElementById('btn-clear-claim-teacher');

    if (!inputTeacher || !dropTeacher) return;

    function renderTeacherDropdown(query = '') {
        const q = query.toLowerCase().trim();
        const matches = (appData.teachers || []).filter(t => {
            if (!q) return true;
            return t.name.toLowerCase().includes(q);
        });

        dropTeacher.innerHTML = '';
        if (matches.length === 0) {
            dropTeacher.innerHTML = '<div class="p-2.5 text-center text-xs text-gray-500">ไม่พบอาจารย์ที่ค้นหา (พิมพ์ชื่อเองได้)</div>';
        } else {
            const displayList = q ? matches.slice(0, 50) : matches.slice(0, 30);
            displayList.forEach(t => {
                const item = document.createElement('div');
                item.className = 'p-2 hover:bg-blue-600/20 hover:text-blue-200 rounded-lg cursor-pointer transition text-xs flex justify-between items-center border-b border-[#2d3748]/40 last:border-0';
                item.innerHTML = `
                    <div class="font-medium text-white">${t.name}</div>
                    <span class="text-[10px] bg-blue-500/20 text-blue-300 px-1.5 py-0.5 rounded ml-2">เลือก</span>
                `;
                item.addEventListener('click', (e) => {
                    e.stopPropagation();
                    selectTeacher(t.name);
                });
                dropTeacher.appendChild(item);
            });
            if (!q && matches.length > 30) {
                const hint = document.createElement('div');
                hint.className = 'p-1.5 text-center text-[10px] text-gray-500';
                hint.textContent = `พิมพ์ชื่อเพื่อค้นหาจากทั้งหมด ${matches.length} ท่าน`;
                dropTeacher.appendChild(hint);
            }
        }
        dropTeacher.classList.remove('hidden');
    }

    function selectTeacher(name) {
        inputTeacher.value = name;
        activeClaim.teacherName = name;
        if (!activeClaim.signatures) activeClaim.signatures = {};
        activeClaim.signatures.teacher = name;
        const sigTeacher = document.getElementById('sig-teacher-name');
        if (sigTeacher) sigTeacher.value = name;
        if (btnClearTeacher) btnClearTeacher.classList.remove('hidden');
        dropTeacher.classList.add('hidden');
        renderA4Page1();
        renderA4Page2();
    }

    inputTeacher.addEventListener('focus', () => renderTeacherDropdown(inputTeacher.value));
    inputTeacher.addEventListener('input', () => {
        const val = inputTeacher.value;
        activeClaim.teacherName = val;
        if (!activeClaim.signatures) activeClaim.signatures = {};
        activeClaim.signatures.teacher = val;
        const sigTeacher = document.getElementById('sig-teacher-name');
        if (sigTeacher) sigTeacher.value = val;
        if (val && btnClearTeacher) btnClearTeacher.classList.remove('hidden');
        else if (btnClearTeacher) btnClearTeacher.classList.add('hidden');
        renderTeacherDropdown(val);
        renderA4Page1();
        renderA4Page2();
    });

    if (btnClearTeacher) {
        btnClearTeacher.addEventListener('click', (e) => {
            e.stopPropagation();
            inputTeacher.value = '';
            activeClaim.teacherName = '';
            if (!activeClaim.signatures) activeClaim.signatures = {};
            activeClaim.signatures.teacher = '';
            const sigTeacher = document.getElementById('sig-teacher-name');
            if (sigTeacher) sigTeacher.value = '';
            btnClearTeacher.classList.add('hidden');
            dropTeacher.classList.add('hidden');
            renderA4Page1();
            renderA4Page2();
        });
    }

    document.addEventListener('click', (e) => {
        if (!e.target.closest('#claim-input-teacher') && !e.target.closest('#dropdown-claim-teacher-list')) {
            dropTeacher.classList.add('hidden');
        }
    });
}

// -------------------------------------------------------------------------
// THAI BUDDHIST CALENDAR POPUP & DATE PICKER
// -------------------------------------------------------------------------
let calCurrentYearBE = 2568;
let calCurrentMonth = 5; // 0-indexed (5 = June)
let thaiCalendarInitialized = false;

function initThaiCalendarPopup() {
    if (thaiCalendarInitialized) return;
    thaiCalendarInitialized = true;

    const inputTH = document.getElementById('claim-input-start-date-th');
    const inputISO = document.getElementById('claim-input-start-date');
    const btnOpen = document.getElementById('btn-open-thai-calendar');
    const popup = document.getElementById('thai-calendar-popup');
    const monthSelect = document.getElementById('cal-month-select');
    const yearSelect = document.getElementById('cal-year-select');
    const btnPrev = document.getElementById('cal-prev-month');
    const btnNext = document.getElementById('cal-next-month');
    const daysGrid = document.getElementById('cal-days-grid');
    const btnToday = document.getElementById('cal-btn-today');
    const holidayDetail = document.getElementById('cal-holiday-detail');

    if (!inputTH || !popup) return;

    // Populate Month Select
    monthSelect.innerHTML = THAI_MONTHS_FULL.map((m, idx) => `<option value="${idx}">${m}</option>`).join('');

    // Populate Year Select (BE 2565 to 2575)
    let yearOptions = '';
    for (let y = 2565; y <= 2575; y++) {
        yearOptions += `<option value="${y}">${y}</option>`;
    }
    yearSelect.innerHTML = yearOptions;

    function renderCalendarGrid() {
        daysGrid.innerHTML = '';
        const yearCE = calCurrentYearBE - 543;
        const firstDay = new Date(yearCE, calCurrentMonth, 1).getDay(); // 0 = Sun
        const daysInMonth = new Date(yearCE, calCurrentMonth + 1, 0).getDate();

        monthSelect.value = calCurrentMonth;
        yearSelect.value = calCurrentYearBE;
        if (holidayDetail) holidayDetail.textContent = '';

        const currentIso = inputISO ? inputISO.value : '';
        const now = new Date();
        const todayIso = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;

        // Empty padding cells before 1st of month
        for (let i = 0; i < firstDay; i++) {
            const blank = document.createElement('div');
            blank.className = 'h-8';
            daysGrid.appendChild(blank);
        }

        // Days of month
        for (let day = 1; day <= daysInMonth; day++) {
            const dateCE = new Date(yearCE, calCurrentMonth, day);
            const dateIso = `${yearCE}-${String(calCurrentMonth + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
            const holiday = getThaiHoliday(dateCE);
            const isSelected = dateIso === currentIso;
            const isToday = dateIso === todayIso;

            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = `cal-day-btn text-xs ${isSelected ? 'selected' : ''} ${isToday ? 'today' : ''} ${holiday ? 'holiday' : ''}`;
            btn.textContent = day;

            if (holiday) {
                btn.title = holiday.name;
                btn.addEventListener('mouseenter', () => {
                    if (holidayDetail) holidayDetail.textContent = `📌 ${holiday.name}`;
                });
                btn.addEventListener('mouseleave', () => {
                    if (holidayDetail) holidayDetail.textContent = '';
                });
            }

            btn.addEventListener('click', () => {
                if (inputISO) inputISO.value = dateIso;
                inputTH.value = formatThaiBEDate(dateIso);
                handleStartDateChange(dateIso);
                popup.classList.add('hidden');
            });

            daysGrid.appendChild(btn);
        }
    }

    function openCalendar() {
        const curIso = (inputISO && inputISO.value) ? inputISO.value : (activeClaim ? activeClaim.startDate : "2025-06-02");
        const d = new Date(curIso);
        if (!isNaN(d.getTime())) {
            calCurrentMonth = d.getMonth();
            calCurrentYearBE = d.getFullYear() + 543;
        }
        renderCalendarGrid();
        popup.classList.remove('hidden');
    }

    if (btnOpen) {
        btnOpen.addEventListener('click', (e) => {
            e.stopPropagation();
            if (popup.classList.contains('hidden')) {
                openCalendar();
            } else {
                popup.classList.add('hidden');
            }
        });
    }

    monthSelect.addEventListener('change', () => {
        calCurrentMonth = parseInt(monthSelect.value);
        renderCalendarGrid();
    });

    yearSelect.addEventListener('change', () => {
        calCurrentYearBE = parseInt(yearSelect.value);
        renderCalendarGrid();
    });

    btnPrev.addEventListener('click', (e) => {
        e.stopPropagation();
        calCurrentMonth--;
        if (calCurrentMonth < 0) {
            calCurrentMonth = 11;
            calCurrentYearBE--;
        }
        renderCalendarGrid();
    });

    btnNext.addEventListener('click', (e) => {
        e.stopPropagation();
        calCurrentMonth++;
        if (calCurrentMonth > 11) {
            calCurrentMonth = 0;
            calCurrentYearBE++;
        }
        renderCalendarGrid();
    });

    if (btnToday) {
        btnToday.addEventListener('click', (e) => {
            e.stopPropagation();
            const now = new Date();
            const todayIso = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;
            if (inputISO) inputISO.value = todayIso;
            inputTH.value = formatThaiBEDate(todayIso);
            calCurrentMonth = now.getMonth();
            calCurrentYearBE = now.getFullYear() + 543;
            handleStartDateChange(todayIso);
            popup.classList.add('hidden');
        });
    }

    // Close calendar when clicking outside
    document.addEventListener('click', (e) => {
        if (!popup.contains(e.target) && e.target !== btnOpen && e.target !== inputTH) {
            popup.classList.add('hidden');
        }
    });

    // Auto-masking and typing for inputTH (เช่น 29/05/2569)
    inputTH.addEventListener('input', (e) => {
        let val = inputTH.value.replace(/[^\d/]/g, '');
        if (e.inputType !== 'deleteContentBackward') {
            if (val.length === 2 && !val.includes('/')) {
                val = val + '/';
            } else if (val.length === 5 && val.split('/').length === 2) {
                val = val + '/';
            }
        }
        inputTH.value = val;

        if (val.length === 10) {
            const iso = parseThaiBEToISO(val);
            if (iso) {
                if (inputISO) inputISO.value = iso;
                handleStartDateChange(iso);
            }
        }
    });

    inputTH.addEventListener('change', () => {
        const iso = parseThaiBEToISO(inputTH.value);
        if (iso) {
            if (inputISO) inputISO.value = iso;
            inputTH.value = formatThaiBEDate(iso);
            handleStartDateChange(iso);
        } else {
            if (activeClaim && activeClaim.startDate) {
                inputTH.value = formatThaiBEDate(activeClaim.startDate);
            }
        }
    });
}

// -------------------------------------------------------------------------
// PERMANENT DARK MODE ENFORCER
// -------------------------------------------------------------------------
function initPermanentDarkMode() {
    localStorage.removeItem('teachingFeeTheme');
    document.body.classList.remove('light-theme');
}

// -------------------------------------------------------------------------
// DATA IMPORT SYSTEM (EXCEL / PDF / IMAGES)
// -------------------------------------------------------------------------
let importCurrentCategory = 'student'; // 'teacher' | 'subject' | 'student'
let importExtractedItems = []; // Array of parsed candidate objects
let importTargetContext = 'settings'; // 'settings' | 'claim'

function initDataImportSystem() {
    // Configure PDF.js worker if available
    if (typeof pdfjsLib !== 'undefined' && !pdfjsLib.GlobalWorkerOptions.workerSrc) {
        pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
    }

    const dropzone = document.getElementById('import-dropzone');
    const fileInput = document.getElementById('import-file-input');
    const categoryRadios = document.querySelectorAll('input[name="import-category"]');
    const btnConfirmImport = document.getElementById('btn-confirm-import-data');
    const chkSelectAll = document.getElementById('import-select-all');

    if (!dropzone || !fileInput) return;

    // Trigger buttons from Settings tabs
    document.querySelectorAll('.btn-import-trigger').forEach(btn => {
        btn.addEventListener('click', () => {
            const cat = btn.getAttribute('data-category') || 'student';
            importTargetContext = 'settings';
            openDataImportModal(cat);
        });
    });

    // Universal import button in Settings footer
    const btnUniversal = document.getElementById('btn-open-universal-import');
    if (btnUniversal) {
        btnUniversal.addEventListener('click', () => {
            importTargetContext = 'settings';
            openDataImportModal('student');
        });
    }

    // Quick import button from Claim Tab 4 (Students)
    const btnImportClaimStudents = document.getElementById('btn-import-students-claim');
    if (btnImportClaimStudents) {
        btnImportClaimStudents.addEventListener('click', () => {
            importTargetContext = 'claim';
            openDataImportModal('student');
        });
    }

    // Category Radio Changes
    categoryRadios.forEach(radio => {
        radio.addEventListener('change', () => {
            if (radio.checked) {
                setImportCategory(radio.value);
                // If file already loaded, re-parse with new category
                if (window._lastUploadedFile) {
                    processUploadedFile(window._lastUploadedFile);
                }
            }
        });
    });

    // Dropzone Click & Drag Events
    dropzone.addEventListener('click', () => fileInput.click());

    ['dragenter', 'dragover'].forEach(eventName => {
        dropzone.addEventListener(eventName, (e) => {
            e.preventDefault();
            e.stopPropagation();
            dropzone.classList.add('border-purple-400', 'bg-[#141725]');
        });
    });

    ['dragleave', 'drop'].forEach(eventName => {
        dropzone.addEventListener(eventName, (e) => {
            e.preventDefault();
            e.stopPropagation();
            dropzone.classList.remove('border-purple-400', 'bg-[#141725]');
        });
    });

    dropzone.addEventListener('drop', (e) => {
        const dt = e.dataTransfer;
        const files = dt.files;
        if (files && files.length > 0) {
            handleFileSelection(files[0]);
        }
    });

    fileInput.addEventListener('change', (e) => {
        if (fileInput.files && fileInput.files.length > 0) {
            handleFileSelection(fileInput.files[0]);
        }
    });

    // Select All Checkbox
    if (chkSelectAll) {
        chkSelectAll.addEventListener('change', () => {
            const checked = chkSelectAll.checked;
            document.querySelectorAll('.chk-import-row').forEach(cb => {
                cb.checked = checked;
            });
            updateImportSelectionCount();
        });
    }

    // Confirm Import Action
    if (btnConfirmImport) {
        btnConfirmImport.addEventListener('click', handleExecuteImport);
    }
}

function openDataImportModal(category = 'student') {
    setImportCategory(category);
    resetImportModalState();
    openModal('modal-import-data');
}

function setImportCategory(category) {
    importCurrentCategory = category;

    // Sync radio inputs & card styles
    document.querySelectorAll('input[name="import-category"]').forEach(r => {
        r.checked = (r.value === category);
        const card = r.closest('.import-type-card');
        if (card) {
            if (r.checked) {
                card.classList.add('border-purple-500', 'bg-purple-950/30');
                card.classList.remove('border-[#2d3748]', 'bg-[#0f121d]');
            } else {
                card.classList.remove('border-purple-500', 'bg-purple-950/30');
                card.classList.add('border-[#2d3748]', 'bg-[#0f121d]');
            }
        }
    });

    // Update Preview Table Column Headers
    const th1 = document.getElementById('th-col-1');
    const th2 = document.getElementById('th-col-2');
    const th3 = document.getElementById('th-col-3');

    if (category === 'teacher') {
        if (th1) th1.textContent = 'คำนำหน้า / รหัส';
        if (th2) th2.textContent = 'ชื่อ - นามสกุลอาจารย์';
        if (th3) th3.textContent = 'ตำแหน่ง / หมายเหตุ';
    } else if (category === 'subject') {
        if (th1) th1.textContent = 'รหัสวิชา';
        if (th2) th2.textContent = 'ชื่อรายวิชา';
        if (th3) th3.textContent = 'หน่วยกิต (ท-ป-ศ)';
    } else {
        // student
        if (th1) th1.textContent = 'รหัสนักศึกษา';
        if (th2) th2.textContent = 'ชื่อ - นามสกุล';
        if (th3) th3.textContent = 'ระดับชั้น / หมายเหตุ';
    }
}

function resetImportModalState() {
    window._lastUploadedFile = null;
    importExtractedItems = [];

    const fileInput = document.getElementById('import-file-input');
    if (fileInput) fileInput.value = '';

    const fileInfo = document.getElementById('import-file-info');
    if (fileInfo) fileInfo.classList.add('hidden');

    const statusBar = document.getElementById('import-status-bar');
    if (statusBar) statusBar.classList.add('hidden');

    const previewSection = document.getElementById('import-preview-section');
    if (previewSection) previewSection.classList.add('hidden');

    const btnConfirm = document.getElementById('btn-confirm-import-data');
    if (btnConfirm) {
        btnConfirm.disabled = true;
        document.getElementById('label-confirm-import').textContent = 'ยืนยันนำเข้าข้อมูล (0 รายการ)';
    }
}

function handleFileSelection(file) {
    if (!file) return;
    window._lastUploadedFile = file;

    // Display File Info
    const fileInfo = document.getElementById('import-file-info');
    const fileName = document.getElementById('import-file-name');
    const fileSize = document.getElementById('import-file-size');

    if (fileInfo && fileName && fileSize) {
        fileName.textContent = file.name;
        const sizeKb = (file.size / 1024).toFixed(1);
        fileSize.textContent = `(${sizeKb > 1024 ? (sizeKb / 1024).toFixed(2) + ' MB' : sizeKb + ' KB'})`;
        fileInfo.classList.remove('hidden');
    }

    processUploadedFile(file);
}

function setImportStatus(message, isSpinning = true) {
    const statusBar = document.getElementById('import-status-bar');
    const statusText = document.getElementById('import-status-text');
    if (statusBar && statusText) {
        statusBar.classList.remove('hidden');
        statusText.textContent = message;
        const icon = statusBar.querySelector('i');
        if (icon) {
            icon.className = isSpinning ? 'fa-solid fa-circle-notch fa-spin text-blue-400' : 'fa-solid fa-circle-check text-green-400';
        }
    }
}

async function processUploadedFile(file) {
    const ext = file.name.split('.').pop().toLowerCase();
    setImportStatus(`กำลังอ่านข้อมูลจากไฟล์ ${file.name}...`, true);

    try {
        if (['xlsx', 'xls', 'csv'].includes(ext)) {
            await parseExcelOrCsvFile(file);
        } else if (ext === 'pdf') {
            await parsePdfFile(file);
        } else if (['png', 'jpg', 'jpeg', 'webp', 'bmp'].includes(ext)) {
            await parseImageFileWithOcr(file);
        } else {
            alert('รองรับเฉพาะไฟล์ Excel (.xlsx, .xls, .csv), เอกสาร PDF (.pdf) และรูปภาพ (.png, .jpg)');
            setImportStatus('ประเภทไฟล์ไม่ถูกต้อง', false);
        }
    } catch (err) {
        console.error('File parsing error:', err);
        setImportStatus(`เกิดข้อผิดพลาดในการอ่านไฟล์: ${err.message}`, false);
        alert(`เกิดข้อผิดพลาดในการประมวลผลไฟล์: ${err.message}`);
    }
}

// 1. EXCEL / CSV PARSER (SheetJS)
function parseExcelOrCsvFile(file) {
    return new Promise((resolve, reject) => {
        if (typeof XLSX === 'undefined') {
            reject(new Error('SheetJS library ไม่พร้อมใช้งาน'));
            return;
        }

        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const data = new Uint8Array(e.target.result);
                const workbook = XLSX.read(data, { type: 'array' });
                
                // Aggregate 2D row arrays from all sheets
                let allRows = [];
                workbook.SheetNames.forEach(sheetName => {
                    const sheet = workbook.Sheets[sheetName];
                    const rows = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: '' });
                    allRows = allRows.concat(rows);
                });

                importExtractedItems = extractItemsFromRows(allRows, importCurrentCategory);
                renderImportPreview();
                setImportStatus(`ดึงข้อมูลสำเร็จ พบ ${importExtractedItems.length} รายการ`, false);
                resolve();
            } catch (err) {
                reject(err);
            }
        };
        reader.onerror = reject;
        reader.readAsArrayBuffer(file);
    });
}

// 2. PDF PARSER (PDF.js)
async function parsePdfFile(file) {
    if (typeof pdfjsLib === 'undefined') {
        throw new Error('PDF.js library ไม่พร้อมใช้งาน');
    }

    const arrayBuffer = await file.arrayBuffer();
    const loadingTask = pdfjsLib.getDocument({ data: arrayBuffer });
    const pdfDoc = await loadingTask.promise;

    let textLines = [];

    for (let pageNum = 1; pageNum <= pdfDoc.numPages; pageNum++) {
        setImportStatus(`กำลังอ่านเอกสาร PDF หน้า ${pageNum}/${pdfDoc.numPages}...`, true);
        const page = await pdfDoc.getPage(pageNum);
        const textContent = await page.getTextContent();
        
        // Group items by line based on vertical Y coordinate
        const linesMap = {};
        textContent.items.forEach(item => {
            const y = Math.round(item.transform[5]); // Y position
            if (!linesMap[y]) linesMap[y] = [];
            linesMap[y].push({ x: item.transform[4], text: item.str });
        });

        // Sort lines top to bottom (Y descending in PDF space)
        const sortedY = Object.keys(linesMap).map(Number).sort((a, b) => b - a);
        sortedY.forEach(y => {
            const lineItems = linesMap[y].sort((a, b) => a.x - b.x);
            const lineStr = lineItems.map(i => i.text.trim()).filter(Boolean).join(' ');
            if (lineStr) textLines.push(lineStr);
        });
    }

    importExtractedItems = extractItemsFromLines(textLines, importCurrentCategory);
    renderImportPreview();
    setImportStatus(`ดึงข้อมูลจาก PDF สำเร็จ พบ ${importExtractedItems.length} รายการ`, false);
}

// 3. IMAGE PARSER (Tesseract.js OCR)
async function parseImageFileWithOcr(file) {
    if (typeof Tesseract === 'undefined') {
        throw new Error('Tesseract OCR library ไม่พร้อมใช้งาน');
    }

    setImportStatus('กำลังสแกนรูปภาพด้วยระบบ OCR (ภาษาไทย/อังกฤษ)...', true);

    const result = await Tesseract.recognize(file, 'tha+eng', {
        logger: m => {
            if (m.status === 'recognizing text') {
                const pct = Math.round((m.progress || 0) * 100);
                setImportStatus(`กำลังวิเคราะห์ข้อความในภาพ (${pct}%)...`, true);
            }
        }
    });

    const text = result.data.text || '';
    const textLines = text.split('\n').map(l => l.trim()).filter(Boolean);

    importExtractedItems = extractItemsFromLines(textLines, importCurrentCategory);
    renderImportPreview();
    setImportStatus(`ดึงข้อมูลจากรูปภาพสำเร็จ พบ ${importExtractedItems.length} รายการ`, false);
}

// -------------------------------------------------------------------------
// INTELLIGENT PATTERN EXTRACTORS
// -------------------------------------------------------------------------

// Thai Title Prefixes
const THAI_NAME_PREFIXES = ['นาย', 'นางสาว', 'นาง', 'น.ส.', 'ว่าที่ ร.ต.', 'ว่าที่ร้อยตรี', 'ด.ช.', 'ด.ญ.', 'อ.', 'อาจารย์', 'ดร.', 'ผศ.', 'รศ.', 'ศ.'];

function splitThaiName(raw) {
    let clean = (raw || '').trim();
    if (!clean) return { prefix: '', name: '', surname: '', fullName: '' };

    let detectedPrefix = '';
    for (const p of THAI_NAME_PREFIXES) {
        if (clean.startsWith(p)) {
            detectedPrefix = p;
            clean = clean.substring(p.length).trim();
            break;
        }
    }

    const tokens = clean.split(/\s+/).filter(Boolean);
    if (tokens.length >= 2) {
        const name = (detectedPrefix ? detectedPrefix : '') + tokens[0];
        const surname = tokens.slice(1).join(' ');
        return { prefix: detectedPrefix, name, surname, fullName: `${name} ${surname}`.trim() };
    } else if (tokens.length === 1) {
        const name = (detectedPrefix ? detectedPrefix : '') + tokens[0];
        return { prefix: detectedPrefix, name, surname: '', fullName: name };
    }
    return { prefix: '', name: clean, surname: '', fullName: clean };
}

// Extract items from 2D Excel row arrays
function extractItemsFromRows(rows, category) {
    const results = [];
    const seenKeys = new Set();

    rows.forEach(row => {
        if (!Array.isArray(row) || row.length === 0) return;
        const rowStrings = row.map(cell => String(cell || '').trim()).filter(Boolean);
        if (rowStrings.length === 0) return;
        const rowJoined = rowStrings.join(' ');

        if (category === 'student') {
            // Find 10-13 digit student ID (starts with 6x usually e.g. 68401211001)
            let studentId = '';
            let namePart = '';

            for (let i = 0; i < row.length; i++) {
                const cellStr = String(row[i] || '').trim();
                const mId = cellStr.match(/\b(6\d{9,12}|\d{10,12})\b/);
                if (mId && !studentId) {
                    studentId = mId[1];
                } else if (cellStr && !cellStr.match(/^\d+$/) && cellStr.length >= 4) {
                    // Potential name cell
                    if (!namePart && !['ชื่อ', 'นามสกุล', 'รหัส', 'ลำดับ', 'สถานะ'].some(h => cellStr.includes(h))) {
                        namePart = cellStr;
                        // Check if next column has surname
                        if (i + 1 < row.length) {
                            const nextCell = String(row[i + 1] || '').trim();
                            if (nextCell && !nextCell.match(/^\d+$/) && nextCell.length >= 2) {
                                namePart += ' ' + nextCell;
                            }
                        }
                    }
                }
            }

            if (studentId || (namePart && THAI_NAME_PREFIXES.some(p => namePart.includes(p)))) {
                const parsed = splitThaiName(namePart);
                const uniqueKey = studentId || parsed.fullName;
                if (uniqueKey && !seenKeys.has(uniqueKey)) {
                    seenKeys.add(uniqueKey);
                    results.push({
                        col1: studentId || '-',
                        col2: parsed.fullName || '-',
                        col3: 'นักศึกษา ป.ตรี',
                        rawStudentId: studentId,
                        rawName: parsed.name,
                        rawSurname: parsed.surname,
                        rawFullName: parsed.fullName
                    });
                }
            }

        } else if (category === 'teacher') {
            // Search for teacher name
            for (let i = 0; i < row.length; i++) {
                const cellStr = String(row[i] || '').trim();
                if (cellStr.length >= 5 && THAI_NAME_PREFIXES.some(p => cellStr.startsWith(p) || cellStr.includes(' ' + p))) {
                    const parsed = splitThaiName(cellStr);
                    if (parsed.fullName && !seenKeys.has(parsed.fullName)) {
                        seenKeys.add(parsed.fullName);
                        results.push({
                            col1: parsed.prefix || 'อ.',
                            col2: parsed.fullName,
                            col3: 'อาจารย์/ผู้สอน',
                            rawName: parsed.fullName
                        });
                    }
                }
            }

        } else if (category === 'subject') {
            // Search for subject code e.g. 27-40121-2201 or 01-401-201
            let code = '';
            let name = '';
            let credits = 3;
            let hours = 3;

            for (let i = 0; i < row.length; i++) {
                const cellStr = String(row[i] || '').trim();
                const mCode = cellStr.match(/(\d{2}-\d{4,5}-\d{4}|\b\d{4}-\d{4}\b|\b\d{7,9}\b)/);
                if (mCode && !code) {
                    code = mCode[1];
                } else if (!name && cellStr.length > 3 && !cellStr.match(/^\d+$/) && !['รหัส', 'วิชา', 'หน่วยกิต', 'ทฤษฎี', 'ปฏิบัติ'].some(h => cellStr === h)) {
                    name = cellStr;
                }
            }

            // Detect credits & hours in row
            const mCredits = rowJoined.match(/(\d)\s*\((\d+)-(\d+)-(\d+)\)/) || rowJoined.match(/(\d)\s*หน่วยกิต/);
            if (mCredits) {
                credits = parseInt(mCredits[1]) || 3;
                if (mCredits[2] && mCredits[3]) {
                    hours = (parseInt(mCredits[2]) || 0) + (parseInt(mCredits[3]) || 0);
                }
            }

            if (code && name) {
                if (!seenKeys.has(code)) {
                    seenKeys.add(code);
                    results.push({
                        col1: code,
                        col2: name,
                        col3: `${credits} นก. (${hours} ชม.)`,
                        rawCode: code,
                        rawName: name,
                        rawCredits: credits,
                        rawHours: hours
                    });
                }
            }
        }
    });

    return results;
}

// Extract items from raw text lines (from PDF, OCR image, or clipboard)
function extractItemsFromLines(lines, category) {
    const results = [];
    const seenKeys = new Set();

    lines.forEach(line => {
        const clean = (line || '').trim();
        if (!clean || clean.length < 3) return;

        if (category === 'student') {
            // Match student ID: 10-13 digits
            const mId = clean.match(/\b(6\d{9,12}|\d{10,12})\b/);
            // Match name with prefix or Thai words
            const mName = clean.match(/(?:นาย|นางสาว|นาง|น\.ส\.|ว่าที่\s*ร\.ต\.|ด\.ช\.|ด\.ญ\.)\s*([ก-๙]+)\s+([ก-๙]+)/);

            if (mId || mName) {
                const studentId = mId ? mId[1] : '';
                let fullName = '';
                let name = '';
                let surname = '';

                if (mName) {
                    fullName = mName[0].trim();
                    const parsed = splitThaiName(fullName);
                    name = parsed.name;
                    surname = parsed.surname;
                } else {
                    // Remove student ID from line and look for Thai text
                    const rem = clean.replace(studentId, '').replace(/^[0-9.\s-]+/, '').trim();
                    const parsed = splitThaiName(rem);
                    name = parsed.name;
                    surname = parsed.surname;
                    fullName = parsed.fullName;
                }

                const uniqueKey = studentId || fullName;
                if (uniqueKey && !seenKeys.has(uniqueKey)) {
                    seenKeys.add(uniqueKey);
                    results.push({
                        col1: studentId || '-',
                        col2: fullName || '-',
                        col3: 'นักศึกษา ป.ตรี',
                        rawStudentId: studentId,
                        rawName: name,
                        rawSurname: surname,
                        rawFullName: fullName
                    });
                }
            }

        } else if (category === 'teacher') {
            // Find lines with Thai title prefixes
            const mTeacher = clean.match(/(?:นาย|นางสาว|นาง|น\.ส\.|ว่าที่\s*ร\.ต\.|ผศ\.|รศ\.|ศ\.|ดร\.|อ\.|อาจารย์)\s*([ก-๙]+)\s+([ก-๙]+)/);
            if (mTeacher) {
                const fullName = mTeacher[0].trim();
                const parsed = splitThaiName(fullName);
                if (parsed.fullName && !seenKeys.has(parsed.fullName)) {
                    seenKeys.add(parsed.fullName);
                    results.push({
                        col1: parsed.prefix || 'อ.',
                        col2: parsed.fullName,
                        col3: 'อาจารย์/ผู้สอน',
                        rawName: parsed.fullName
                    });
                }
            }

        } else if (category === 'subject') {
            // Find subject code pattern e.g. 27-40121-2201
            const mCode = clean.match(/(\d{2}-\d{4,5}-\d{4}|\b\d{4}-\d{4}\b|\b\d{7,9}\b)/);
            if (mCode) {
                const code = mCode[1];
                let rem = clean.replace(code, '').replace(/^[0-9.\s-]+/, '').trim();
                
                // Check credits pattern e.g. 3(2-2-5) or 3-2-4
                let credits = 3;
                let hours = 3;
                const mCred = rem.match(/(\d)\s*\(([0-9]+)-([0-9]+)-[0-9]+\)/) || rem.match(/(\d)\s*หน่วยกิต/);
                if (mCred) {
                    credits = parseInt(mCred[1]) || 3;
                    if (mCred[2] && mCred[3]) {
                        hours = (parseInt(mCred[2]) || 0) + (parseInt(mCred[3]) || 0);
                    }
                    rem = rem.replace(mCred[0], '').trim();
                }

                // Strip leading/trailing brackets
                const name = rem.replace(/^[\[\(]/, '').replace(/[\]\)]$/, '').trim();

                if (code && name && !seenKeys.has(code)) {
                    seenKeys.add(code);
                    results.push({
                        col1: code,
                        col2: name,
                        col3: `${credits} นก. (${hours} ชม.)`,
                        rawCode: code,
                        rawName: name,
                        rawCredits: credits,
                        rawHours: hours
                    });
                }
            }
        }
    });

    return results;
}

// -------------------------------------------------------------------------
// PREVIEW TABLE & SELECTION LOGIC
// -------------------------------------------------------------------------
function renderImportPreview() {
    const section = document.getElementById('import-preview-section');
    const tbody = document.getElementById('import-preview-tbody');
    const badge = document.getElementById('import-detected-badge');
    const btnConfirm = document.getElementById('btn-confirm-import-data');
    const chkSelectAll = document.getElementById('import-select-all');

    if (!section || !tbody) return;

    section.classList.remove('hidden');
    tbody.innerHTML = '';

    if (chkSelectAll) chkSelectAll.checked = true;

    if (importExtractedItems.length === 0) {
        tbody.innerHTML = `
            <tr>
                <td colspan="5" class="p-6 text-center text-xs text-gray-400">
                    <i class="fa-solid fa-triangle-exclamation text-amber-400 text-lg mb-2 block"></i>
                    ไม่พบข้อมูลที่ตรงกับประเภท "<strong>${getCategoryLabel(importCurrentCategory)}</strong>" ในไฟล์นี้<br>
                    <span class="text-[11px] text-gray-500">ลองเปลี่ยนประเภทข้อมูลด้านบน หรือตรวจสอบรูปแบบไฟล์</span>
                </td>
            </tr>
        `;
        if (badge) badge.textContent = 'พบ 0 รายการ';
        if (btnConfirm) {
            btnConfirm.disabled = true;
            document.getElementById('label-confirm-import').textContent = 'ยืนยันนำเข้าข้อมูล (0 รายการ)';
        }
        return;
    }

    importExtractedItems.forEach((item, idx) => {
        const tr = document.createElement('tr');
        tr.className = 'hover:bg-[#1c2134] transition border-b border-[#2d3748]/60 last:border-0';
        tr.innerHTML = `
            <td class="p-2 text-center">
                <input type="checkbox" class="chk-import-row accent-purple-600 rounded" data-index="${idx}" checked>
            </td>
            <td class="p-2 text-center text-gray-500 font-mono">${idx + 1}</td>
            <td class="p-2 font-mono text-purple-300 font-medium">${item.col1}</td>
            <td class="p-2 text-white font-medium">${item.col2}</td>
            <td class="p-2 text-center text-gray-400">${item.col3}</td>
        `;
        tbody.appendChild(tr);
    });

    // Row Checkbox Listeners
    tbody.querySelectorAll('.chk-import-row').forEach(cb => {
        cb.addEventListener('change', updateImportSelectionCount);
    });

    updateImportSelectionCount();
}

function updateImportSelectionCount() {
    const checkedRows = document.querySelectorAll('.chk-import-row:checked');
    const totalCount = importExtractedItems.length;
    const checkedCount = checkedRows.length;

    const badge = document.getElementById('import-detected-badge');
    const btnConfirm = document.getElementById('btn-confirm-import-data');
    const labelConfirm = document.getElementById('label-confirm-import');
    const chkSelectAll = document.getElementById('import-select-all');

    if (badge) badge.textContent = `พบ ${totalCount} รายการ (เลือก ${checkedCount})`;
    if (labelConfirm) labelConfirm.textContent = `ยืนยันนำเข้าข้อมูล (${checkedCount} รายการ)`;
    if (btnConfirm) btnConfirm.disabled = (checkedCount === 0);

    if (chkSelectAll) {
        chkSelectAll.checked = (checkedCount === totalCount && totalCount > 0);
    }
}

function getCategoryLabel(cat) {
    if (cat === 'teacher') return 'อาจารย์ผู้สอน';
    if (cat === 'subject') return 'รายวิชา';
    return 'นักศึกษา';
}

// -------------------------------------------------------------------------
// IMPORT EXECUTION (APPEND OR REPLACE)
// -------------------------------------------------------------------------
function handleExecuteImport() {
    const checkedBoxes = document.querySelectorAll('.chk-import-row:checked');
    if (checkedBoxes.length === 0) return;

    const selectedIndices = Array.from(checkedBoxes).map(cb => parseInt(cb.getAttribute('data-index')));
    const selectedItems = selectedIndices.map(i => importExtractedItems[i]);

    const importMode = document.querySelector('input[name="import-mode"]:checked')?.value || 'append';

    let addedCount = 0;

    if (importCurrentCategory === 'student') {
        if (importMode === 'replace') {
            appData.students = [];
        }

        const existingIds = new Set((appData.students || []).map(s => s.studentId ? s.studentId.trim() : ''));
        const existingNames = new Set((appData.students || []).map(s => s.name ? s.name.trim() : ''));

        selectedItems.forEach(item => {
            const sid = item.rawStudentId || '';
            const fullName = item.rawFullName || `${item.rawName || ''} ${item.rawSurname || ''}`.trim();

            const isDuplicate = (sid && existingIds.has(sid)) || (!sid && existingNames.has(fullName));
            if (!isDuplicate || importMode === 'replace') {
                appData.students.push({
                    id: generateId(),
                    studentId: sid,
                    name: fullName
                });
                if (sid) existingIds.add(sid);
                if (fullName) existingNames.add(fullName);
                addedCount++;
            }
        });

        // If invoked from Claim Tab 4 (Students editor), sync to activeClaim.students as well
        if (activeClaim && (importTargetContext === 'claim' || currentView === 'claim-form')) {
            if (importMode === 'replace') {
                activeClaim.students = [];
            }
            if (!activeClaim.students) activeClaim.students = [];

            const claimExistingIds = new Set(activeClaim.students.map(s => s.studentId ? s.studentId.trim() : ''));
            selectedItems.forEach(item => {
                const sid = item.rawStudentId || '';
                const name = item.rawName || '';
                const surname = item.rawSurname || '';
                if (!sid || !claimExistingIds.has(sid) || importMode === 'replace') {
                    activeClaim.students.push({
                        studentId: sid,
                        name: name,
                        surname: surname
                    });
                    if (sid) claimExistingIds.add(sid);
                }
            });

            // Update Claim UI
            const inpStCount = document.getElementById('claim-input-students');
            if (inpStCount) inpStCount.value = activeClaim.students.length;
            renderStudentsEditor();
            renderA4Page1();
            renderA4Page2();
        }

    } else if (importCurrentCategory === 'teacher') {
        if (importMode === 'replace') {
            appData.teachers = [];
        }

        const existingTeacherNames = new Set((appData.teachers || []).map(t => t.name.trim()));

        selectedItems.forEach(item => {
            const tName = item.rawName || item.col2;
            if (tName && (!existingTeacherNames.has(tName) || importMode === 'replace')) {
                appData.teachers.push({
                    id: generateId(),
                    name: tName
                });
                existingTeacherNames.add(tName);
                addedCount++;
            }
        });

    } else if (importCurrentCategory === 'subject') {
        if (importMode === 'replace') {
            appData.subjects_master = [];
        }

        const existingCodes = new Set((appData.subjects_master || []).map(s => s.code.trim()));

        selectedItems.forEach(item => {
            const code = item.rawCode || item.col1;
            const name = item.rawName || item.col2;
            const credits = item.rawCredits || 3;
            const hours = item.rawHours || 3;

            if (code && (!existingCodes.has(code) || importMode === 'replace')) {
                appData.subjects_master.push({
                    id: generateId(),
                    code: code,
                    name: name,
                    credits: credits,
                    hours: hours
                });
                existingCodes.add(code);
                addedCount++;
            }
        });
    }

    // Save and Refresh UI
    saveData();
    renderSettingsLists();
    updateGlobalStats();
    updateTabCounts();

    closeModal('modal-import-data');

    alert(`✓ นำเข้าข้อมูล ${getCategoryLabel(importCurrentCategory)} เรียบร้อยแล้ว จำนวน ${addedCount} รายการ`);
}

// -------------------------------------------------------------------------
// GRAND SUMMARY CLAIM (ใบเบิกรวม ตราครุฑ - แบบบันทึกข้อความ)
// -------------------------------------------------------------------------
let currentSummaryTermId = null;
let summaryClaimSelectedSubIds = new Set();

function initSummaryClaimSystem() {
    const btnOpenInTerm = document.getElementById('btn-open-summary-claim');
    if (btnOpenInTerm) {
        btnOpenInTerm.addEventListener('click', () => {
            if (currentTermId) openSummaryClaimModal(currentTermId);
        });
    }

    const btnPrint = document.getElementById('btn-print-summary-claim');
    if (btnPrint) {
        btnPrint.addEventListener('click', printSummaryClaim);
    }

    const btnSelectAll = document.getElementById('btn-summary-select-all');
    if (btnSelectAll) {
        btnSelectAll.addEventListener('click', () => {
            const term = appData.terms.find(t => t.id === currentSummaryTermId);
            if (!term) return;
            term.subjects.forEach(s => summaryClaimSelectedSubIds.add(s.id));
            saveSummaryClaimState();
            renderSummaryClaimSubjectSelector();
            renderSummaryClaimA4();
        });
    }

    const btnDeselectAll = document.getElementById('btn-summary-deselect-all');
    if (btnDeselectAll) {
        btnDeselectAll.addEventListener('click', () => {
            summaryClaimSelectedSubIds.clear();
            saveSummaryClaimState();
            renderSummaryClaimSubjectSelector();
            renderSummaryClaimA4();
        });
    }

    // Input listeners for memo fields
    const memoInputIds = [
        'summary-input-dept',
        'summary-input-doc-no',
        'summary-input-doc-date',
        'summary-input-subject-title',
        'summary-input-recipient',
        'summary-input-requester',
        'summary-input-role',
        'summary-input-dept-name',
        'summary-input-level',
        'summary-input-term-year',
        'summary-input-start-date',
        'summary-input-end-date',
        'summary-input-percent',
        'summary-sig-requester',
        'summary-sig-dept-head',
        'summary-sig-verifier',
        'summary-sig-verifier-role',
        'summary-sig-academic-deputy',
        'summary-sig-resource-deputy',
        'summary-sig-director'
    ];

    memoInputIds.forEach(id => {
        const el = document.getElementById(id);
        if (el) {
            el.addEventListener('input', () => {
                if (id === 'summary-input-requester') {
                    const sigReq = document.getElementById('summary-sig-requester');
                    if (sigReq) sigReq.value = el.value;
                }
                saveSummaryClaimState();
                renderSummaryClaimA4();
            });
        }
    });

    // Attach Autocomplete for personnel in Summary Claim
    const summaryPersonIds = [
        'summary-input-requester',
        'summary-sig-requester',
        'summary-sig-dept-head',
        'summary-sig-verifier',
        'summary-sig-academic-deputy',
        'summary-sig-resource-deputy',
        'summary-sig-director'
    ];
    summaryPersonIds.forEach(id => {
        const el = document.getElementById(id);
        if (el) {
            attachTeacherAutocomplete(el, (name) => {
                if (id === 'summary-input-requester') {
                    const sigReq = document.getElementById('summary-sig-requester');
                    if (sigReq) sigReq.value = name;
                }
                saveSummaryClaimState();
                renderSummaryClaimA4();
            });
        }
    });
}

function getSubjectClaimSummary(sub) {
    const masterSub = (appData.subjects_master || []).find(s => s.id === sub.subjectId) || { code: sub.code || '', name: sub.name || '' };
    const teacher = (appData.teachers || []).find(t => t.id === sub.teacherId) || {};
    
    let subjectCode = masterSub.code || sub.code || '';
    let subjectName = masterSub.name || sub.name || '';
    let teacherName = teacher.name || '';
    let credits = sub.credits || masterSub.credits || 3;
    let students = sub.studentCount || 6;
    const term = appData.terms.find(t => t.id === currentTermId);
    let rate = sub.rate || (term && term.hourlyRate) || 42;
    let hours = sub.hours || 45;

    if (sub.claimData) {
        if (sub.claimData.subjectCode) subjectCode = sub.claimData.subjectCode;
        if (sub.claimData.subjectName) subjectName = sub.claimData.subjectName;
        if (sub.claimData.teacherName) teacherName = sub.claimData.teacherName;
        if (sub.claimData.credits) credits = parseInt(sub.claimData.credits) || credits;
        if (sub.claimData.rate) rate = parseFloat(sub.claimData.rate) || rate;
        if (sub.claimData.students && sub.claimData.students.length > 0) {
            students = sub.claimData.students.length;
        }
        if (sub.claimData.weeks && Array.isArray(sub.claimData.weeks)) {
            let sumHrs = 0;
            sub.claimData.weeks.forEach(w => {
                if (!w.isHoliday) sumHrs += (parseInt(w.totalHrs) || 0);
            });
            if (sumHrs > 0) hours = sumHrs;
        }
    }

    const totalMoney = hours * rate;

    return {
        id: sub.id,
        code: subjectCode,
        name: subjectName,
        teacherName: teacherName || 'นายณัฐวรรธน์ เกษกุล',
        credits: credits,
        students: students,
        hours: hours,
        rate: rate,
        totalMoney: totalMoney,
        claimData: sub.claimData
    };
}

function openSummaryClaimModal(termId) {
    const term = appData.terms.find(t => t.id === termId);
    if (!term) return;

    currentSummaryTermId = termId;

    // Load or initialize summary claim data in term
    if (!term.summaryClaimData) {
        term.summaryClaimData = {};
    }
    const state = term.summaryClaimData;

    // Badge
    const termBadge = document.getElementById('summary-term-badge');
    if (termBadge) termBadge.textContent = `ภาคเรียนที่ ${term.no}/${term.year}`;

    // Select all subjects by default if not set
    if (!state.selectedSubjectIds || !Array.isArray(state.selectedSubjectIds) || state.selectedSubjectIds.length === 0) {
        summaryClaimSelectedSubIds = new Set(term.subjects.map(s => s.id));
    } else {
        summaryClaimSelectedSubIds = new Set(state.selectedSubjectIds);
    }

    // Calculate live effective dates from subjects
    const effectiveDates = getTermEffectiveDateRange(term, summaryClaimSelectedSubIds.size > 0 ? Array.from(summaryClaimSelectedSubIds) : null);
    let defaultStartDate = effectiveDates.startDateStr;
    let defaultEndDate = effectiveDates.endDateStr;
    let defaultDept = 'เทคโนโลยีโยธา';
    let defaultRequester = 'นายณัฐวรรธน์ เกษกุล';
    let defaultLevel = '1';

    if (term.subjects.length > 0) {
        const firstSub = term.subjects[0];
        const claim = (typeof ensureSubjectClaimData === 'function')
            ? ensureSubjectClaimData(term, firstSub)
            : (firstSub.claimData || {});
        if (claim) {
            if (claim.department) defaultDept = claim.department;
            if (claim.teacherName) defaultRequester = claim.teacherName;
            if (claim.level) defaultLevel = claim.level.replace(/[^0-9]/g, '') || '1';
        }
    }

    // Check if saved state has stale placeholder dates or empty
    const isStaleStartDate = !state.startDateStr || 
        state.startDateStr.includes('2 มิถุนายน') || 
        state.startDateStr.includes('มิถุนายน 2568');
    const isStaleEndDate = !state.endDateStr || 
        state.endDateStr.includes('29 กันยายน') || 
        state.endDateStr.includes('4 ตุลาคม 2568');

    const effectiveStartVal = isStaleStartDate ? defaultStartDate : (state.startDateStr || defaultStartDate);
    const effectiveEndVal = isStaleEndDate ? defaultEndDate : (state.endDateStr || defaultEndDate);
    const effectiveTermYear = (state.termYearStr && state.termYearStr.includes(String(term.no))) 
        ? state.termYearStr 
        : `${term.no}  /   ${term.year}`;

    state.startDateStr = effectiveStartVal;
    state.endDateStr = effectiveEndVal;
    state.termYearStr = effectiveTermYear;

    // Populate Memo Input Fields
    const setVal = (id, val, fallback) => {
        const el = document.getElementById(id);
        if (el) el.value = (val !== undefined && val !== null && String(val).trim() !== '') ? val : fallback;
    };

    setVal('summary-input-dept', state.deptHeader, 'สาขาวิชาโยธา  วิทยาลัยเทคนิคอุบลราชธานี');
    setVal('summary-input-doc-no', state.docNo, '');
    setVal('summary-input-doc-date', state.docDate, '');
    setVal('summary-input-subject-title', state.docSubject, 'ขอเบิกค่าสอนระดับปริญญาตรี');
    setVal('summary-input-recipient', state.recipient, 'ผู้อำนวยการวิทยาลัยเทคนิคอุบลราชธานี');
    setVal('summary-input-requester', state.requesterName, defaultRequester);
    setVal('summary-input-role', state.requesterRole, 'อาจารย์');
    setVal('summary-input-dept-name', state.department, defaultDept);
    setVal('summary-input-level', state.classLevel, defaultLevel);
    setVal('summary-input-term-year', state.termYearStr, `${term.no}  /   ${term.year}`);
    setVal('summary-input-percent', state.percent, 60);
    setVal('summary-input-start-date', state.startDateStr, defaultStartDate);
    setVal('summary-input-end-date', state.endDateStr, defaultEndDate);

    // Signatures (ดึงค่าเริ่มต้นจากเทอมแรกอัตโนมัติ)
    const sig = state.signatures || {};
    const defSig = getDefaultSignatures2To9();
    setVal('summary-sig-requester', sig.requester, defaultRequester);
    setVal('summary-sig-dept-head', sig.deptHead, defSig.deptHead || 'นายปริวัฒน์ ยืนยิ่ง');
    setVal('summary-sig-verifier', sig.verifier, defSig.curriculumHead || 'นายชนะ   สุทธิประภา');
    setVal('summary-sig-verifier-role', sig.verifierRole, defSig.curriculumHeadRole || 'หัวหน้างานพัฒนาหลักสูตรสายเทคโนโลยีหรือสายปฏิบัติการ');
    setVal('summary-sig-academic-deputy', sig.academicDeputy, defSig.academicDeputy || 'นายสุวิชา  มั่นยืน');
    setVal('summary-sig-resource-deputy', sig.resourceDeputy, defSig.resourceDeputy || 'นางสาวสายฝน  สาระผล');
    setVal('summary-sig-director', sig.director, defSig.director || 'นายธาตรี  พิบูลมณฑา');

    renderSummaryClaimSubjectSelector();
    renderSummaryClaimA4();
    openModal('modal-summary-claim');
}

function saveSummaryClaimState() {
    const term = appData.terms.find(t => t.id === currentSummaryTermId);
    if (!term) return;

    if (!term.summaryClaimData) term.summaryClaimData = {};
    const state = term.summaryClaimData;

    const getVal = (id) => (document.getElementById(id)?.value || '').trim();

    state.selectedSubjectIds = Array.from(summaryClaimSelectedSubIds);
    state.deptHeader = getVal('summary-input-dept');
    state.docNo = getVal('summary-input-doc-no');
    state.docDate = getVal('summary-input-doc-date');
    state.docSubject = getVal('summary-input-subject-title');
    state.recipient = getVal('summary-input-recipient');
    state.requesterName = getVal('summary-input-requester');
    state.requesterRole = getVal('summary-input-role');
    state.department = getVal('summary-input-dept-name');
    state.classLevel = getVal('summary-input-level');
    state.termYearStr = getVal('summary-input-term-year');
    state.percent = getVal('summary-input-percent');
    state.startDateStr = getVal('summary-input-start-date');
    state.endDateStr = getVal('summary-input-end-date');

    state.signatures = {
        requester: getVal('summary-sig-requester'),
        deptHead: getVal('summary-sig-dept-head'),
        verifier: getVal('summary-sig-verifier'),
        verifierRole: getVal('summary-sig-verifier-role'),
        academicDeputy: getVal('summary-sig-academic-deputy'),
        resourceDeputy: getVal('summary-sig-resource-deputy'),
        director: getVal('summary-sig-director')
    };

    saveData();
}

function renderSummaryClaimSubjectSelector() {
    const term = appData.terms.find(t => t.id === currentSummaryTermId);
    const container = document.getElementById('summary-subjects-selector-list');
    const badge = document.getElementById('summary-selected-count-badge');
    if (!term || !container) return;

    container.innerHTML = '';

    if (term.subjects.length === 0) {
        container.innerHTML = `
            <div class="p-4 text-center text-xs text-gray-500 bg-[#0f121d] rounded-lg border border-[#2d3748]">
                <i class="fa-solid fa-triangle-exclamation text-amber-400 mb-1 block"></i>
                ยังไม่มีรายวิชาในภาคเรียนนี้ กรุณาเพิ่มรายวิชาในเทอมก่อน
            </div>
        `;
        if (badge) {
            badge.innerHTML = `<span>เลือก 0 รายวิชา</span><span>ยอดรวม: 0.00 บาท</span>`;
        }
        return;
    }

    let selectedCount = 0;
    let selectedMoney = 0;

    term.subjects.forEach(sub => {
        const info = getSubjectClaimSummary(sub);
        const isChecked = summaryClaimSelectedSubIds.has(sub.id);

        if (isChecked) {
            selectedCount++;
            selectedMoney += info.totalMoney;
        }

        const card = document.createElement('label');
        card.className = `p-2.5 rounded-lg border text-xs flex items-start gap-2.5 cursor-pointer transition ${isChecked ? 'bg-orange-950/20 border-orange-500/50 text-white' : 'bg-[#0f121d] border-[#2d3748] text-gray-400 hover:border-gray-500'}`;
        card.innerHTML = `
            <input type="checkbox" class="chk-summary-sub accent-orange-500 rounded mt-0.5" data-sub-id="${sub.id}" ${isChecked ? 'checked' : ''}>
            <div class="flex-1 overflow-hidden">
                <div class="flex justify-between items-center mb-0.5">
                    <span class="font-bold text-white text-[12px] truncate">${info.name}</span>
                    <span class="font-mono text-orange-300 font-bold ml-2">${formatMoney(info.totalMoney)} บ.</span>
                </div>
                <div class="text-[11px] text-gray-400 flex items-center justify-between">
                    <span>รหัส: ${info.code || '-'} | ผู้สอน: ${info.teacherName}</span>
                    <span>${info.hours} ชม. (${info.rate} บ.)</span>
                </div>
            </div>
        `;

        const chk = card.querySelector('.chk-summary-sub');
        chk.addEventListener('change', () => {
            if (chk.checked) {
                summaryClaimSelectedSubIds.add(sub.id);
            } else {
                summaryClaimSelectedSubIds.delete(sub.id);
            }
            saveSummaryClaimState();
            renderSummaryClaimSubjectSelector();
            renderSummaryClaimA4();
        });

        container.appendChild(card);
    });

    if (badge) {
        badge.innerHTML = `
            <span>เลือก ${selectedCount} จาก ${term.subjects.length} รายวิชา</span>
            <span>ยอดรวม: ${formatMoney(selectedMoney)} บาท</span>
        `;
    }
}

function parseThaiDateComponents(str, fallbackYear = '2568') {
    if (!str || !String(str).trim()) {
        return { day: '.....', month: '..................', year: '........' };
    }
    
    let s = String(str).trim();

    // 1. Check DD/MM/YYYY
    if (s.includes('/')) {
        const parts = s.split('/');
        if (parts.length >= 3) {
            const d = parseInt(parts[0].trim()) || parts[0].trim();
            const mIdx = parseInt(parts[1].trim()) - 1;
            const m = (mIdx >= 0 && mIdx < 12 && THAI_MONTHS_FULL[mIdx]) ? THAI_MONTHS_FULL[mIdx] : parts[1].trim();
            let y = parseInt(parts[2].trim()) || parts[2].trim();
            if (typeof y === 'number' && y < 2500) y += 543;
            return { day: String(d), month: m, year: String(y) };
        }
    }

    // 2. Check YYYY-MM-DD
    if (s.includes('-')) {
        const p = s.split('-');
        if (p.length === 3 && p[0].length === 4) {
            let y = parseInt(p[0]);
            if (y < 2500) y += 543;
            const mIdx = parseInt(p[1]) - 1;
            const m = (mIdx >= 0 && mIdx < 12 && THAI_MONTHS_FULL[mIdx]) ? THAI_MONTHS_FULL[mIdx] : p[1];
            const d = parseInt(p[2]);
            return { day: String(d), month: m, year: String(y) };
        }
    }

    // 3. Month extraction (search full names first, then short abbreviations)
    let foundMonth = '';
    const thaiMonthsShort = [
        'ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.',
        'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'
    ];

    for (let i = 0; i < THAI_MONTHS_FULL.length; i++) {
        if (s.includes(THAI_MONTHS_FULL[i])) {
            foundMonth = THAI_MONTHS_FULL[i];
            s = s.replace(THAI_MONTHS_FULL[i], ' ');
            break;
        }
    }
    if (!foundMonth) {
        for (let i = 0; i < thaiMonthsShort.length; i++) {
            if (s.includes(thaiMonthsShort[i])) {
                foundMonth = THAI_MONTHS_FULL[i];
                s = s.replace(thaiMonthsShort[i], ' ');
                break;
            }
        }
    }

    // 4. Year extraction (4-digit number: 25xx or 20xx)
    let foundYear = '';
    const yearMatch = s.match(/\b(25\d{2}|20\d{2}|\d{4})\b/);
    if (yearMatch) {
        let yVal = parseInt(yearMatch[1]);
        if (yVal < 2500) yVal += 543;
        foundYear = String(yVal);
        s = s.replace(yearMatch[0], ' ');
    } else {
        foundYear = String(fallbackYear || '2568');
    }

    // Clean Thai prefix words like วันที่, วัน, เดือน, พ.ศ., พศ
    s = s.replace(/(วันที่|วัน|เดือน|พ\.ศ\.|พศ)/g, ' ');

    // 5. Day extraction (1-31)
    let foundDay = '';
    const dayMatch = s.match(/\b([1-9]|[12]\d|3[01])\b/);
    if (dayMatch) {
        foundDay = String(parseInt(dayMatch[1]));
    } else {
        foundDay = s.trim() || '.....';
    }

    return {
        day: foundDay || '.....',
        month: foundMonth || '..................',
        year: foundYear || '........'
    };
}

// -------------------------------------------------------------------------
// DYNAMIC TERM DATE RANGE CALCULATION (คำนวณช่วงวันที่เบิกจริงจากรายวิชา)
// -------------------------------------------------------------------------
function getTermEffectiveDateRange(term, selectedSubIds = null) {
    if (!term || !term.subjects || term.subjects.length === 0) {
        return {
            startDateStr: `1 ${THAI_MONTHS_FULL[5]} พ.ศ. ${term ? term.year : 2568}`,
            endDateStr: `30 ${THAI_MONTHS_FULL[8]} พ.ศ. ${term ? term.year : 2568}`
        };
    }

    const subIdsToInclude = selectedSubIds && selectedSubIds.length > 0 
        ? selectedSubIds 
        : term.subjects.map(s => s.id);
    const subs = term.subjects.filter(s => subIdsToInclude.includes(s.id));
    const targetSubs = subs.length > 0 ? subs : term.subjects;

    let minDateObj = null;
    let minDateStr = '';
    let maxDateObj = null;
    let maxDateStr = '';

    targetSubs.forEach(sub => {
        const claim = (typeof ensureSubjectClaimData === 'function')
            ? ensureSubjectClaimData(term, sub)
            : (sub.claimData || {});

        // 1. Check start date
        let subStartDateObj = null;
        if (claim.startDate) {
            const d = new Date(claim.startDate);
            if (!isNaN(d.getTime())) subStartDateObj = d;
        }
        if (!subStartDateObj && claim.weeks && claim.weeks.length > 0 && claim.weeks[0].date) {
            const d = new Date(claim.weeks[0].date);
            if (!isNaN(d.getTime())) subStartDateObj = d;
        }

        if (subStartDateObj) {
            if (!minDateObj || subStartDateObj.getTime() < minDateObj.getTime()) {
                minDateObj = subStartDateObj;
                minDateStr = formatThaiDateFull(subStartDateObj);
            }
        }

        // 2. Check end date
        let subEndDateObj = null;
        let subEndThai = claim.endDateThai;

        if (claim.weeks && claim.weeks.length > 0) {
            for (let i = claim.weeks.length - 1; i >= 0; i--) {
                if (claim.weeks[i].date) {
                    const d = new Date(claim.weeks[i].date);
                    if (!isNaN(d.getTime())) {
                        subEndDateObj = d;
                        break;
                    }
                }
            }
        }

        if (!subEndDateObj && subEndThai) {
            const comp = parseThaiDateComponents(subEndThai, term.year);
            if (comp.month && comp.day && !isNaN(parseInt(comp.day))) {
                const mIdx = THAI_MONTHS_FULL.indexOf(comp.month);
                let yCe = parseInt(comp.year);
                if (yCe > 2400) yCe -= 543;
                if (mIdx >= 0 && !isNaN(yCe)) {
                    subEndDateObj = new Date(yCe, mIdx, parseInt(comp.day));
                }
            }
        }

        if (subEndDateObj) {
            if (!maxDateObj || subEndDateObj.getTime() > maxDateObj.getTime()) {
                maxDateObj = subEndDateObj;
                maxDateStr = (subEndThai && subEndThai.includes('เดือน')) 
                    ? subEndThai 
                    : formatThaiDateFull(subEndDateObj);
            }
        } else if (subEndThai && !maxDateStr) {
            maxDateStr = subEndThai;
        }
    });

    return {
        startDateStr: minDateStr || (targetSubs[0]?.claimData?.startDate ? formatThaiDateFull(targetSubs[0].claimData.startDate) : `1 มิถุนายน พ.ศ. ${term.year}`),
        endDateStr: maxDateStr || (targetSubs[0]?.claimData?.endDateThai || `30 กันยายน พ.ศ. ${term.year}`)
    };
}

function generateSummaryClaimA4HTML(term, selectedSubIds = null) {
    if (!term) return '';
    const state = term.summaryClaimData || {};

    // Calculate effective date range from subjects (or selected subjects)
    const effectiveDates = getTermEffectiveDateRange(term, selectedSubIds);

    // Only read from DOM if #modal-summary-claim is currently open for THIS term
    const isSummaryModalOpenForThisTerm = 
        (typeof currentSummaryTermId !== 'undefined' && currentSummaryTermId === term.id) &&
        Boolean(document.getElementById('modal-summary-claim')?.classList.contains('active'));

    const getVal = (id, fallback) => {
        if (isSummaryModalOpenForThisTerm) {
            const v = document.getElementById(id)?.value;
            if (v !== undefined && v !== null && v.trim() !== '') return v.trim();
        }
        return fallback;
    };

    const deptHeader = getVal('summary-input-dept', state.deptHeader || 'สาขาวิชาโยธา  วิทยาลัยเทคนิคอุบลราชธานี');
    const docNo = getVal('summary-input-doc-no', state.docNo || '');
    const docDate = getVal('summary-input-doc-date', state.docDate || '');
    const subjectTitle = getVal('summary-input-subject-title', state.docSubject || 'ขอเบิกค่าสอนระดับปริญญาตรี');
    const recipient = getVal('summary-input-recipient', state.recipient || 'ผู้อำนวยการวิทยาลัยเทคนิคอุบลราชธานี');

    // Default requester and department from first subject or term
    let defaultDept = 'เทคโนโลยีโยธา';
    let defaultRequester = 'นายณัฐวรรธน์ เกษกุล';
    let defaultLevel = '1';

    if (term.subjects && term.subjects.length > 0) {
        const firstSub = term.subjects[0];
        const claim = (typeof ensureSubjectClaimData === 'function') 
            ? ensureSubjectClaimData(term, firstSub) 
            : (firstSub.claimData || {});
        if (claim) {
            if (claim.department) defaultDept = claim.department;
            if (claim.teacherName) defaultRequester = claim.teacherName;
            if (claim.level) defaultLevel = claim.level.replace(/[^0-9]/g, '') || '1';
        }
    }

    const requester = getVal('summary-input-requester', state.requesterName || defaultRequester);
    const role = getVal('summary-input-role', state.requesterRole || 'อาจารย์');
    const deptName = getVal('summary-input-dept-name', state.department || defaultDept);
    const level = getVal('summary-input-level', state.classLevel || defaultLevel);
    const percent = getVal('summary-input-percent', state.percent || '60');
    
    // Ensure termYearStr matches term
    const defaultTermYear = (state.termYearStr && state.termYearStr.includes(String(term.no))) 
        ? state.termYearStr 
        : `${term.no}  /   ${term.year}`;
    const termYearStr = getVal('summary-input-term-year', defaultTermYear);

    // Ensure dates are updated and not stale dummy values
    const isStaleStartDate = !state.startDateStr || 
        state.startDateStr.includes('2 มิถุนายน') || 
        state.startDateStr.includes('มิถุนายน 2568');
    const isStaleEndDate = !state.endDateStr || 
        state.endDateStr.includes('29 กันยายน') || 
        state.endDateStr.includes('4 ตุลาคม 2568');

    const fallbackStart = (isStaleStartDate || !isSummaryModalOpenForThisTerm) 
        ? effectiveDates.startDateStr 
        : (state.startDateStr || effectiveDates.startDateStr);
    const fallbackEnd = (isStaleEndDate || !isSummaryModalOpenForThisTerm) 
        ? effectiveDates.endDateStr 
        : (state.endDateStr || effectiveDates.endDateStr);

    const startDateStr = getVal('summary-input-start-date', fallbackStart);
    const endDateStr = getVal('summary-input-end-date', fallbackEnd);

    // Parse date components
    const startComp = parseThaiDateComponents(startDateStr, term ? term.year : 2568);
    const endComp = parseThaiDateComponents(endDateStr, term ? term.year : 2568);

    // Split deptHeader into left (department) and right (college) if present
    let deptLeft = 'สาขาวิชาโยธา';
    let deptRight = 'วิทยาลัยเทคนิคอุบลราชธานี';
    if (deptHeader.includes('วิทยาลัย')) {
        const parts = deptHeader.split('วิทยาลัย');
        deptLeft = parts[0].trim() || 'สาขาวิชาโยธา';
        deptRight = 'วิทยาลัย' + parts.slice(1).join('วิทยาลัย').trim();
    } else {
        deptLeft = deptHeader;
        deptRight = '';
    }

    // Signatures (ดึงค่าเริ่มต้นจากเทอมแรกผ่าน getDefaultSignatures2To9)
    const sig = state.signatures || {};
    const defSig = (typeof getDefaultSignatures2To9 === 'function') ? getDefaultSignatures2To9() : {};
    const sigRequester = getVal('summary-sig-requester', sig.requester || requester);
    const sigDeptHead = getVal('summary-sig-dept-head', sig.deptHead || defSig.deptHead || 'นายปริวัฒน์ ยืนยิ่ง');
    const sigVerifier = getVal('summary-sig-verifier', sig.verifier || defSig.curriculumHead || 'นายชนะ   สุทธิประภา');
    const sigVerifierRole = getVal('summary-sig-verifier-role', sig.verifierRole || defSig.curriculumHeadRole || 'หัวหน้างานพัฒนาหลักสูตรสายเทคโนโลยีหรือสายปฏิบัติการ');
    const sigAcademic = getVal('summary-sig-academic-deputy', sig.academicDeputy || defSig.academicDeputy || 'นายสุวิชา  มั่นยืน');
    const sigResource = getVal('summary-sig-resource-deputy', sig.resourceDeputy || defSig.resourceDeputy || 'นางสาวสายฝน  สาระผล');
    const sigDirector = getVal('summary-sig-director', sig.director || defSig.director || 'นายธาตรี  พิบูลมณฑา');

    // Filter selected subjects
    const subIdsToInclude = selectedSubIds ? selectedSubIds : (term.subjects.map(s => s.id));
    const selectedSubs = term.subjects.filter(s => subIdsToInclude.includes(s.id));

    // Determine teacher column width based on the longest teacher name
    const measureCanvas = document.createElement('canvas');
    const measureCtx = measureCanvas.getContext('2d');
    measureCtx.font = '14pt "TH Sarabun New", "TH Sarabun PSK", Sarabun, sans-serif';

    let maxTeacherWidth = 0;
    selectedSubs.forEach(sub => {
        const info = getSubjectClaimSummary(sub, term);
        const w = measureCtx.measureText(info.teacherName || '').width;
        if (w > maxTeacherWidth) maxTeacherWidth = w;
    });
    // Add cell padding (padding: 2px 4px -> 8px horizontal + 4px safety)
    const teacherColWidth = Math.max(90, Math.min(140, Math.ceil(maxTeacherWidth + 12)));

    // Measure non-subject columns:
    // col 1 (ที่): 22px
    // col 2 (ชื่อ-สกุล): teacherColWidth
    // col 4 (หน่วยกิต): 36px
    // col 5 (จำนวน นศ.): 44px
    // col 6 (ชั่วโมง): 34px
    // col 7 (อัตรา/ชม.): 40px
    // col 8 (เป็นเงิน): 66px
    // Printable A4 content width is ~604.7px.
    // Non-subject columns sum = 22 + teacherColWidth + 36 + 44 + 34 + 40 + 66 = 242 + teacherColWidth.
    const maxSubjectTextWidth = Math.max(160, 604.7 - (242 + teacherColWidth) - 8);

    let sumCredits = 0;
    let sumStudents = 0;
    let sumHours = 0;
    let sumMoney = 0;
    let representativeRate = 42;

    let rowsHtml = '';
    selectedSubs.forEach((sub, idx) => {
        const info = getSubjectClaimSummary(sub, term);
        sumCredits += (parseInt(info.credits) || 0);
        sumStudents = Math.max(sumStudents, (parseInt(info.students) || 0));
        sumHours += (parseInt(info.hours) || 0);
        sumMoney += (parseFloat(info.totalMoney) || 0);
        representativeRate = info.rate || representativeRate;

        // Auto calculate font size for subject name from 13.5pt down to 6.5pt
        let bestSubjectFontSizePt = 6.5;
        for (let pt = 13.5; pt >= 6.5; pt -= 0.25) {
            measureCtx.font = `${pt}pt "TH Sarabun New", "TH Sarabun PSK", Sarabun, sans-serif`;
            if (measureCtx.measureText(info.name || '').width <= maxSubjectTextWidth) {
                bestSubjectFontSizePt = pt;
                break;
            }
        }

        // Auto calculate font size for teacher name if needed
        let bestTeacherFontSizePt = 13.5;
        for (let pt = 13.5; pt >= 8.5; pt -= 0.25) {
            measureCtx.font = `${pt}pt "TH Sarabun New", "TH Sarabun PSK", Sarabun, sans-serif`;
            if (measureCtx.measureText(info.teacherName || '').width <= (teacherColWidth - 8)) {
                bestTeacherFontSizePt = pt;
                break;
            }
        }

        rowsHtml += `
            <tr style="height: 28px;">
                <td style="text-align: center; border: 1px solid #000; padding: 2px 1px; font-size: 11.5pt;">${idx + 1}</td>
                <td class="summary-teacher-cell" style="border: 1px solid #000; padding: 2px 3px; white-space: nowrap; overflow: hidden; vertical-align: middle;">
                    <span class="summary-teacher-text" data-pt="${bestTeacherFontSizePt}" style="display: inline-block; white-space: nowrap; font-size: ${bestTeacherFontSizePt}pt; line-height: 1.15;">${info.teacherName}</span>
                </td>
                <td class="summary-subject-cell" style="border: 1px solid #000; padding: 2px 3px; white-space: nowrap; overflow: hidden; vertical-align: middle;">
                    <span class="summary-subject-text" data-pt="${bestSubjectFontSizePt}" style="display: inline-block; white-space: nowrap; font-size: ${bestSubjectFontSizePt}pt; line-height: 1.15;">${info.name}</span>
                </td>
                <td style="text-align: center; border: 1px solid #000; padding: 2px 1px; font-size: 11.5pt;">${info.credits}</td>
                <td style="text-align: center; border: 1px solid #000; padding: 2px 1px; font-size: 11.5pt;">${info.students}</td>
                <td style="text-align: center; border: 1px solid #000; padding: 2px 1px; font-size: 11.5pt;">${info.hours}</td>
                <td style="text-align: center; border: 1px solid #000; padding: 2px 1px; font-size: 11.5pt;">${info.rate}</td>
                <td style="text-align: right; border: 1px solid #000; padding: 2px 4px; font-size: 11.5pt; white-space: nowrap;">${formatMoney(info.totalMoney)}</td>
            </tr>
        `;
    });

    // If empty
    if (selectedSubs.length === 0) {
        rowsHtml = `
            <tr>
                <td colspan="8" style="text-align: center; padding: 18px; color: #888; border: 1px solid #000;">
                    (ยังไม่ได้เลือกรายวิชาที่ต้องการเบิก กรุณาติ๊กเลือกวิชาในแถบด้านซ้าย)
                </td>
            </tr>
        `;
    }

    // Totals Row
    const totalsRowHtml = `
        <tr style="height: 28px; font-weight: bold; background-color: #fafafa;">
            <td colspan="3" style="text-align: center; border: 1px solid #000; padding: 2px 4px; font-size: 12.5pt;">รวม</td>
            <td style="text-align: center; border: 1px solid #000; padding: 2px 1px; font-size: 11.5pt;">${sumCredits}</td>
            <td style="text-align: center; border: 1px solid #000; padding: 2px 1px; font-size: 11.5pt;">${sumStudents || (selectedSubs.length > 0 ? 6 : 0)}</td>
            <td style="text-align: center; border: 1px solid #000; padding: 2px 1px; font-size: 11.5pt;">${sumHours}</td>
            <td style="text-align: center; border: 1px solid #000; padding: 2px 1px; font-size: 11.5pt;">${selectedSubs.length > 0 ? representativeRate : ''}</td>
            <td style="text-align: right; border: 1px solid #000; padding: 2px 4px; font-size: 11.5pt; white-space: nowrap;">${formatMoney(sumMoney)}</td>
        </tr>
    `;

    return `
        <div style="font-family: 'TH Sarabun New', 'TH Sarabun PSK', 'Sarabun', Tahoma, sans-serif; color: #000000; line-height: 1.35; font-size: 14pt; padding: 0;">
            
            <!-- Garuda Crest Header (Top Left Garuda, Center Title) -->
            <div style="position: relative; min-height: 68px; margin-bottom: 4px;">
                <img src="ตราครุฑ.jpg" alt="ตราครุฑ" style="width: 64px; height: auto; position: absolute; left: 0; top: 0;">
                <div style="text-align: center; font-size: 33px; font-weight: bold; padding-top: 10px; letter-spacing: 0.5px;">
                    บันทึกข้อความ
                </div>
            </div>

            <!-- Official Header Fields -->
            <div style="font-size: 14pt; margin-bottom: 5px; display: flex; align-items: flex-end;">
                <span style="font-weight: bold; width: 85px; flex-shrink: 0; padding-bottom: 1px;">ส่วนราชการ</span>
                <div style="flex: 1; border-bottom: 1px dotted #333; display: flex; justify-content: space-between; align-items: flex-end; padding: 0 4px 1px 6px; line-height: 1.2; min-height: 22px;">
                    <span style="white-space: nowrap;">${deptLeft}</span>
                    <span style="white-space: nowrap;">${deptRight}</span>
                </div>
            </div>

            <div style="display: flex; font-size: 14pt; margin-bottom: 5px; align-items: flex-end;">
                <div style="width: 50%; display: flex; align-items: flex-end; padding-right: 14px;">
                    <span style="font-weight: bold; width: 24px; flex-shrink: 0; padding-bottom: 1px;">ที่</span>
                    <div style="flex: 1; border-bottom: 1px dotted #333; padding: 0 4px 1px 6px; line-height: 1.2; min-height: 22px; white-space: nowrap;">
                        ${docNo || ''}
                    </div>
                </div>
                <div style="width: 50%; display: flex; align-items: flex-end;">
                    <span style="font-weight: bold; width: 44px; flex-shrink: 0; padding-bottom: 1px;">วันที่</span>
                    <div style="flex: 1; border-bottom: 1px dotted #333; padding: 0 4px 1px 6px; line-height: 1.2; min-height: 22px; white-space: nowrap;">
                        ${docDate || ''}
                    </div>
                </div>
            </div>

            <div style="display: flex; align-items: flex-end; font-size: 14pt; margin-bottom: 5px;">
                <span style="font-weight: bold; width: 50px; flex-shrink: 0; padding-bottom: 1px;">เรื่อง</span>
                <div style="flex: 1; border-bottom: 1px dotted #333; padding: 0 4px 1px 6px; line-height: 1.2; min-height: 22px; white-space: nowrap;">
                    ${subjectTitle || ''}
                </div>
            </div>

            <div style="display: flex; align-items: flex-end; font-size: 14pt; margin-bottom: 12px;">
                <span style="font-weight: bold; width: 50px; flex-shrink: 0; padding-bottom: 1px;">เรียน</span>
                <div style="flex: 1; border-bottom: 1px dotted #333; padding: 0 4px 1px 6px; line-height: 1.2; min-height: 22px; white-space: nowrap;">
                    ${recipient || ''}
                </div>
            </div>

            <!-- Body Paragraph with Indent -->
            <div style="text-align: justify; text-indent: 110px; font-size: 14pt; line-height: 1.35; margin-bottom: 10px;">
                ด้วย ${requester} ตำแหน่ง ${role} สาขาวิชา ${deptName} ขออนุญาตเบิกค่าสอนระดับปริญญาตรี จำนวน ${percent}% ของยอดนักศึกษาที่จ่ายเงินลงทะเบียนเรียน ระดับ ปริญญาตรี ชั้นปีที่ ${level} สาขาวิชา ${deptName} ประจำภาคเรียนที่ ${termYearStr} ระหว่าง วันที่ ${startComp.day} เดือน ${startComp.month} พ.ศ. ${startComp.year} ถึง วันที่ ${endComp.day} เดือน ${endComp.month} พ.ศ. ${endComp.year} รายละเอียดต่อไปนี้
            </div>

            <!-- Table (8 Columns) -->
            <table class="doc-table" style="width: 100%; table-layout: fixed; border-collapse: collapse; font-size: 14pt; margin-bottom: 6px;">
                <colgroup>
                    <col style="width: 22px;">
                    <col style="width: ${teacherColWidth}px;">
                    <col>
                    <col style="width: 36px;">
                    <col style="width: 44px;">
                    <col style="width: 34px;">
                    <col style="width: 40px;">
                    <col style="width: 66px;">
                </colgroup>
                <thead>
                    <tr style="background-color: #f3f4f6; font-weight: bold; text-align: center; height: 28px; line-height: 1.15;">
                        <th style="border: 1px solid #000; padding: 2px 1px; white-space: nowrap; font-size: 10.5pt;">ที่</th>
                        <th style="border: 1px solid #000; padding: 2px 2px; white-space: nowrap; font-size: 10.5pt;">ชื่อ - สกุล</th>
                        <th style="border: 1px solid #000; padding: 2px 3px; white-space: nowrap; font-size: 10.5pt;">ชื่อวิชา</th>
                        <th style="border: 1px solid #000; padding: 2px 1px; white-space: nowrap; font-size: 10.5pt;">หน่วยกิต</th>
                        <th style="border: 1px solid #000; padding: 2px 1px; white-space: nowrap; font-size: 9.5pt;">จำนวน นศ.</th>
                        <th style="border: 1px solid #000; padding: 2px 1px; white-space: nowrap; font-size: 10.5pt;">ชั่วโมง</th>
                        <th style="border: 1px solid #000; padding: 2px 1px; white-space: nowrap; font-size: 10pt;">อัตรา/ชม.</th>
                        <th style="border: 1px solid #000; padding: 2px 2px; white-space: nowrap; font-size: 10.5pt;">เป็นเงิน</th>
                    </tr>
                </thead>
                <tbody>
                    ${rowsHtml}
                    ${totalsRowHtml}
                </tbody>
            </table>

            <div style="text-indent: 110px; font-size: 14pt; margin-top: 6px; margin-bottom: 8px; line-height: 1.35;">
                จึงเรียนมาเพื่อโปรดพิจารณาอนุมัติ
            </div>

            <!-- Signatures Block -->
            <div style="font-size: 14pt; line-height: 1.3; margin-top: 10px;">
                
                <!-- Row 1: ผู้ขอเบิก & หัวหน้าสาขาวิชา -->
                <div style="display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 10px;">
                    <div style="width: 48%; text-align: center;">
                        ลงชื่อ .................................................... ผู้ขอเบิก<br>
                        <span style="display: inline-block; margin-top: 3px;">(${sigRequester})</span>
                    </div>
                    <div style="width: 48%; text-align: center;">
                        ลงชื่อ .................................................... หัวหน้าสาขาวิชา<br>
                        <span style="display: inline-block; margin-top: 3px;">(${sigDeptHead})</span>
                    </div>
                </div>

                <!-- Row 2: ผู้ตรวจสอบ (Centered) -->
                <div style="text-align: center; margin-bottom: 10px;">
                    ลงชื่อ ..................................................... ผู้ตรวจสอบ<br>
                    <span style="display: inline-block; margin-top: 3px;">(${sigVerifier})</span><br>
                    ${sigVerifierRole}
                </div>

                <!-- Row 3: รองฯ ฝ่ายวิชาการ & รองฯ ฝ่ายบริหารทรัพยากร -->
                <div style="display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 10px;">
                    <div style="width: 48%; text-align: center;">
                        <strong style="font-weight: bold;">เห็นควรลงนามอนุมัติดังเสนอ</strong><br>
                        <span style="display: inline-block; margin-top: 3px;">ลงชื่อ ......................................................</span><br>
                        <span style="display: inline-block; margin-top: 3px;">(${sigAcademic})</span><br>
                        รองผู้อำนวยการฝ่ายวิชาการ
                    </div>
                    <div style="width: 48%; text-align: center;">
                        <strong style="font-weight: bold;">ควรอนุมัติให้จ่ายได้</strong><br>
                        <span style="display: inline-block; margin-top: 3px;">ลงชื่อ ..................................................................</span><br>
                        <span style="display: inline-block; margin-top: 3px;">(${sigResource})</span><br>
                        รองผู้อำนวยการฝ่ายบริหารทรัพยากร
                    </div>
                </div>

                <!-- Row 4: ผู้อำนวยการวิทยาลัยเทคนิคอุบลราชธานี (Centered) -->
                <div style="text-align: center;">
                    <strong style="font-weight: bold;">อนุมัติให้เบิกจ่ายได้</strong><br>
                    <span style="display: inline-block; margin-top: 3px;">ลงชื่อ .........................................................</span><br>
                    <span style="display: inline-block; margin-top: 3px;">(${sigDirector})</span><br>
                    ผู้อำนวยการวิทยาลัยเทคนิคอุบลราชธานี
                </div>

            </div>

        </div>
    `;
}

function fitSummaryClaimTableFonts(container) {
    if (!container) return;
    // Fit subject name cells
    container.querySelectorAll('.summary-subject-cell').forEach(cell => {
        const textSpan = cell.querySelector('.summary-subject-text');
        if (!textSpan) return;
        const cellWidth = cell.clientWidth;
        if (cellWidth <= 0) return;
        const computed = window.getComputedStyle(cell);
        const pad = (parseFloat(computed.paddingLeft) || 0) + (parseFloat(computed.paddingRight) || 0);
        const avail = cellWidth - pad - 1;
        if (avail > 30) {
            let curPt = parseFloat(textSpan.getAttribute('data-pt')) || 13;
            while (textSpan.offsetWidth > avail && curPt > 6.0) {
                curPt -= 0.25;
                textSpan.style.fontSize = curPt + 'pt';
            }
        }
    });

    // Fit teacher name cells
    container.querySelectorAll('.summary-teacher-cell').forEach(cell => {
        const textSpan = cell.querySelector('.summary-teacher-text');
        if (!textSpan) return;
        const cellWidth = cell.clientWidth;
        if (cellWidth <= 0) return;
        const computed = window.getComputedStyle(cell);
        const pad = (parseFloat(computed.paddingLeft) || 0) + (parseFloat(computed.paddingRight) || 0);
        const avail = cellWidth - pad - 1;
        if (avail > 30) {
            let curPt = parseFloat(textSpan.getAttribute('data-pt')) || 13;
            while (textSpan.offsetWidth > avail && curPt > 7.0) {
                curPt -= 0.25;
                textSpan.style.fontSize = curPt + 'pt';
            }
        }
    });
}

function renderSummaryClaimA4() {
    const term = appData.terms.find(t => t.id === currentSummaryTermId);
    const paper = document.getElementById('summary-claim-paper');
    if (!term || !paper) return;

    paper.innerHTML = generateSummaryClaimA4HTML(term, Array.from(summaryClaimSelectedSubIds));
    fitSummaryClaimTableFonts(paper);
}

function printSummaryClaim() {
    document.body.classList.add('printing-summary-claim');
    window.print();
    setTimeout(() => {
        document.body.classList.remove('printing-summary-claim');
    }, 1000);
}

// -------------------------------------------------------------------------
// BATCH PRINT SYSTEM (ระบบสั่งพิมพ์เอกสารเลือกเทอม/รายวิชา/ใบเบิกรวม)
// -------------------------------------------------------------------------
let batchPrintSelectedSubIds = new Set();

function ensureSubjectClaimData(term, sub) {
    if (sub.claimData) {
        const c = JSON.parse(JSON.stringify(sub.claimData));
        if (!c.rateCustomized && term && term.hourlyRate) {
            c.rate = term.hourlyRate;
        }
        return c;
    }
    const masterSub = (appData.subjects_master || []).find(s => s.id === sub.subjectId) || {};
    const teacher = (appData.teachers || []).find(t => t.id === sub.teacherId) || {};
    const c = createInitialSubjectClaimData(term, masterSub, teacher);
    sub.claimData = JSON.parse(JSON.stringify(c));
    sub.hours = c.weeks.reduce((sum, w) => sum + (w.isHoliday ? 0 : (parseFloat(w.totalHrs) || 0)), 0);
    return c;
}

function initBatchPrintSystem() {
    const btnBatchPrint = document.getElementById('btn-batch-print');
    if (!btnBatchPrint) return;

    btnBatchPrint.addEventListener('click', openBatchPrintModal);

    const termSelect = document.getElementById('batch-print-term-select');
    if (termSelect) {
        termSelect.addEventListener('change', () => {
            renderBatchPrintOptions(termSelect.value);
        });
    }

    const btnSelectAll = document.getElementById('btn-batch-select-all');
    if (btnSelectAll) {
        btnSelectAll.addEventListener('click', () => {
            const termId = document.getElementById('batch-print-term-select')?.value;
            const term = appData.terms.find(t => t.id === termId);
            if (term) {
                term.subjects.forEach(s => batchPrintSelectedSubIds.add(s.id));
                updateBatchPrintCheckboxUI();
            }
        });
    }

    const btnDeselectAll = document.getElementById('btn-batch-deselect-all');
    if (btnDeselectAll) {
        btnDeselectAll.addEventListener('click', () => {
            batchPrintSelectedSubIds.clear();
            updateBatchPrintCheckboxUI();
        });
    }

    const chkSummary = document.getElementById('batch-print-check-summary');
    if (chkSummary) {
        chkSummary.addEventListener('change', updateBatchPrintTotalsBadge);
    }

    const chkP1 = document.getElementById('batch-print-page1-all');
    if (chkP1) {
        chkP1.addEventListener('change', updateBatchPrintTotalsBadge);
    }

    const chkP2 = document.getElementById('batch-print-page2-all');
    if (chkP2) {
        chkP2.addEventListener('change', updateBatchPrintTotalsBadge);
    }

    const btnExecute = document.getElementById('btn-batch-print-execute');
    if (btnExecute) {
        btnExecute.addEventListener('click', executeBatchPrint);
    }
}

function openBatchPrintModal() {
    const termSelect = document.getElementById('batch-print-term-select');
    if (!termSelect) return;

    if (!appData.terms || appData.terms.length === 0) {
        alert('ยังไม่มีภาคเรียนในระบบ กรุณาเพิ่มภาคเรียนก่อน');
        return;
    }

    termSelect.innerHTML = '';
    appData.terms.forEach(term => {
        const opt = document.createElement('option');
        opt.value = term.id;
        opt.textContent = `ภาคเรียนที่ ${term.no}/${term.year}`;
        termSelect.appendChild(opt);
    });

    const targetTermId = currentTermId || appData.terms[0].id;
    termSelect.value = targetTermId;

    renderBatchPrintOptions(targetTermId);
    openModal('modal-batch-print');
}

function renderBatchPrintOptions(termId) {
    const term = appData.terms.find(t => t.id === termId);
    const container = document.getElementById('batch-subjects-list');
    const subCountEl = document.getElementById('batch-term-sub-count');
    const moneyBadge = document.getElementById('batch-term-money-badge');

    if (!term || !container) return;

    // Ensure all subjects have claimData initialized
    term.subjects.forEach(sub => ensureSubjectClaimData(term, sub));

    container.innerHTML = '';
    // By default, select all subjects in this term
    batchPrintSelectedSubIds = new Set(term.subjects.map(s => s.id));

    let totalTermMoney = 0;
    term.subjects.forEach(sub => {
        const info = getSubjectClaimSummary(sub, term);
        totalTermMoney += info.totalMoney;
    });

    if (subCountEl) subCountEl.textContent = term.subjects.length;
    if (moneyBadge) moneyBadge.textContent = `${formatMoney(totalTermMoney)} บาท`;

    if (term.subjects.length === 0) {
        container.innerHTML = `
            <div class="p-4 text-center text-xs text-gray-500 bg-[#0f121d] rounded-lg border border-[#2d3748]">
                <i class="fa-solid fa-circle-exclamation text-amber-400 mb-1 block text-base"></i>
                ยังไม่มีรายวิชาในภาคเรียนนี้
            </div>
        `;
        updateBatchPrintTotalsBadge();
        return;
    }

    term.subjects.forEach(sub => {
        const info = getSubjectClaimSummary(sub, term);
        const card = document.createElement('label');
        card.id = `batch-sub-card-${sub.id}`;
        card.className = `p-3 rounded-xl border text-xs flex items-center justify-between gap-3 cursor-pointer transition bg-blue-950/20 border-blue-500/50 text-white`;
        card.innerHTML = `
            <div class="flex items-center gap-3 overflow-hidden flex-1">
                <input type="checkbox" class="batch-chk-subject w-4 h-4 rounded text-blue-500 focus:ring-blue-400 border-gray-600 bg-gray-700 cursor-pointer flex-shrink-0" data-sub-id="${sub.id}" checked>
                <div class="overflow-hidden flex-1">
                    <div class="font-bold text-white text-xs truncate">
                        ${info.name}
                        <span class="text-gray-400 font-normal ml-1">(${info.code || '-'})</span>
                    </div>
                    <div class="text-[11px] text-gray-400 mt-0.5 flex flex-wrap items-center gap-2">
                        <span><i class="fa-solid fa-user-tie text-[10px] text-blue-400 mr-1"></i>${info.teacherName}</span>
                        <span>•</span>
                        <span>${info.hours} ชม.</span>
                        <span>•</span>
                        <span>${info.students} คน</span>
                    </div>
                </div>
            </div>
            <div class="text-right flex-shrink-0">
                <span class="font-mono text-emerald-400 font-bold text-xs">${formatMoney(info.totalMoney)} บ.</span>
                <span class="block text-[10px] text-gray-400">อัตรา ${info.rate} บ./ชม.</span>
            </div>
        `;

        const chk = card.querySelector('.batch-chk-subject');
        chk.addEventListener('change', () => {
            if (chk.checked) {
                batchPrintSelectedSubIds.add(sub.id);
                card.className = `p-3 rounded-xl border text-xs flex items-center justify-between gap-3 cursor-pointer transition bg-blue-950/20 border-blue-500/50 text-white`;
            } else {
                batchPrintSelectedSubIds.delete(sub.id);
                card.className = `p-3 rounded-xl border text-xs flex items-center justify-between gap-3 cursor-pointer transition bg-[#0f121d] border-[#2d3748] text-gray-400 hover:border-gray-500`;
            }
            updateBatchPrintTotalsBadge();
        });

        container.appendChild(card);
    });

    updateBatchPrintTotalsBadge();
}

function updateBatchPrintCheckboxUI() {
    document.querySelectorAll('.batch-chk-subject').forEach(chk => {
        const subId = chk.getAttribute('data-sub-id');
        const isChecked = batchPrintSelectedSubIds.has(subId);
        chk.checked = isChecked;
        const card = document.getElementById(`batch-sub-card-${subId}`);
        if (card) {
            if (isChecked) {
                card.className = `p-3 rounded-xl border text-xs flex items-center justify-between gap-3 cursor-pointer transition bg-blue-950/20 border-blue-500/50 text-white`;
            } else {
                card.className = `p-3 rounded-xl border text-xs flex items-center justify-between gap-3 cursor-pointer transition bg-[#0f121d] border-[#2d3748] text-gray-400 hover:border-gray-500`;
            }
        }
    });
    updateBatchPrintTotalsBadge();
}

function updateBatchPrintTotalsBadge() {
    const isSummary = document.getElementById('batch-print-check-summary')?.checked || false;
    const isP1 = document.getElementById('batch-print-page1-all')?.checked || false;
    const isP2 = document.getElementById('batch-print-page2-all')?.checked || false;

    const termSelect = document.getElementById('batch-print-term-select');
    const term = termSelect ? appData.terms.find(t => t.id === termSelect.value) : null;

    if (term) {
        const effectiveDates = getTermEffectiveDateRange(term, Array.from(batchPrintSelectedSubIds));
        const dateTextEl = document.getElementById('batch-summary-dates-text');
        if (dateTextEl) {
            dateTextEl.textContent = `ช่วงวันที่เบิก: ${effectiveDates.startDateStr} ถึง ${effectiveDates.endDateStr}`;
        }
    }

    const subCount = batchPrintSelectedSubIds.size;
    const pagesPerSub = (isP1 ? 1 : 0) + (isP2 ? 1 : 0);
    const subPages = subCount * pagesPerSub;
    const summaryPages = isSummary ? 1 : 0;
    const totalPages = summaryPages + subPages;

    const badgeText = document.getElementById('batch-print-total-pages-text');
    if (badgeText) {
        if (totalPages === 0) {
            badgeText.textContent = '0 หน้า (ยังไม่ได้เลือกรายการ)';
        } else {
            let details = [];
            if (isSummary) details.push('ใบเบิกรวม 1 แผ่น');
            if (subCount > 0 && pagesPerSub > 0) details.push(`${subCount} รายวิชา (${subPages} แผ่น)`);
            badgeText.textContent = `รวมทั้งหมด ${totalPages} หน้า A4 (${details.join(' + ')})`;
        }
    }
}

function executeBatchPrint() {
    const termSelect = document.getElementById('batch-print-term-select');
    if (!termSelect) return;
    const termId = termSelect.value;
    const term = appData.terms.find(t => t.id === termId);
    if (!term) return alert('ไม่พบข้อมูลภาคเรียนที่เลือก');

    const printSummary = document.getElementById('batch-print-check-summary')?.checked || false;
    const printPage1 = document.getElementById('batch-print-page1-all')?.checked || false;
    const printPage2 = document.getElementById('batch-print-page2-all')?.checked || false;

    const selectedSubIds = Array.from(batchPrintSelectedSubIds);

    if (!printSummary && selectedSubIds.length === 0) {
        alert('กรุณาติ๊กเลือกอย่างน้อย 1 รายการ (ใบเบิกรวม หรือรายวิชา) เพื่อพิมพ์');
        return;
    }

    if (selectedSubIds.length > 0 && !printPage1 && !printPage2 && !printSummary) {
        alert('กรุณาเลือกหน้าที่ต้องการพิมพ์ (หน้า 1 หรือ หน้า 2)');
        return;
    }

    const batchContainer = document.getElementById('batch-print-container');
    if (!batchContainer) return;
    batchContainer.innerHTML = '';

    // 1. If Summary Claim is selected, append Summary Claim A4 paper
    if (printSummary) {
        const summaryPaper = document.createElement('div');
        summaryPaper.className = 'a4-paper summary-claim-paper';
        summaryPaper.innerHTML = generateSummaryClaimA4HTML(term, selectedSubIds.length > 0 ? selectedSubIds : null);
        batchContainer.appendChild(summaryPaper);
        fitSummaryClaimTableFonts(summaryPaper);
    }

    // 2. For each selected subject, append Page 1 and/or Page 2
    selectedSubIds.forEach(subId => {
        const sub = term.subjects.find(s => s.id === subId);
        if (!sub) return;
        const claim = ensureSubjectClaimData(term, sub);

        if (printPage1) {
            const p1 = document.createElement('div');
            p1.className = 'a4-paper doc-page-1';
            p1.style.fontSize = '14pt';
            p1.innerHTML = generateA4Page1HTML(claim);
            // font fit
            const totalLineEl = p1.querySelector('#p1-calc-total-line');
            if (totalLineEl) {
                let currentPt = 14;
                while (totalLineEl.scrollWidth > totalLineEl.clientWidth && currentPt > 8.5) {
                    currentPt -= 0.5;
                    totalLineEl.style.fontSize = currentPt + 'pt';
                }
            }
            batchContainer.appendChild(p1);
        }

        if (printPage2) {
            const p2 = document.createElement('div');
            p2.className = 'a4-paper doc-page-2';
            p2.style.fontSize = '14pt';
            p2.innerHTML = generateA4Page2HTML(claim);
            batchContainer.appendChild(p2);
        }
    });

    // 3. Trigger Print
    document.body.classList.add('printing-batch');

    setTimeout(() => {
        window.print();
    }, 150);

    const cleanup = () => {
        document.body.classList.remove('printing-batch');
        if (batchContainer) batchContainer.innerHTML = '';
        window.removeEventListener('afterprint', cleanup);
    };

    window.addEventListener('afterprint', cleanup);
    setTimeout(cleanup, 2500);
}

// -------------------------------------------------------------------------
// CLOUDFLARE PAGES REAL-TIME CLOUD SYNC ENGINE
// -------------------------------------------------------------------------
let cloudSyncStatus = 'offline'; // 'ready', 'syncing', 'setup_required', 'error', 'offline'
let cloudSyncDebounceTimer = null;

async function initCloudSync() {
    const btnSync = document.getElementById('btn-cloud-sync');
    const btnSyncNow = document.getElementById('btn-cloud-sync-now');
    const btnPull = document.getElementById('btn-cloud-pull-force');
    const btnPush = document.getElementById('btn-cloud-push-force');

    if (btnSync) {
        btnSync.onclick = () => {
            openModal('modal-cloud-sync');
        };
    }

    if (btnSyncNow) {
        btnSyncNow.onclick = async () => {
            await doCloudSync(true);
        };
    }

    if (btnPull) {
        btnPull.onclick = async () => {
            if (confirm('คุณต้องการดึงข้อมูลล่าสุดจาก Cloudflare มาทับข้อมูลในเครื่องนี้ใช่หรือไม่?')) {
                await doCloudPull();
            }
        };
    }

    if (btnPush) {
        btnPush.onclick = async () => {
            if (confirm('คุณต้องการส่งข้อมูลในเครื่องนี้ขึ้นไปแทนที่บน Cloudflare ใช่หรือไม่?')) {
                await doCloudPush(true);
            }
        };
    }

    // Check if running on Web (http / https)
    const isWeb = window.location.protocol.startsWith('http');
    if (!isWeb) {
        updateCloudSyncUI('offline', 'ในเครื่อง (Local)');
        return;
    }

    // Initial check and fetch on login/load
    await doCloudSync(false);
}

function updateCloudSyncUI(status, label, updatedAt) {
    cloudSyncStatus = status;
    const dot = document.getElementById('cloud-sync-dot');
    const text = document.getElementById('cloud-sync-text');
    const badge = document.getElementById('cloud-status-badge');
    const lastSyncText = document.getElementById('cloud-last-sync-text');

    if (dot && text) {
        if (status === 'ready') {
            dot.className = 'w-2.5 h-2.5 rounded-full bg-emerald-400';
            text.textContent = label || 'คลาวด์ซิงค์';
        } else if (status === 'syncing') {
            dot.className = 'w-2.5 h-2.5 rounded-full bg-amber-400 animate-ping';
            text.textContent = 'กำลังซิงค์...';
        } else if (status === 'setup_required') {
            dot.className = 'w-2.5 h-2.5 rounded-full bg-amber-400';
            text.textContent = 'รอผูก KV';
        } else if (status === 'error') {
            dot.className = 'w-2.5 h-2.5 rounded-full bg-red-400';
            text.textContent = 'ซิงค์ไม่สำเร็จ';
        } else {
            dot.className = 'w-2.5 h-2.5 rounded-full bg-gray-400';
            text.textContent = 'ในเครื่อง';
        }
    }

    if (badge) {
        if (status === 'ready') {
            badge.className = 'px-2.5 py-1 rounded-full text-xs font-medium bg-emerald-500/20 text-emerald-400 flex items-center gap-1.5';
            badge.innerHTML = '<span class="w-2 h-2 rounded-full bg-emerald-400"></span> เชื่อมต่อคลาวด์แล้ว';
        } else if (status === 'setup_required') {
            badge.className = 'px-2.5 py-1 rounded-full text-xs font-medium bg-amber-500/20 text-amber-300 flex items-center gap-1.5';
            badge.innerHTML = '<span class="w-2 h-2 rounded-full bg-amber-400"></span> รอผูก KV Namespace';
        } else if (status === 'error') {
            badge.className = 'px-2.5 py-1 rounded-full text-xs font-medium bg-red-500/20 text-red-400 flex items-center gap-1.5';
            badge.innerHTML = '<span class="w-2 h-2 rounded-full bg-red-400"></span> เกิดข้อผิดพลาด';
        } else {
            badge.className = 'px-2.5 py-1 rounded-full text-xs font-medium bg-gray-500/20 text-gray-400 flex items-center gap-1.5';
            badge.innerHTML = '<span class="w-2 h-2 rounded-full bg-gray-400"></span> โหมดในเครื่อง (ออฟไลน์)';
        }
    }

    if (lastSyncText && updatedAt) {
        const d = new Date(updatedAt);
        if (!isNaN(d.getTime())) {
            lastSyncText.textContent = d.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit', second: '2-digit' }) + ' (' + d.toLocaleDateString('th-TH') + ')';
        } else {
            lastSyncText.textContent = updatedAt;
        }
    }
}

async function doCloudSync(isManual = false) {
    if (!window.location.protocol.startsWith('http')) return;
    try {
        const u = currentUser ? currentUser.username : 'civilutc';
        updateCloudSyncUI('syncing');
        const res = await fetch(`/api/sync?user=${encodeURIComponent(u)}`);
        if (!res.ok) {
            updateCloudSyncUI('error', 'ซิงค์ผิดพลาด');
            return;
        }
        const json = await res.json();
        if (json.setupRequired) {
            updateCloudSyncUI('setup_required', 'รอผูก KV');
            return;
        }

        if (json.success) {
            if (json.data && (json.data.terms || json.data.teachers)) {
                const cloudTime = json.updatedAt ? new Date(json.updatedAt).getTime() : 0;
                const localTime = appData && appData.lastModified ? new Date(appData.lastModified).getTime() : 0;

                if (cloudTime > localTime) {
                    appData = json.data;
                    const key = getUserStorageKey(u);
                    localStorage.setItem(key, JSON.stringify(appData));
                    if (u === 'civilutc') {
                        localStorage.setItem('teachingFeeData', JSON.stringify(appData));
                    }
                    if (currentView === 'semesters') renderSemestersView();
                    if (typeof renderAnnualDaysChart === 'function') renderAnnualDaysChart();
                } else if (localTime > cloudTime || !json.data) {
                    await doCloudPush(false);
                }
            } else if (!json.data && appData && ((appData.terms && appData.terms.length > 0) || (appData.teachers && appData.teachers.length > 0))) {
                await doCloudPush(false);
            }

            const timeStr = json.updatedAt || new Date().toISOString();
            updateCloudSyncUI('ready', 'คลาวด์ซิงค์', timeStr);
            if (isManual) alert('ซิงค์ข้อมูลกับคลาวด์เรียบร้อยแล้ว!');
        }
    } catch (err) {
        console.warn('Cloud sync error:', err);
        updateCloudSyncUI('error', 'ซิงค์ไม่สำเร็จ');
    }
}

async function doCloudPush(showAlert = true) {
    if (!window.location.protocol.startsWith('http')) return;
    try {
        const u = currentUser ? currentUser.username : 'civilutc';
        updateCloudSyncUI('syncing');
        const now = new Date().toISOString();
        if (appData) {
            appData.lastModified = now;
            const key = getUserStorageKey(u);
            localStorage.setItem(key, JSON.stringify(appData));
            if (u === 'civilutc') {
                localStorage.setItem('teachingFeeData', JSON.stringify(appData));
            }
        }

        const res = await fetch('/api/sync', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ user: u, data: appData, updatedAt: now })
        });
        const json = await res.json();
        if (json.success) {
            updateCloudSyncUI('ready', 'คลาวด์ซิงค์', now);
            if (showAlert) alert('ส่งข้อมูลขึ้น Cloudflare KV เรียบร้อยแล้ว!');
        } else {
            updateCloudSyncUI('error');
            if (showAlert) alert('ส่งข้อมูลไม่สำเร็จ: ' + (json.message || json.error));
        }
    } catch (e) {
        updateCloudSyncUI('error');
        if (showAlert) alert('เชื่อมต่อคลาวด์ไม่สำเร็จ: ' + e.message);
    }
}

async function doCloudPull() {
    if (!window.location.protocol.startsWith('http')) return;
    try {
        const u = currentUser ? currentUser.username : 'civilutc';
        updateCloudSyncUI('syncing');
        const res = await fetch(`/api/sync?user=${encodeURIComponent(u)}`);
        const json = await res.json();
        if (json.success && json.data) {
            appData = json.data;
            const key = getUserStorageKey(u);
            localStorage.setItem(key, JSON.stringify(appData));
            if (u === 'civilutc') {
                localStorage.setItem('teachingFeeData', JSON.stringify(appData));
            }
            if (currentView === 'semesters') renderSemestersView();
            renderAnnualChart();
            updateCloudSyncUI('ready', 'คลาวด์ซิงค์', json.updatedAt || new Date().toISOString());
            alert('ดึงข้อมูลล่าสุดจาก Cloudflare เรียบร้อยแล้ว!');
        } else {
            alert('ไม่พบข้อมูลบนคลาวด์ หรือยังไม่ได้ผูก KV');
            updateCloudSyncUI('setup_required');
        }
    } catch (e) {
        alert('ดึงข้อมูลไม่สำเร็จ: ' + e.message);
        updateCloudSyncUI('error');
    }
}

function triggerAutoCloudSync() {
    if (!window.location.protocol.startsWith('http')) return;
    if (!currentUser) return;
    if (cloudSyncDebounceTimer) clearTimeout(cloudSyncDebounceTimer);
    cloudSyncDebounceTimer = setTimeout(() => {
        doCloudPush(false);
    }, 2500);
}
